return {
  [193515657134592] = "Ritual de mudança de fortuna.",
  [193515657104896] = "Beyonder Habilidades",
  [193515925581056] = "\"O Louco que não pertence a esta época\"... É uma sensação boa, bastante segura.",
  [598342094582784] = "Porta aberta",
  [813709740240384] = "Você está bem?",
  [813709740127232] = "Hum?",
  [813709739981312] = "Olá, aconteceu algo?",
  [1139301010114048] = "\"Todo mundo vai... inclusive eu.\" \n No momento em que você viu esta frase, você acordou do seu sonho sobressaltado.",
  [1139301010119168] = "Todos eles viram a cabeça um após o outro, olhando para você ao lado do assento “O Mundo”.",
  [1139095388578304] = "Obtenha pistas relevantes no bar",
  [1139094851813888] = "Identifique com cuidado",
  [1139094851683840] = "Explique honestamente",
  [1139094851688960] = "Sopa de Cogumelos",
  [993959585252864] = "Louvado seja o tolo",
  [1139165182948608] = "Vamos discutir os detalhes no escritório, {{PlayerName}} também pode vir.",
  [1139165182952704] = "A última vez que estive aqui, nem sabia como era Tingen, e agora...",
  [1139094851701760] = "Faça o que foi dito",
  [1139165182734592] = "Olá, capitão, sou o novo funcionário {{PlayerName}} que acabou de ingressar.",
  [1139165182968320] = "Huh, onde está minha carteira?",
  [1139165182837248] = "Devo modificar o encantamento para que a descrição de abertura aponte para <P_Yellow> me </> ?",
  [1139165182820864] = "Não é bom... O tempo de Rozanne em Tingen in the Mirror também atingiu um ponto crítico, sua consciência começou a se tornar caótica.",
  [1139165182780672] = "Por que parece... nem tão novo quanto aquele que o carteiro dirige?",
  [1139165182414848] = "Suspeito que este caderno seja um item maligno com um certo grau de vida e inteligência. É muito perigoso mantê-lo em nossas mãos.",
  [1139301010210560] = "Você está prestes a andar de bicicleta para levar o jornaleiro até o próximo missão local, vivenciando os costumes locais das ruas de Tingen, o que levará cerca de 1 a 2 minutos.\n Quer optar por viajar rapidamente?",
  [1139165182246400] = "Você sabe, em ocasiões sociais formais, o preço de suas roupas, cartola e até cinto pode afetar seu valor aos olhos dos outros.",
  [1139301010210304] = "[Animação de espaço reservado] Os três saem felizes e entram em uma carruagem em direção à Rua Fania.",
  [1139165181919744] = "Lembre-se de proteger seu cabelo, não acabe como Dunn.",
  [1139165181841920] = "<P_Heart> (Gorgolejo————) </>",
  [1139165182708224] = "Obrigado, Sr. Tolo. Você sabe o que aconteceu agora?",
  [1139165182586368] = "Está tão escuro que preciso acender a luz primeiro.",
  [1139165182445056] = "Melissa ainda não voltou? Mas ela deveria estar em breve.",
  [1139165182312960] = "Certo, sou um Vidente!",
  [1139165182296576] = "Eu, vou esperar ele voltar para casa!",
  [1139301010210048] = "Depois de algumas rodadas de \"luta contra o mal\" tensas e emocionantes...",
  [1139301010209792] = "Frye: Parece que tudo acabou, o Espelho Mágico do Desespero foi destruído e o ritual de sacrifício foi interrompido...\n Frye: Salvamos Tingen mais uma vez.\n Leonard: Mas desta vez... estamos todos vivos.",
  [1139301010209536] = "O tempo começa a fluir e todos se reúnem em torno do rosto pálido de Frye.\n Frye: Tosse... tosse tosse... vocês... são todos...\n Frye lentamente abre os olhos, examina as pessoas ao seu redor e lentamente revela um sorriso; todo mundo relaxa.",
  [1139301010209280] = "No momento crítico, Leonard aparece, pausa o tempo e dissipa a chuva espelhada. \n Leonard: Já chega, meu velho, obrigado.",
  [1139301010209024] = "O espelho mágico se estilhaça, explodindo com uma enorme quantidade de energia, e incontáveis ​​​​fragmentos de espelho caem do céu.\n Os Vigias Noturnos presentes estão mergulhados em uma enorme crise.",
  [1139301010208768] = "A sombra fantasma se dissipa, e aquela torrente de conhecimento relacionada ao Palácio do Vapor aparece no céu.\n Bernadette: O Palácio do Vapor, ele apareceu novamente...\n Bernadette o persegue.",
  [1139301010208512] = "A barreira carmesim se dissipa e Bernadette olha ansiosamente para Roselle no céu.\n Roselle: Bernadette, minha filha...",
  [1139301010208256] = "Professor: Grande Mãe, quero oferecer-lhe todo o Tingen, por favor, conceda-me o renascimento!\n Um enorme espelho aparece no espaço aberto, e a figura do professor desaparece no espelho e desaparece.",
  [1139301010208000] = "Você e Frye saem da casa segura e voltam para Tingen no Espelho...\n Encontre o Espelho Mágico do Desespero, destrua-o e salve mais pessoas!",
  [1139301010207744] = "Alguns dias depois.",
  [1139301010207488] = "Em meio aos olhares invejosos dos outros, você se senta elegantemente no vaso sanitário dourado.",
  [1139301010206976] = "A \"Cidade das Cidades\" \n está prestes a zarpar!",
  [1139301010206720] = "[Espaço reservado] O batedor de carteira tenta fugir, mas Tom anda de bicicleta nova e o derruba com força.\n Jogador: Lembre-se, desta vez a Gangue dos Caçadores de Dragões mexeu com a pessoa errada.",
  [1139301010206464] = "[Espaço reservado] O jogador olha em volta, mas não consegue encontrar sua carteira; ao longe, o batedor de carteiras Baker está prestes a partir triunfantemente quando é descoberto pelo jogador.",
  [1139301010206208] = "[Espaço reservado] Leonard segura bem alto a Coroa do Conhecimento e todos retornam com sucesso ao mundo real antes do colapso de Tingen.\n Depois de um período de tempo, a vida de todos parece ter voltado ao normal, e os Vigias Noturnos estão tirando fotos sob o corredor de glicínias.",
  [1139301010205952] = "[Espaço reservado] Em frente à casa segura, Rozanne está ajudando ansiosamente os cidadãos sobreviventes a escapar, e Frye usa sua carne e sangue para bloquear a chuva espelhada para todos.",
  [1139301010205696] = "[Espaço reservado] Frye: ...Não é bom, a casa segura está em perigo!",
  [1139301010205440] = "[Espaço reservado] O jogador atira na Viscondessa ferida, e o Espelho Mágico do Desespero bloqueia a bala fatal para ela.\n Espelho Mágico do Desespero: Ugh... adeus... Helena...",
  [1139301010205184] = "[Espaço reservado] Quando o espelho mágico se quebra, a Viscondessa aparece.\n Viscondessa: Não seja rude!",
  [1139301010204928] = "[Espaço reservado] A vontade de Roselle desperta, reunindo uma torrente de conhecimento em um canhão, que explode na barreira, e a lua instantaneamente fica branca prateada.",
  [1139301010204672] = "[Espaço reservado] Você e Frye são empurrados para trás pela barreira e apoiados pelas vinhas atrás de vocês.\n Uma senhora misteriosa desce elegantemente a escada da videira.\n Senhora misteriosa: Encontrou seu colega?",
  [1139301010204416] = "[Espaço reservado] O jogador finalmente se livra da torrente carmesim e chega à Praça Central, onde Frye já está esperando.\n Sob o luar carmesim, o professor está realizando um ritual de sacrifício, e os cidadãos enlouquecidos estão se espalhando pelo centro da praça, transformando-se em uma torrente de informações para serem sacrificadas à Deusa Mãe.",
  [1139301010204160] = "[Espaço reservado] O jogador e Frye chegam ao cruzamento, e edifícios no ar caem do céu. Os dois se esquivam repetidamente e são forçados a se separar.",
  [1139301010203904] = "[Placeholder] O jogador e Frye saem da casa segura e descobrem que sob o luar carmesim, os cidadãos estão se transformando em uma torrente de informações, um após o outro; a verdadeira crise chegou.",
  [1139301010203648] = "[Animação de espaço reservado] Selena parece ter percebido alguma coisa! Ela se vira rapidamente, sua pele não apenas ficando pálida, mas também com unhas afiadas e assustadoras.",
  [1139301010203392] = "[Animação de espaço reservado] Em seguida, ele acende rapidamente as velas e ativa o ritual de purificação.",
  [1139301010203136] = "[Placeholder-QTE] Klein rapidamente constrói uma parede de espiritualidade , isolando toda a sala.",
  [1139301010202880] = "[Animação de espaço reservado] Aproveitando o momento em que Selena está olhando ao redor, Klein aparece silenciosamente no canto.",
  [1139301010202624] = "[Placeholder-Animation] Animação de preparação de poções.",
  [1139301010202368] = "[Animação de espaço reservado] O jogador caminha até a recepção e Rozanne está se olhando no espelho. Rozanne percebe o jogador, coloca o espelho sobre a mesa e um close mostra os dois conversando.",
  [1139301010201856] = "[Espaço reservado] Mais de uma dúzia de cidadãos se reúnem em torno de Rozanne.",
  [1139301010201600] = "[Espaço reservado] Quando Rozanne está salvando alguém, ela é emboscada por um monstro, e Bernadette aparece de repente, levantando a mão para cuidar do monstro.",
  [1139301010201344] = "[Espaço reservado] Alguém de repente levanta as mãos, enquanto os corpos dos outros se torcem rigidamente e começam a atacar as pessoas ao seu redor. A multidão grita e se dispersa.",
  [1139301010201088] = "Dentro da silhueta da energia negra, uma pessoa torceu-se e dobrou-se para trás, transformando-se em um lobisomem gigante.",
  [1139301010200832] = "Uma explosão de energia negra irrompe repentinamente na multidão, e as pessoas ao redor recuam aterrorizadas.",
  [1139301010200576] = "Velho elegante: Pessoal, o banquete ainda não começou, como podem sair mais cedo?",
  [1139301010200320] = "Assim como Rozanne e Dunn estavam se preparando para entrar no espelho, uma campainha tocou.\n O mordomo saiu da torrente carmesim de efeito de conhecimento e curvou-se levemente para todos.",
  [1139301010200064] = "Swayne bate algumas vezes no barril de vinho ao lado dele.",
  [1139301010199808] = "Você pediu mais algumas informações e as registrou no arquivo de investigação.",
  [1139301010199552] = "Você luta para acordar e se encontrar em um espaço estranho, \n e não muito longe está uma figura familiar - o Sr. Enganar.",
  [1139301010199296] = "Você vislumbra uma figura no espelho, com cabelos pretos, olhos castanhos e uma expressão de terror.\n Espere, esse não é você!",
  [1139301010199040] = "Muitas cenas repentinamente passam diante de seus olhos: \n uma lua vermelha, um diário manchado de sangue...",
  [1139301010198784] = "Uma luz ofuscante pisca e você vê o Sr. Louco parado diante de você, esperando que você acorde...",
  [1139301010198528] = "Uma névoa branco-acinzentada emerge diante de seus olhos mais uma vez, e inúmeros fragmentos que registram a história passam por você.",
  [1139301010198272] = "A luz do sol do lado de fora da janela é adorável, brilhando calorosamente em seu corpo...",
  [1139301010198016] = "Você teve outro longo sonho, mas não era mais um pesadelo.\n No sonho, você parecia ver um amigo que não via há muitos anos,\n e vocês conversaram por um longo tempo...",
  [1139301010197760] = "Cook cai no chão inconscientemente.",
  [1139301010197504] = "Ele desliga o fogão desajeitadamente e seus tentáculos se estendem novamente na direção de Cook.",
  [1139301010197248] = "Você vira a cabeça e vê um polvo ocupado em frente ao fogão.",
  [1139301010196992] = "\"Ah, não! Ah, não! Alguém me descobriu!\"",
  [1139301010196480] = "Seu coração está repleto do poder de cura e a névoa do pesadelo parece ter sido temporariamente dissipada.",
  [1139301010196224] = "Depois da psicoterapia da senhorita Justiça e de um descanso no café...",
  [1139301010195968] = "O carteiro vai embora de bicicleta.",
  [1139301010195712] = "Do lado de fora da janela, a lua vermelha se inclina para oeste e gradualmente afunda, \n até que uma luz fraca aparece no leste e o horizonte fica tingido de dourado...",
  [1139301010195456] = "Klein lê o diário com atenção, tentando se lembrar.",
  [1139301010195200] = "Acompanhado por um toque agudo, o carteiro mal consegue frear a bicicleta na sua frente antes de bater em você.",
  [1139301010194944] = "Você?",
  [1139301010194688] = "Meu? Você?",
  [1139301010194432] = "\"EU\"",
  [1139301010193920] = "\"Este é o meu reino\"",
  [1139301010193664] = "Espere... espere...",
  [1139301010193408] = "\"Justiça\": Está tudo bem, ainda há esperança. Vigésima primeira tentativa, recomeçar.",
  [1139301010193152] = "\"O Enforcado\": Desta vez há um problema com o notebook; o renascido cometeu suicídio devido à sua maldição.",
  [1139301010192896] = "\"Mágico\": Pela vigésima vez, falhou de novo? Existem simplesmente muitas situações inesperadas.",
  [1139301010192640] = "“É a vigésima vez, espero que o renascido possa ir um pouco mais longe.”",
  [1139301010192384] = "[Recurso de espaço reservado] A animação da consciência do jogador retornando à sala de alquimia após tomar a poção está em produção...",
  [1139301010192128] = "Flashback de memória: Duas cervejas e um pudim tilintando juntos.",
  [1139301010191872] = "Flashback de memória: Klein se decide e bebe a poção.",
  [1139301010191616] = "Flashback de memória: Dunn sai da névoa cinzenta e repele o monstro.",
  [1139301010191360] = "Flashback de memória: Sr. Azik sorri para você.",
  [1139301010191104] = "Flashback de memória: Klein olha para o diário de Roselle, chocado.",
  [1139301010190848] = "Flashback de memória: Recepção de Blackthorn, Rozanne guarda o jornal apressadamente e olha para você.",
  [1139301010190592] = "Daly realiza mediunidade espiritual, cena da queda de Klein.",
  [1139301010190336] = "Cena do final do parkour de Dunn, com Dunn por toda parte.",
  [1139301010190080] = "Cena da aparição de Dunn e Leonard.",
  [1139301010189824] = "Em meio à espessa neblina cinzenta, os fantasmas de Alger e Audrey olham para cima.",
  [1139301010189568] = "Cena da foto da família de três pessoas de Klein.",
  [1139301010189312] = "Cena de Klein olhando para o olhar da lua vermelha.",
  [1139301010189056] = "Pobres desgraçados.",
  [1139301010188800] = "e também um grupo que luta constantemente contra o perigo e a loucura.",
  [1139301010188544] = "Nós somos Guardiões",
  [1139301010188288] = "Rozanne está ocupada na recepção, ouve alguém chegando, ergue os olhos e encontra você e Leonard. \n Leonard apresenta Rozanne e pergunta a ela sobre o contrato e o distintivo preparados.",
  [1139301010188032] = "Acompanhados pelo canto, os crentes caem um após o outro ou são lançados voando, a lua vermelha desaparece e o tempo volta ao normal.\n Leonard caminha lentamente, encerrando o lançamento do feitiço.",
  [1139301010187776] = "No final da batalha, você está cercado por um grande número de crentes, lançando um contra-ataque desesperado e impotente.\n No momento crítico, Leonard recita um poema em Hermes para interromper o ritual.",
  [1139301010187520] = "Conforme você se aproxima da entrada do parque, o som de uma campainha de bicicleta apressada toca.\n Um carteiro de monóculo freia e para na sua frente em sua bicicleta (versão deluxe).\n Quando o carteiro sai, você vê uma figura passando pela entrada do parque, lembrando-o do ritual do Lago Tingen.",
  [1139301010187264] = "Fors ensina você a orar, e vocês recitam juntos o nome honorífico de Hermes.\n\n\n",
  [1139301010187008] = "Você se aproxima e olha para cima para observar a estela de viagem.\n Uma senhora (Fors) está lendo vagarosamente nas proximidades.\n Fors percebe que você parece confuso, fecha o livro, se vira e se aproxima com um sorriso, puxando magicamente uma carta de tarô do Mágico do nada.",
  [1139301010186752] = "Você sai do café. \nMostre a cena movimentada das ruas de Tingen.",
  [1139301010186496] = "Panorama de Tingen \nA câmera diminui o zoom para mostrar o panorama de Tingen. \nTexto de efeito de cena: Reino de Loen, cidade de Tingen",
  [1139301010186240] = "Banquete interno, dentro do clube, nobres realizam banquetes luxuosos, danças, confraternizações, etc. \nEm uma mesa, uma mão pálida deixa uma carta de Tarô \"Temperança\" ao lado de uma taça de vinho. \n(Você pode dizer pela iluminação interna de vidro que a chuva parou e o céu clareou lá fora.)",
  [1139301010185984] = "Um clube se ilumina e abre suas portas para receber os nobres. \nGarçom: Espero que esta chuva não tenha lhe causado nenhum transtorno. \nNoble: Claro, não caí uma única gota de chuva em mim.",
  [1139301010185728] = "Começa a chover e os trabalhadores enxugam a chuva do rosto e continuam trabalhando. \nChefe: Ainda existem alguns lotes de mercadorias; não pare de trabalhar até que sejam movidos! \nA câmera se move rapidamente para outra cena onde muitos pedestres na rua abrem seus guarda-chuvas. Uma carruagem passa em alta velocidade, espalhando muito esgoto.",
  [1139301010185472] = "No distrito fabril, uma empregada olha para a fumaça preta ao longe, xingando. \nEmpregada: O tempo terrível é sempre interminável. \nA câmera desce da fumaça preta para muitos trabalhadores trabalhando.",
  [1139301010185216] = "Na Iron Cross Street, os transeuntes atravessam a rua, alguns negociando com os donos das barracas, outros correndo. \nUm gatinho corre pela mesa de uma pequena barraca. \nNo canto, Pete e Islyn passam rapidamente no meio da multidão.",
  [1139301010184960] = "Do lado de fora de Blackthorn \nDo lado de fora de Blackthorn, Leonard se inclina contra uma parede ou poste de luz, posando como se tivesse acabado de calçar as luvas. \nEle inclina levemente a cabeça em direção ao café, ainda preocupado com a possibilidade de você vir sozinho, então ele sai.",
  [1139301010184704] = "Sob as glicínias. Corredor de glicínias, Cattleya fica sob a treliça, pétalas caindo. \n Ela ajusta os óculos, levanta-se e caminha lentamente pelas profundezas do corredor de glicínias.",
  [1139301010184448] = "Audrey: O grande Sr. Louco também morou aqui uma vez. \n-Bourgeois Cafe \nO sol está brilhando forte do lado de fora da janela; vários casais conversam em mesas de café na rua. \nFors e Xio sentam-se juntos, olhando para um pedaço de bolo na frente deles, com vinho tinto na mesa.",
  [1139301010184192] = "Você prova o café e Audrey apresenta o local: Tingen City.",
  [1139301010183936] = "Rebecca traz duas xícaras de café com um garçom.",
  [1139301010183680] = "Audrey se apresenta como \"Justiça\" e analisa o prólogo: \nVocê foi corrompido por um deus maligno e resgatado pelo Louco.",
  [1139301010183424] = "À sua frente está sentada a elegante e nobre senhora Audrey, com um grande golden retriever deitado ao lado dela. \n Na mesa ao lado da garota, uma carta do Louco repousa silenciosamente.",
  [1139301010183168] = "A tela fica preta e uma chamada suave é ouvida. \n Você abre ligeiramente os olhos e se vê sentado perto da janela.",
  [1139301010182912] = "[Recurso de espaço reservado] Animação de Deus Caminho em produção...",
  [1139301010182656] = "Muitas imagens passam pela sua mente: uma multidão estagnada, um palhaço estranho com maquiagem no rosto, um monstro enlouquecido cinza-branco... Esses são fragmentos de “sua” história.",
  [1139301010182400] = "[Espaço reservado] Algumas memórias voltam; parece que Klein já esteve aqui antes...",
  [1139301010182144] = "A vigésima primeira vez, recomeçando...",
  [1139301010181888] = "A vigésima tentativa, falhou...",
  [1139301010181632] = "Pela vigésima vez, recomeçando...",
  [1139301010181376] = "[Voz de longe] Jovem: Enid, venha aqui rápido.",
  [1139301010180864] = "Aniversário... por que parece tão familiar...",
  [1139301010180608] = "Quando você olha para cima novamente, a garotinha se foi, deixando apenas uma bonequinha de cordeiro para trás.",
  [1139301010180352] = "Um sussurro ecoa em seus ouvidos. Você aperta a cabeça com dor enquanto cenas de algum ritual voltam à sua mente.",
  [1139301010180096] = "Quando você olha para cima novamente, a garotinha se foi.",
  [1139301010179840] = "Um sussurro ecoa em seus ouvidos. Você aperta o peito de dor enquanto cenas horríveis de algum ritual voltam à sua mente.",
  [1139301010179584] = "Menina: “Cordeirinho, cordeirinho, o irmão disse que vai comemorar meu aniversário hoje, adivinha que presente o irmão vai preparar para mim?”",
  [519177257361921] = "Feliz aniversário!",
  [1139301010179328] = "Você acorda debaixo de uma árvore, uma garotinha não muito longe está brincando de costas para você",
  [1139301010179072] = "Menina: “O irmão me ligou! Cordeiro, cordeirinho, fique bem e durma aqui, vou brincar com você de novo quando voltar.”",
  [1139301010178816] = "\"Justiça\": (Respira fundo) Bom, um novo sonho começou.",
  [1139301010178560] = "\"Mágico\": Senhorita Justiça, conforme o plano, a porta foi aberta.",
  [1139301010178304] = "\"A Estrela\": Não se preocupem, pessoal. O Sr. Louco fará milagres ficarem do nosso lado.",
  [1139301010178048] = "\"O Enforcado\": Não é um fracasso. A “Deusa Mãe da Depravação” corrompeu as memórias do renascido e há muitos sonhos associados às memórias. Devemos colidir repetidamente com a vontade “Dela” de coletar informações suficientes e fazer todos os preparativos para este momento final.",
  [1139301010177792] = "\"O Eremita\": Falhou novamente desta vez. Esta é a décima nona morte; o renascido não pode mais suportar.",
  [1139301010177536] = "Uma longa lança voa e perfura seu corpo",
  [1139301010177280] = "Você se ajoelha, olha lentamente para a Deusa Mãe e derrama lágrimas sem expressão.",
  [1139301010177024] = "As esculturas emitem sussurros de sacrifícios aos deuses malignos, incentivando você a seguir em frente.",
  [1139301010176768] = "(A câmera se volta para o ambiente) Você está em um corredor repleto de esculturas dos dois lados.",
  [1139301010176512] = "(Close do rosto danificado pela batalha do jogador) Sua expressão é desesperada e quebrada",
  [1139301010176256] = "Klein tonto se prepara para ir para casa...",
  [1139301010176000] = "Dunn e os outros correm de volta para a empresa, selando o Artefato Selado e o caderno dentro do Portão Chanis.",
  [1139301010175744] = "Ao voltar para casa, Klein está tão cansado que adormece na cama sem nem trocar de roupa...",
  [1139301010175488] = "Leonard notifica a polícia para lidar com as consequências e depois retorna para a Blackthorn Security Company...",
  [1139301010175232] = "Klein confirma suas preocupações, dá um passo para trás para manter distância e começa a pensar em uma contramedida.",
  [1139301010174976] = "[Espaço reservado B] Klein passa pelo encosto do sofá, espiando secretamente o espelho de Selena. \nO espelho reflete uma figura, sua aparência distorcida, irradiando uma tonalidade negra e verde maligna.",
  [1139301010174720] = "[QTE] Toca aqui \n Klein: Eu tenho a mesma atitude. \n Leonard: Estou feliz por termos chegado a um consenso. \n Leonard: Nesses romances de aventura, isso é chamado de encontro de dois protagonistas e as rodas da história começam a avançar.",
  [1139301010174464] = "Leonard: Da mesma forma, espero que você me veja com uma atitude semelhante. \nLeonard: Claro, é melhor não contar essas coisas aos superiores. Esses caras são rígidos e conservadores, sempre pensando que pessoas especiais como nós serão inevitavelmente atraídas por deuses e demônios malignos para a queda. \n*Leonard estende a mão*",
  [1139301010174208] = "[Espaço reservado A] Leonard: Klein, não há necessidade de fingir entre nós. \nLeonard: Uma vez eu lhe disse que existem muitas pessoas especiais neste mundo, por exemplo, você e, por exemplo, eu. \nLeonard: Não acho que um Beyonder que esconde segredos seja necessariamente uma pessoa má. Contanto que suas ações não prejudiquem a mim ou ao Vigias Noturnos , então você ainda é meu companheiro de equipe.",
  [1139301010173952] = "Somos Guardiões \n e também um grupo de \n pobres coitados lutando constantemente contra o perigo e a loucura.",
  [470936453122048] = "Vidente",
  [1139301010173696] = "Klein compra alguns vegetais e carne e depois corre para casa.",
  [1139301010173440] = "No meio da multidão, Pete segurando Islyn passa rapidamente.",
  [1139301010173184] = "O carteiro dá tchau e sai andando de bicicleta, fazendo ding-a-ling.",
  [1139301010172928] = "Um carteiro andando de bicicleta freia repentinamente e para na sua frente.",
  [1139301010172672] = "Você experimentou uma batalha que não pode ser interrompida.",
  [1139301010172416] = "Eles olham para você, caminham em sua direção e te abraçam...",
  [1139301010172160] = "Em meio aos sussurros, a lua vermelha surge, \n e os cidadãos no parque ficam parados como esculturas, seus movimentos congelados.",
  [1139301010171904] = "Inúmeras fitas coloridas são disparadas do cano.",
  [1139301010171648] = "Você quer tocar as orelhas branco-rosadas do coelho. \n O coelho saca uma pistola e aponta para você: \"Eu odeio caras indelicados!\" \n Os arredores imediatamente se transformam em caos. \n \"Bang!\"",
  [1139301010171392] = "Divina de repente segura um coelho para você: \n Colega, venha aprender sobre nossa \"Gehrman Performance Art Research Society\"!",
  [1139301010171136] = "Coelho Gehrman: Você, pare. \n Você olha para a esquerda e para a direita, procurando de onde vem a voz.",
  [1139301010170880] = "[Temporário] Você luta até a exaustão, e a cor carmesim se espalha como uma maré.",
  [1139301010170624] = "Há uma pessoa inesperada em casa – Benson. Ao ver Klein, ele o cumprimenta com um sorriso.",
  [1139301010170368] = "[Espaço reservado] QTE3-Klein coloca um cristal irregular no cadinho.",
  [1139301010170112] = "[Espaço temporário] QTE2-Klein derrama um pouco de líquido cintilante no cadinho.",
  [1139301010169856] = "[Espaço reservado] QTE1-Klein espalha um pó estranho no cadinho.",
  [1139301010169600] = "No sonho, um caderno preto repousa silenciosamente no chão. Um momento depois, a figura de um homem o leva embora...",
  [1139301010169344] = "Sussurros fragmentados ecoam de repente em seu sonho.",
  [1139301010169088] = "\"Hornacis...Flegrea...\"",
  [1139301010168832] = "Klein deita na cama e adormece.",
  [1139301010168576] = "[Espaço reservado] Velho Neil: \"Está um pouco melhor agora?\"",
  [1139301010168320] = "[Espaço reservado] Klein pensa bastante por um momento. Desta vez, ele decide delinear uma bola de luz.",
  [1139301010168064] = "[Espaço temporário] Velho Neil: \"Carinha, concentre-se!\"",
  [1139301010167808] = "[Espaço reservado] Klein tenta novamente – desta vez, ele tenta delinear um míssil intercontinental em sua mente, mas falha.",
  [1139301010167552] = "[Espaço reservado] Velho Neil: \"Então substitua o objeto delineado por um objeto que não existe no mundo, algo imaginado do nada.\"",
  [1139301010167296] = "[Espaço temporário] Klein se esforça para se concentrar, imaginando uma cartola de seda.",
  [1139301010167040] = "[Espaço reservado] Velho Neil: \"Imagine um objeto comum em sua mente, concentre toda a sua atenção nele e continue repetindo e delineando esse objeto.\"",
  [1139301010166784] = "[Espaço reservado] Todos: Saúde!",
  [1139301010166528] = "[Espaço reservado] Klein: Para uma vida melhor no futuro.",
  [1139301010166272] = "[Espaço reservado] Benson: Venha, vamos comemorar que Klein encontrou um bom emprego!",
  [1139301010166016] = "[Espaço temporário] Melissa: Mmm (sons de mastigação na boca) delicioso... Louvada seja a Senhora!",
  [1139301010165760] = "[Espaço temporário] A câmera diminui o zoom; os três irmãos estão reunidos ao redor da mesa, desfrutando calorosamente do jantar.",
  [1139301010165504] = "[Espaço reservado] Uma mão dá corda na boneca mecânica de Melissa algumas vezes. Depois de se soltar, a linda boneca cambaleia e caminha sobre a mesa cheia de pratos.",
  [1139301010165248] = "Melissa pega uma boneca mecânica.",
  [1139301010164992] = "Melissa: \"Klein, parabéns por encontrar um emprego.\"",
  [1139301010164736] = "Melissa: \"Obrigada... tenho um presente para você.\"",
  [1139301010164480] = "Ao dizer isso, Klein tira um pudim de limão.",
  [1139301010164224] = "Klein: \"Melissa, nós temos cerveja, você tem isso.\"",
  [1139301010163968] = "Benson: \"Ha, cerveja de gengibre! Senti tanta falta desse sabor.\"",
  [1139301010163712] = "[Espaço temporário] Dunn pacifica Klein: Está tudo bem, Klein, volte para a empresa primeiro.",
  [1139301010163456] = "[Espaço reservado] Klein olha em volta; Kenley está se livrando do cadáver, os pedestres passam, mas não reagem ao corpo no chão. Há uma sensação de uma parede transparente azul nebulosa ao redor, e o coro não muito longe ainda está cantando.",
  [1139301010163200] = "\"Justiça\": Beyonders avança seu Sequência consumindo poções, o que também é um avanço em seu nível de vida. Esta é uma— \n\"Justiça\": Caminho de progressão do humano para Deus.",
  [1139301010162944] = "\"Justiça\": Existem muitos Beyonders neste mundo. A base dos Beyonder poderes é representada por—22 Beyonder Caminhos. \n\"Justiça\": Para cada Caminho , começando em Sequência 9, quanto mais você avança, menor é o número, representando um nível mais alto de poder.",
  [1139301010162688] = "Alimentado pelo ressentimento acumulado dia e noite no distrito fabril, e catalisado pela escuridão e pela opressão tangíveis, o plano está avançando sem problemas.\"",
  [1139301010162432] = "Uma caneta-tinteiro escreve: \n \"O ritual para a prole foi um sucesso! Embora Klein tenha descoberto as mortes em série nas favelas, isso não afeta a continuação da história.",
  [1139301010162176] = "Depois de uma noite de reviravoltas, Klein acorda cedo no dia seguinte e vai para o Adivinhação Clube...",
  [1139301010161920] = "Depois que a cana oscila, ela não cai para dar direção, mas permanece firme no lugar.",
  [1139301010161664] = "Klein conta o que viu.",
  [1139301010161408] = "[Espaço reservado B] O espelho se quebra e Klein retorna à realidade.",
  [1139301010161152] = "Mulher encapuzada-risos: Você nunca se perguntou por que nossos superiores são todos mulheres? \nMulher Encapuzada: Esta é a resposta. \nA imagem fica borrada e Trissy aparece. \nEla fica perto da janela, olhando seu reflexo no vidro, tocando suavemente seu rosto no espelho. \nTrissy: Chega de vagar, chega de passar fome, chega de ser comprada e vendida... \nTrissy: Para sobreviver, sempre é preciso pagar um preço, não é?",
  [1139301010160896] = "[Espaço reservado B] A superfície do espelho converge, apresentando uma memória. Trissy e uma mulher encapuzada ficam cara a cara. \nMulher Encapuzada: Muito bem, Tingen ficou ainda mais caótico... O medo e a morte são sempre o melhor alimento. \nHomem: Concluí o missão . Você me prometeu os materiais para avançar. \nMulher Encapuzada: Claro, a próxima Sequência para avanço é—Bruxa. \nHomem: Bruxa?! Devo avançar para uma bruxa? Você está brincando comigo?",
  [1139301010160640] = "Justo neste momento, tudo o que ela vê diante dela se despedaça abruptamente, como uma alucinação. Ela está dentro de um altar, as janelas de vidro quebradas e o céu revela uma lua vermelha. \nAs pupilas de Trissy se contraem: fui arrastada para um sonho?!",
  [1139301010160384] = "[Espaço reservado A] Uma mulher gentil e doce está parada perto da janela. Ela o abre, seus lindos olhos olhando para você. Depois de espalhar um pouco de pólvora, ela desaparece, de repente aparecendo atrás de Leonard e enfiando uma adaga na parte inferior de suas costas.",
  [1139301010160128] = "[C Placeholder] \n Klein: A localização do altar. \n É uma casa azul-acinzentada de dois andares banhada pelo brilho do crepúsculo, com as costas de uma mulher parada perto da janela. Não muito longe da casa, um rio corre tranquilamente.",
  [1139301010159872] = "Uma figura se aproxima, uma mão bela e esbelta acende um fósforo e o estende para o incendiário \n ???: \"É como acender um grande incêndio para queimar tudo. Você também quer ser livre, não é?\"",
  [1139301010159616] = "Piromaníaco: Por que o destino tem que tirar tudo de mim! Essas pessoas ricas não precisam fazer nada para desfrutar de sua riqueza. E nós... tentamos o nosso melhor, mas no final não temos nada. \n???: Outro... É esse mundo que está errado. Você não vai fazer algo a respeito?",
  [1139301010159360] = "[Espaço reservado B] Klein se senta e começa a meditar. Na escuridão, ele vê um homem desesperado de meia-idade rasgando suas dívidas e espalhando-as no ar. \nPiromaníaco: Eu... não tenho mais nada!",
  [1139301010159104] = "Vista panorâmica da cidade de Tingen \n A chuva cai continuamente e o badalar do relógio ecoa.",
  [1139301010158848] = "Uma carruagem passa em alta velocidade e as luzes do Clube se acendem. \n Porteiro: \"Que tempo terrível, obrigado pelo seu trabalho duro.\" \n Dentro do Clube, em um canto do extravagante banquete, \n uma mão pálida deixa um cartão \"Temperança\" ao lado de uma taça de vinho.",
  [1139301010158592] = "Factory District \n Uma empregada que compra carne olha para as distantes chaminés pretas: \"Esta chuva simplesmente não para.\" \n Sob as chaminés pretas, os trabalhadores enxugam a chuva do rosto e continuam a trabalhar. \n Os pedestres na rua abrem seus guarda-chuvas um após o outro.",
  [1139301010158336] = "Rua Cruz de Ferro \n Os transeuntes caminham pela rua, alguns negociando com os donos das barracas, outros correndo. \n Um gato corre pela mesa de uma pequena barraca. \n No canto, Pete e Enid passam rapidamente.",
  [1139301010158080] = "Do lado de fora de Blackthorn \n Leonard se inclina contra a parede para ajustar as luvas, \n inclina levemente a cabeça em direção ao café, sente que a psicoterapia foi bem-sucedida e sai com um sorriso.",
  [1139301010157824] = "Debaixo das glicínias \n Cattleya ajusta os óculos e se levanta, caminhando em direção às profundezas da galeria das glicínias.",
  [1139301010157568] = "[Animação de espaço reservado] Os três irmãos (tilintando os copos): \"Felicidades!\"",
  [1139301010157312] = "[Animação de espaço reservado] Klein (também levantando o copo): \"Para uma vida melhor no futuro!\"",
  [1139301010157056] = "[Animação de espaço reservado] Benson (erguendo o copo): \"Venha, vamos comemorar que Klein encontrou um bom emprego!\"",
  [1139301010156800] = "[Animação de espaço reservado] Melissa: \"Mmm (som de mastigação)... delicioso... Louvada seja a Deusa!\"",
  [1139301010156544] = "[Animação de espaço reservado] A câmera se afasta para mostrar os três irmãos reunidos ao redor da mesa, desfrutando calorosamente do jantar.",
  [1139301010156288] = "[Animação de espaço reservado] Klein dá corda na boneca mecânica de Melissa algumas vezes, deixando-a balançar sobre a mesa cheia de pratos.",
  [1139301010156032] = "“Klein?” \n A ligação intrigada do Velho Neil trouxe Klein de volta à realidade.",
  [1139301010155776] = "“A escolha inicial ainda foi muito precipitada. Agora parece que seja um Aprendiz, um Vidente ou um Saqueador, todos seriam melhores.”",
  [1139301010155520] = "\"Eu já disse isso dez mil vezes, a chave para uma poção não é o domínio e a escavação, mas a digestão e a atuação.\"",
  [1139301010155264] = "\"1º de janeiro de 1184. Uma grande festa de Ano Novo. A Sra. Flonal é realmente deslumbrante.\"",
  [1139301010155008] = "\"18 de novembro. Que coisa mágica. Através de um experimento caprichoso, descobri um pobre sujeito preso em uma tempestade e perdido nas profundezas da escuridão.\"",
  [1139301010154752] = "Klein: \"Isso é... chinês?!\" \n Suprimindo seu choque, Klein lê o diário seriamente.",
  [1139301010154496] = "[Animação de espaço reservado] \"Você sabe sobre Welch e Naya?\"",
  [1139301010154240] = "Azik entra no escritório.",
  [1139301010153984] = "“Olá, Klein.”",
  [1139301010153728] = "Leonard: \"Boa tarde, nos encontramos novamente. Você se lembra de mim? \n Leonard Mitchell, um Sequência Poeta das 8 Meia-Noite.\"",
  [1139301010153472] = "[Animação de espaço reservado] Klein sobe as escadas. De repente, uma figura bloqueia seu caminho.",
  [1139301010153216] = "[Diálogo de espaço reservado] Dunn sai de trás de Klein. Ao vê-lo aparecer, Klein não pode deixar de relaxar.",
  [1139301010152960] = "[Placeholder-Dialogue] \"Tudo bem, este é o Portão Chanis, em homenagem ao Arcebispo Chanis, o fundador do sistema Vigia Noturno.\"",
  [1139301010152704] = "[Placeholder-Dialogue] O tremor para tão repentinamente quanto começou. Klein olha para a porta, perplexo (e ainda abalado).",
  [1139301010152448] = "[Diálogo de espaço reservado] De repente, sons violentos de batidas vêm de dentro da porta, e a porta inteira balança junto com ele. Vendo essa reviravolta, Klein recua aterrorizado.",
  [1139301010152192] = "[Placeholder-Dialogue] Klein se inclina perto do Portão Chanis e o observa cuidadosamente.",
  [1139301010151936] = "[Placeholder-Dialogue] Na introdução de Rozanne, Klein troca gentilezas com Frye.",
  [1139301010151680] = "[Placeholder-Dialogue] Na introdução de Rozanne, Klein troca gentilezas com Kenley e Xiga.",
  [1139301010151424] = "Continua",
  [1139301010151168] = "Klein: \"Esse coro - a igreja está nessa direção!\"",
  [1139301010150912] = "Neste momento, uma voz fraca e cantante emerge da neblina – é o hino à Deusa da Noite Meia que ele ouviu o coro cantar antes.",
  [1139301010150656] = "De repente, surge uma névoa espessa, obscurecendo rapidamente a rua e sua visão. Klein entra em pânico no meio da neblina e começa a observar o que está ao seu redor: “Essa também é uma habilidade Beyonder?”",
  [1139301010150400] = "Klein: “Assim, conduza lentamente a outra parte em direção à igreja...”",
  [1139301010150144] = "Klein: \"Essa sensação de estar sendo observado não desapareceu. Um Beyonder pode correr mais rápido que uma carruagem?\"",
  [1139301010149888] = "A carruagem para em uma rua do Distrito Norte de Tingen. Klein desce e olha em volta rapidamente.",
  [1139301010149632] = "Um par de mãos delgadas a empurra suavemente. \n ???: Tudo bem, vá em frente. Mesmo se você morrer, você não terá que passar fome.",
  [1139301010149376] = "[C Espaço reservado] Uma mulher espiritual aparece colando caixas de fósforos. \n Mulher: Meu peito está tão apertado... \n Embora o atendimento médico de caridade seja gratuito... leva um dia inteiro... esqueça, se eu não trabalhar hoje, não terei comida amanhã...",
  [1139301010149120] = "Crianças maltrapilhas olham para Klein e Leonard enquanto descem da carruagem, enquanto um homem dorme na entrada da casa.",
  [1139301010148864] = "[Espaço reservado C] A carruagem passa pela Lower Street da Iron Cross Street e para em frente a uma casa em ruínas.",
  [1139301010148608] = "Klein conta o que aconteceu no Clube.",
  [1139301010148352] = "Klein: Senhorita, você está bem? \n Senhora: Obrigada pela sua preocupação, estou bem, só um pouco cansada. \n Pessoa atrás: Saia rapidamente, não bloqueie a porta do carro. \n Klein passa por essa senhora. \n Klein: Não tive tempo de usar Visão Espiritual para verificar. Esqueça, vamos voltar para Blackthorn primeiro.",
  [1139301010148096] = "[Espaço reservado B] A carruagem segue em direção à entrada de Blackthorn. Klein desce e encontra uma linda mulher se preparando para embarcar. \n Ela é doce e gentil, com longos cabelos negros e pele clara. Talvez devido ao frio, seu corpo esteja tremendo um pouco, mas ela ainda parece bastante charmosa. \n Klein: (Tenho que admitir, esta é realmente a garota mais linda que vi desde que transmigrei. Estranho, por que ela continua tremendo?)",
  [1139301010147840] = "Meia hora depois...",
  [1139301010147584] = "[Um espaço reservado] Primeiro, houve a água do mar tingida de vermelho e os sons da matança, depois a cena mudou, o tempo melhorou e Joyce entrou em uma casa com um moinho de vento de brinquedo.",
  [1139301010147328] = "Klein se recosta, fecha os olhos e começa a meditar.",
  [1139301010147072] = "\"Oh, Senhor Supremo do Carmesim, Grande Imperatriz da Calamidade e do Horror...\" \n \"Eu rezo por seu favor, favoreça sua ovelha perdida - Selina!\"",
  [1139301010146816] = "(Espaço reservado, é necessário adicionar a performance de Klein) \n Klein canta o nome honorífico:",
  [1139301010146560] = "[Recurso de espaço reservado para processo de nomenclatura]",
  [1139301010146304] = "Na noite seguinte",
  [1139301010146048] = "Infectado pela atmosfera aquecida ao seu redor, Klein também se joga no intenso jogo de cartas.",
  [1139301010145792] = "(Espaço reservado, há um vídeo de flashback aqui) \n Klein já havia visto no diário de Roselle: Não é maestria, é atuação...",
  [1139301010145536] = "[Espaço reservado] Klein e Derrick seguravam a espada; A mão de Derrick tremia ligeiramente. Ele soltou um soluço reprimido e, acompanhado por um relâmpago no céu, mergulhou a espada no Espírito Maligno de seus pais.",
  [1139301010145280] = "[Espaço reservado] Klein estendeu a mão para tocar a estrela vermelha no espaço de névoa cinza e, de repente, ondas de água surgiram em seu corpo; a estrela vermelha profunda irrompeu com luz vermelha. \n Na Terra Abandonada dos Deuses, Derrick se ajoelhou em tristeza, orando enquanto enfrentava uma bola de cristal. \n “Grande Deus, por favor, olhe mais uma vez para este lugar abandonado por você.” \n \"Grande Deus, por favor, deixe-nos, o povo das trevas, nos livrar dessa maldição predestinada.\" \n Assim que ele estava prestes a se desesperar, uma massa vermelha profunda em erupção da bola de cristal afogou a cena. O alto Derrick apareceu acima da névoa cinzenta e olhou para Klein, que estava envolto em névoa cinzenta sobre a longa mesa de bronze.",
  [1139301010145024] = "[Espaço reservado] Na Casa de Welch, Vincent e um membro da Ordem Aurora venderam o Caderno Antígono para Welch, finalmente congelando no caderno.",
  [1139301010144768] = "[Espaço reservado] Klein relembrou o adivinhação desse período e um cristal amarelo apareceu em sua mente; de repente ele teve alguns insights.",
  [1139301010144512] = "Conforme Derrick narra, a história da Cidade de Prata parece se desenrolar lentamente diante dos olhos de Klein.",
  [1139301010144256] = "[Espaço reservado] Klein pega seu salário recém-recebido e o mostra com orgulho para Melissa.",
  [1139301010144000] = "Klein se senta e a sonolência gradualmente toma conta dele. \n Quem sabe quanto tempo se passou...",
  [1139301010143744] = "[Espaço reservado] O velho Neil faz uma pose, imaginando o que viu...",
  [1139301010143488] = "[Espaço reservado] Outra porta do dia, a porta do sonho, e o caderno sobre a mesa brilharam diante de seus olhos",
  [1139301010143232] = "[Espaço temporário] Dunn está em um impasse com o inimigo e parece que ambos caíram em um sono profundo.",
  [1139301010142976] = "O garçom serviu café para você \n O sol lá fora da janela estava perfeito \n Alguém estava conversando em uma mesa de centro perto da rua. \n Fors e Xio sentaram-se à mesa, olhando para um pedaço de bolo na frente deles.",
  [1139301010142720] = "Uau-",
  [1139301010142464] = "De repente, cartas de tarô voaram, cortando as vinhas de você e de Enid. \n A chama da vela se apagou e Pete disse com raiva: Quem é? \n Uma massa de névoa cinzenta envolta em luz cintilante caiu da antena. \n A névoa cinzenta se dissipou gradualmente, e o homem por trás da névoa tirou a cartola e curvou-se ligeiramente.",
  [1139301010142208] = "...O Rei do Amarelo e do Preto.",
  [1139301010141952] = "Você olhou para o círculo mágico e queria sair da área ritual, mas também foi enredado pelas vinhas e a corrupção carmesim apareceu em seu corpo.",
  [1139301010141696] = "\"Justiça\": Não se preocupe, existe mais de um Deus, e uma grande existência irá te ajudar...",
  [1139301010141440] = "A marionete da lua levantou-se, pulando e pulando, realizando a ação de rezar para a lua. \n Fantoche: Lua, lua, brilhe, brilhe. \n Fantoche: Todas as coisas crescem, crescem— \n Ao mesmo tempo, vinhas se espalham, enredando Enid...",
  [1139301010141184] = "Pete tocou o boneco da lua próximo ao altar e acendeu a terceira vela. \n Enid apareceu abruptamente, correndo para fora da floresta. \n Enid: Irmão, então você estava aqui. \n Pete: Enid, venha aqui, venha para o lado do seu irmão. \n Assim que Enid entrou na área do círculo mágico, o círculo se iluminou completamente.",
  [1139301010140928] = "Você insistiu em escolher abraçar a “Grande Mãe”; a psicoterapia falhou e você foi completamente corroído pela corrupção.",
  [1139301010140672] = "O carmesim obscureceu tudo, deixando apenas seus dolorosos gemidos abafados e o som de batimentos cardíacos acelerados. \n \"Justiça\": Não, não abrace aquela lua vermelha carregada de corrupção. \n \"Justiça\": Você nunca será capaz de acordar. \n Você insistiu em escolher abraçar a “Grande Mãe”; a psicoterapia falhou e você foi completamente corroído pela corrupção.",
  [1139301010140416] = "Fantoche: Abrace a “Grande Mãe”! Obtenha \"Renascimento e Salvação\"!",
  [1139301010140160] = "Vá para o carregamento após os fragmentos, pule para o Capítulo 1, Seção 1 da linha Mistério",
  [1139301010139904] = "[Espaço temporário] O Velho Neil diz que esta é a cor da sua própria aura. \n Sob a orientação dele, você começa a olhar em volta para outras coisas...",
  [1139301010139648] = "\"Sh.\" \n \"Justiça\" interrompeu gentilmente suas palavras.",
  [1139301010139392] = "Substituição de segmento de nomenclatura",
  [1139301010139136] = "O cachorro de cabelos dourados parece entender as emoções nas palavras de seu dono, salta para se esfregar na mão de seu dono e então se vira para seguir em frente.",
  [1139301010138880] = "[Animação aqui] \n Acordando com aroma de café, diante de você está uma linda senhora sorrindo.",
  [1139301010138624] = "Um nome verdadeiro... mas não pertencente a esta época...",
  [1139301010137856] = "Tão doloroso! Minha cabeça dói muito!",
  [1139301010137600] = "Dor!",
  [1139301010137344] = "No seu sonho, cure você.",
  [1139301010137088] = "[Espaço reservado: todos os ativos neste missão são temporários e apenas para fluxo de plotagem; a maior parte do conteúdo oficial é CS] \n Quando a oração terminou, a névoa cinzenta permeou ▉▉",
  [1139301010136832] = "(CS em produção, texto de espaço reservado) \n Entrando no Adivinhação Clube, um homem está explicando adivinhação métodos...",
  [1139301010136576] = "Uma boa noite de sono sem sonhos ou desastres...",
  [1139301010136320] = "Todos vocês terminaram com alegria as deliciosas ervilhas tenras cozidas com cordeiro; foi um jantar maravilhoso.",
  [1139301010136064] = "[Espaço reservado temporário] \"Ok, vou guardar minha mochila!\" Dizendo isso, Melissa corre de volta para seu quarto para guardar sua mochila...",
  [1139301010135808] = "[Espaço temporário] Klein sorri e acena com a cabeça. Nesse momento, Benson chega de fora e levanta o saco de papel na mão: E isto.",
  [1139301010135552] = "[Espaço temporário] Neste momento, Melissa também retorna. Olhando para o banquete na mesa, ela fica muito surpresa: “Você fez tudo isso?”",
  [1139301010135296] = "[Espaço temporário] Um momento depois, a sala se enche com o aroma da comida. Klein acena com satisfação e começa a colocar toda a comida na mesa.",
  [1139301010135040] = "Klein corre de volta para casa.",
  [1139301010134784] = "O Velho Neil pega duas xícaras e prepara duas xícaras de café fumegante.",
  [1139301010134528] = "[Espaço temporário] De repente, você vê um par de olhos frios e sem cílios. \n Eles estão logo atrás do Velho Neil!",
  [1139301010134272] = "[Espaço reservado temporário] Um pouco de cor vermelha intensa aparece de repente entre seus dedos.",
  [1139301010134016] = "[Espaço temporário] Velho Neil: \"Você se sente um pouco melhor?\"",
  [1139301010133760] = "[Espaço temporário] Velho Neil: \"Coloque toda a sua atenção nele e continue repetindo e delineando este objeto.\"",
  [1139301010133504] = "[Espaço temporário] Klein tenta se concentrar e começa a delinear uma cartola em sua mente...",
  [1139301010133248] = "[Espaço temporário] \"Hornacis... Flegrea... Hornacis... Flegrea... Hornacis... Flegrea...\"",
  [1139301010132992] = "[Espaço temporário] Os objetos na sala começam a dobrar, a cabeça de Klein dói violentamente e sussurros etéreos chegam aos seus ouvidos—",
  [48586280666624] = "Deixar",
  [1139301010132736] = "[Espaço reservado] Os vermelhos ficaram mais vermelhos, os azuis ficaram mais azuis, os blocos de cores eram ricos, uma névoa cinza e ilusória permeava levemente e luzes de sete cores tremeluziam nas profundezas da névoa...",
  [1139301010132480] = "[Espaço reservado] Klein se decidiu e bebeu a poção decididamente de um só gole. \n Logo, ele começou a se contorcer incontrolavelmente e sua visão ficou rapidamente turva.",
  [1139301010132224] = "[Espaço reservado] Dunn moveu-se e matou o monstro com um único tiro. O Vigia Noturno Kenley também chegou para limpar e controlar a cena.",
  [1139301010131968] = "[Espaço reservado] \"Suas flores desabrocham durante a noite até o amanhecer \n Mas quando o dia abre os olhos \n Com vergonha de estar sob o olhar, sem ter onde se esconder \n Ela murcha e cai atordoada...\"",
  [1139301010131712] = "[Espaço reservado] O monstro de repente ficou furioso e atacou Klein. \n Neste momento, Dunn apareceu de repente, ergueu sua arma para repelir o monstro e começou a cantar.",
  [1139301010131456] = "[Espaço reservado] Klein deu alguns passos à frente, a tela tremeu de repente e uma névoa cinza surgiu para formar uma parede de ar. \n Uma pessoa tropeçou para fora da névoa cinzenta, gemeu de dor e depois desabou em um monstro.",
  [1139301010131200] = "[Espaço reservado] Klein estava caminhando tranquilamente pela estrada no Distrito Universitário quando de repente sentiu que algo estava errado.",
  [1139301010130944] = "[Espaço temporário] Klein vira a cabeça e vê duas pistas entrando. O cavalheiro na frente o cumprimenta gentilmente, enquanto o outro cavalheiro está segurando um jornal. \n [Introdução pop-up do personagem: Azik]",
  [1139301010130688] = "[Espaço temporário] Na sala, o Velho Neil está lendo páginas à mesa. De repente, ele percebe o olhar de Klein e levanta a cabeça. \n [Introdução pop-up do personagem: Velho Neil]",
  [1139301010130432] = "[Espaço reservado temporário] A caneta levanta após o toque final no contrato, e Klein pega o contrato e o entrega a Dunn. \n Dunn pega, olha brevemente e sorri enquanto estende a mão para Klein: Bem-vindo, Klein. De agora em diante, você é um de nós.",
  [1139301010130176] = "O esquadrão Vigias Noturnos usou isso para rastrear Haines. Dunn coincidentemente viu a imagem clara do Verdadeiro Criador em seu sonho e sofreu danos tremendos...",
  [1139301010129920] = "\"Selina Wood acidentalmente e coincidentemente viu o verdadeiro encantamento para o espelho adivinhação de seu professor de ocultismo, Haines... \n Sua ousada tentativa de encontrar Klein aconteceu, e este último resolveu com sucesso este Beyonder caso...",
  [1139301010129664] = "(Texto temporário) \n Uma caneta-tinteiro escreve:",
  [1139301010129408] = "Seus braços estavam bem abertos, os pés para cima, e sua cabeça pendia como um pingente. \n Dunn: Não olhe diretamente para Deus!",
  [1139301010129152] = "(CS em produção, texto de espaço reservado) \n \"O espírito heróico persistente, o parente do Verdadeiro Criador, o olho que contempla o destino.\" \n O enorme e borrado Verdadeiro Criador aparece.",
  [1139301010128896] = "(CS em produção, texto temporário) \n A sala está cheia de névoa, o olhar de Selena fica frio, sua pele fica pálida pouco a pouco, e unhas afiadas, brancas e parecidas com ossos crescem rapidamente em seus dez dedos.",
  [1139301010128640] = "Quando Haines apareceu pela primeira vez no Adivinhação Clube, tudo parecia ter sido prenunciado. \n O que poderia estar por trás dessa névoa da história?",
  [1139301010128384] = "Em Blackthorn, os Vigias Noturnos continuam folheando os relatórios, procurando por algo nas informações densas. \n Rastreando inúmeras pistas...",
  [1139301010128128] = "Olhando para baixo, esse é o distrito fabril de Tingen. Onde a névoa negra permeia, as pessoas caem fracamente. \n E por trás daquela névoa negra, uma enorme cruz é vagamente visível.",
  [1139301010127872] = "(CS em produção, texto de espaço reservado) \n Uma névoa cinzenta sem fim surgiu, engolindo você. \n As silhuetas de milhares de lacunas históricas passaram diante de seus olhos até que uma delas parou na sua frente...",
  [1139301010127616] = "Enquanto isso, num canto de Tingen.",
  [1139301010127360] = "Conforme Dunn narra, Klein sente como se também tivesse entrado nesse sonho.",
  [1139301010127104] = "Klein contou sua experiência na Casa de Selena e destacou as ações de Haines.",
  [1139301010126848] = "(CS em produção, espaço reservado para texto) \n A família Moretti pegou uma carruagem para participar de um banquete na Casa de Selena. \n Eles entraram na casa junto com outros convidados.",
  [1139301010126592] = "Desta vez, ninguém vai te acordar do seu sonho novamente.",
  [1139301010126336] = "Klein ergueu ligeiramente a mão direita e uma névoa cinzenta ondulou no espaço. Pilares ergueram-se do chão e um palácio majestoso e imponente apareceu do nada dentro da névoa cinzenta.",
  [1139301010126080] = "Acima da névoa cinzenta, duas figuras ilusórias manchadas de vermelho profundo apareceram de repente na luz.",
  [1139301010125824] = "Uma luz vermelha irrompeu de repente da garrafa, engolindo-o.",
  [1139301010125568] = "Alger está no convés, segurando uma estranha garrafa de vidro, murmurando para si mesmo: “Ainda falta o sangue de um Tubarão Fantasma…”",
  [1139301010125312] = "No Mar Sónia, um veleiro de três mastros navegava no meio de uma tempestade.",
  [1139301010125056] = "Uma luz vermelha irrompeu de repente do espelho antigo, engolindo-a.",
  [1139301010124800] = "Em uma luxuosa villa no Backlund Empress District, Audrey sentou-se em frente à sua penteadeira, acariciando um espelho na mão: “Espelho mágico, espelho mágico, acorde! Em nome da família Hall, ordeno que você acorde!",
  [1139301010124544] = "A estrela explodiu em luz vermelha, cobrindo tudo.",
  [1139301010123264] = "Klein corre pelas ruas e becos, finalmente se livrando de Dunn. (Jogabilidade Parkour reservada)",
  [1139301010123008] = "\"Todo mundo vai morrer, inclusive eu.\"",
  [1139301010122752] = "Depois que Dunn mandou Klein de volta ao apartamento Frankie, ele saiu apressado.",
  [1139301010122496] = "“Tudo bem, acabou. Volte, volte…”",
  [1139301010121984] = "\"Vamos nos conhecer adequadamente - eu sou o verdadeiro Médium Espiritual, Daly Simone.\"",
  [1139301010121728] = "Os arredores começam a ficar embaçados e a balançar; a cena derrete como uma pintura a óleo, com os vermelhos ficando mais vermelhos e os azuis mais azuis. Na cena onírica, Daly caminha diante de você, sorrindo encantadoramente, sua voz parecendo vir de todas as direções—",
  [1139301010121472] = "“Este é o Olho Espiritual, um grande auxiliador da mediunidade espírita e também uma encantadora essência floral.”",
  [1139301010121216] = "Klein se sente... calmo e confortável. Daly explica ao adicionar materiais à chama da vela—",
  [1139301010120960] = "\"Esta é a água floral Amon-Dah, que significa 'tranquilidade' em Hermes.\"",
  [1139301010120704] = "Daly se aproxima lentamente da vela e pinga algumas gotas de água floral na chama; a fragrância se espalha rapidamente pela sala. Daly sorri para Klein e diz—",
  [1139301010120448] = "Você se levantou em meio à dor, seu corpo manchado com o vermelho da corrupção. \n Você recusou firmemente.",
  [1139301010120192] = "O Crimson Will levantou-se e derrubou você. \n Gritou sobre abraçar a Mãe e a alegria de renascer.",
  [1139301010119936] = "Não muito depois, o oceano à sua frente se dissipa, revelando uma sala quente.",
  [1139301010119680] = "No Oceano Subconsciente, você viu um dragão gigante enrolado.",
  [1139165182881792] = "Se você encontrar situações perigosas, comunique-as a tempo; não aja sozinho.",
  [1139165181920768] = "Será que Klein, você passou na entrevista?",
  [1139301010118656] = "Arrodes ergueu seus tentáculos e lançou um aglomerado de luz na estrela carmesim acima de Castelo Sefirá.",
  [1103912358643202] = "Presente",
  [1139301010118400] = "Mas você cai de uma grande altura, aterrissando diante de um longo lance de escadas feitas de luz.",
  [1139301010118144] = "Você bate e bate desesperadamente, finalmente rompendo esse casulo de luz carmesim.",
  [1139301010117888] = "Quando você abre os olhos novamente, você se vê envolto em uma massa vermelha fechada.",
  [1139301010117632] = "Homem misterioso: \"Deixe o pesadelo e volte à realidade.\"",
  [1139301010117376] = "O homem misterioso jogou uma moeda de ouro no Testamento Carmesim, e a moeda de ouro gradualmente espalhou uma névoa cinzenta. \n Esta névoa cinzenta envolveu a Vontade Carmesim, selando-a com sucesso.",
  [1139301010117120] = "Um raio de luar carmesim brilha no lago. \n E uma porção da vontade da \"Mãe\" desce sobre a superfície do lago.",
  [1139301010116864] = "A marionete ficou furiosa: “Aquele que estragou o ritual, aquele que estragou o ritual!” \n Em meio aos gritos, as flores vermelhas na água de repente cresceram e se transformaram em um monstro bizarro.",
  [1139165182540032] = "Um dia, seu companheiro de equipe se torna seu oponente... e você tem que matá-lo.",
  [1139301010116352] = "Para surpresa de todos, a marionete da lua de repente começou a orar, fazendo com que videiras crescessem ao redor. \n Você e Enid foram enredados por essas trepadeiras perigosas relacionadas à \"Mãe\"!",
  [1139301010116096] = "Pete acendeu todas as velas da estaca de madeira (que era um altar) e chamou Enid.",
  [1139301010115840] = "E você... hesita por um momento, depois decide recusar (pelo menos desta vez, sim).",
  [1139301010115584] = "Por alguma razão, o boneco estava muito mais interessado em você do que em Pete. \n Ele se lançou sobre você, agarrando-se a você, e convidou você a abraçar a \"Mãe\".",
  [1139301010115328] = "Pete desenterrou um boneco do chão. \n Um momento depois, o boneco imóvel de repente ganhou vida!",
  [1139301010115072] = "O cervo caiu no chão novamente. Ao mesmo tempo—\n o ferimento no seu braço desapareceu?!",
  [1139165181921024] = "Suspiro, não acho que posso ser professor universitário.",
  [1139165182540288] = "Isso é muito cruel.",
  [1139165182882048] = "Eu entendo, Capitão Frye. Vou lidar com isso com cuidado.",
  [1139165182987264] = "(Legendas em tela preta)",
  [1139165182987008] = "Bom, tenha muito cuidado. Evite o Central Plaza e vejo você no esconderijo.",
  [1139165182986752] = "{{PlayerName}}, vá fazer coisas mais importantes.",
  [1139165182986496] = "Vou levá-los para a casa segura para refúgio o mais rápido possível. Conheço todas as estradas de Tingen, então não se preocupe conosco.",
  [1139165182985984] = "Rozanne, você é incrível...",
  [1139165182985728] = "Ele é meu colega, aquele que vai te proteger.",
  [1103912358643203] = "Futuro",
  [1139165182985472] = "Não tenha medo, aqui é {{PlayerName}}...",
  [1139165182985216] = "Irmã Rozanne!",
  [1139165182984960] = "(Apoia a testa) Suspiro...",
  [1139165182984704] = "Sim, é uma coisa boa eu ter você.",
  [1139165182984448] = "Deusa... dá tanto trabalho?",
  [1139165182984192] = "Relatórios de ações, solicitações de reposição de suprimentos, formulários de reembolso de despesas, cronogramas de patrulha 24 horas...",
  [1139165182983936] = "Você disse que ficaria. (Entrega) Estes são os detalhes específicos do trabalho.",
  [1139165182983680] = "Espere... não me diga que tudo sobrou para mim?",
  [1139165182983168] = "A propósito, se você for investigar May Manor sozinho, e as consequências?",
  [1139165182982912] = "Você gostaria de experimentar um novo sabor de café na próxima vez? Que tal um café com leite com manteiga?",
  [1139165182982656] = "Parece ótimo, então pegarei o navio para Backlund.",
  [1139165182982400] = "O trem a vapor agora leva apenas quatro horas – mas recomendo fortemente que você vá de navio. Você pode apreciar a paisagem ao longo do Rio Tussock; é definitivamente uma experiência inesquecível e você também precisa relaxar!",
  [1139165182982144] = "No entanto, ir para Backlund é realmente uma boa ideia.",
  [1139165182981888] = "Espere até que seu avanço Sequência seja maior antes de investigar mais a fundo esses assuntos.",
  [1139165182981632] = "Ainda é perigoso investigar diretamente agora, mas não se preocupe, suas ações estão sob vigilância constante.",
  [1103912358643201] = "Passado",
  [1139165182981376] = "Ele é membro do Servo da Lua e até realizou um ritual de sacrifício em um sonho... Devo continuar investigando?",
  [1139165182981120] = "\"Dandelion\"... o irmão mais velho da menina do sonho!",
  [1139165182980864] = "A propósito, Leonard disse que \"Dandelion\" pegou sua irmã e trocou Tingen por Backlund.",
  [1139165182980608] = "Se você odeia alguém, mande-o para Backlund, pois é um inferno.",
  [1139165182980352] = "Se você ama alguém, mande-o para Backlund, pois é o paraíso.",
  [1139165182980096] = "Deixe-me pensar, como o Imperador Roselle descreveu isso em seus romances—",
  [1139165182979840] = "Backlund é a capital de Loen, conhecida como a \"Cidade das Cidades\".",
  [1139165182979584] = "Mesmo que ambos venhamos do mesmo lugar, uma cidade natal distante...",
  [1139165182979328] = "<P_Heart> (Sussurrando para si mesmo) </> Pensando bem, esse antecessor... realmente não deixou espaço para aqueles que vieram depois.",
  [1139165182979072] = "Deixe-me contar um segredo: embora eu seja o dono daqui, a verdadeira investidora desta loja é a senhorita Audrey.",
  [1139165182978816] = "O café é apenas um disfarce. Este lugar é favorecido pelo destino, então apenas pessoas especiais podem abrir a porta.",
  [1139165182978560] = "Por que parece que tão poucas pessoas vêm aqui? Os negócios estão ruins?",
  [1139165182978048] = "O tempo está bom hoje. Depois da crise, a cidade precisa de reparos e nós também precisamos descansar.",
  [1139165182977536] = "Obrigado. Você gostaria de jogar uma partida? Acontece que vou verificar como Melissa e os outros estão se saindo com seus adivinhação .",
  [1139165182977280] = "Sr. Moretti, esse último jogo foi brilhante.",
  [1139165182976768] = "“O Rei do Amarelo e do Preto que exerce a boa sorte”, é esse!",
  [1139165182976512] = "No entanto, poderia haver vários mestres acima da névoa cinzenta? É melhor eu adicionar outra camada de seguro.",
  [1139165182976000] = "No entanto, não parece preciso o suficiente. Seria melhor adicionar algumas <P_Yellow> características pessoais </> .",
  [1139165182975488] = "Primeiro, em relação ao meu <P_Yellow> honorífico </> ...",
  [1139165182975232] = "Obrigado.",
  [1139165182974976] = "Você pode ler este guia de viagem de Backlund.",
  [1139165182974720] = "Ao chegar ao porto de Backlund, depois de passar pela Riverside Plaza e seguir pela estrada principal, você verá a Catedral de São Jorge, o Banco de Backlund, a Catedral do Vento Sagrado, a Sala de Concertos...",
  [1139165182974464] = "Ah, então você está viajando para Backlund. Nesse caso, você realmente deveria embarcar neste navio; afinal, seu nome é “Cidade das Cidades”.",
  [1139165182974208] = "Está tudo bem, posso esperar mais um pouco. Afinal, viajar não é algo para se apressar.",
  [1139165182973952] = "<P_Heart> (Já que Rebecca recomendou pegar o navio, suponho que devo esperar...) </>",
  [1139165182973696] = "Este navio faz uma rota popular e os ingressos estão sempre em alta demanda. Você consideraria outro meio de transporte? Ou talvez esperar um pouco mais?",
  [1033542272288256] = "Saudar",
  [1139165182973440] = "Voltar? Mas os ingressos acabaram de esgotar. Os turnos recentes estão todos lotados e os ingressos para os posteriores ainda não foram colocados à venda.",
  [1139165182973184] = "Olá, gostaria de uma passagem para Backlund...",
  [1139165182972928] = "Então, olhando dessa maneira...",
  [1139165182972672] = "Quanto ao plano de sacrifício do “Servo da Lua”, além de Tingen, há também…",
  [1139165182972416] = "Em relação aos membros do “Servo da Lua”, a situação atual é...",
  [1139165182972160] = "Dê-me uma cópia.",
  [1139165182971904] = "<P_Heart> (Poderia ser...) </>",
  [1139165182971648] = "Não! Um herói da época salva Tingen, mostrando verdadeiro brilho em meio à crise - a nova obra-prima do autor best-seller Fors: \"Guardião da Era\"!",
  [1139165182971392] = "Manchete de primeira página? Não seria o Imperador Roselle novamente, seria...",
  [1139165182971136] = "A propósito, {{Sr.|Sra.}}, você quer o jornal de hoje? A manchete da primeira página desta vez é extraordinária.",
  [1139165182970880] = "Sim, vocês com certeza vão conseguir!",
  [1139165182970624] = "Não demorará muito para que possamos ir juntos para Backlund!",
  [1139165182970368] = "Mas tudo bem, com a bicicleta posso vender jornais mais rápido e poderei recuperar o dinheiro em breve!",
  [1139165182970112] = "Ele vinha economizando há muito tempo, originalmente com a intenção de ir para Backlund. Mas tudo acabou sendo gasto na minha bicicleta...",
  [1139165182969856] = "Ele disse que isso o motiva a trabalhar duro e economizar dinheiro.",
  [1139165182969600] = "Bem, seu novo trabalho é perto das docas, então ele pode ver os navios indo para Backlund todos os dias.",
  [1139165182969344] = "Falando nisso, como está seu irmão Jack ultimamente? Ele encontrou um novo emprego?",
  [1139165182969088] = "Sim! Meu irmão comprou para mim!",
  [1139165182968832] = "Obrigado! Esta é a sua bicicleta?",
  [1139165181858560] = "Suspeitamos que você saiu com ele, mas escondeu o caderno no caminho para casa, por isso não encontramos nenhuma pista sobre você.",
  [1139165181859072] = "Embora você tenha sido influenciado por uma força desconhecida e tenha esquecido completamente essa memória, o espírito e o cérebro humanos são maravilhosos; talvez ainda haja alguns vestígios deixados para trás.",
  [1139165182476544] = "Você quer dizer que esse garoto... salvou todos vocês durante o massacre no navio?",
  [1139165182967552] = "Olá, uma passagem para Backlund, por favor.",
  [1139165182967296] = "Na jornada futura, o Sr. Louco continuará a conceder bênçãos. Louvado seja o Louco!",
  [1139165182967040] = "Não importa a época, há necessidade de portadores de lanternas para iluminar a escuridão e conduzir a luz.",
  [1139165182966784] = "O Imperador Roselle disse que este é o melhor e o pior dos tempos.",
  [1139165182966528] = "Falando nisso, o Sr. 'Fool' também já foi membro do Blackthorn.",
  [1139165182966272] = "No entanto, muitos Beyonders selvagens desconfiam deles, então lembre-se de esconder sua identidade.",
  [1139165182966016] = "O status de oficial Beyonder pode fornecer bastante ajuda.",
  [1139165182965760] = "Os pesadelos têm muitas metáforas; talvez em nossa jornada futura encontremos as respostas.",
  [1139165182965504] = "Não entendo, por que eles aparecem repetidamente em meus sonhos?",
  [1139165182965248] = "Há mais alguma coisa que você queira saber?",
  [1139165182964992] = "Tome uma xícara de café e descanse.",
  [1139165182964736] = "Eu entendo.",
  [1139165182964480] = "Mais uma coisa, o ‘Apocalipse’ é um dos principais segredos deste mundo. Não mencione isso facilmente depois de sair daqui, caso contrário, é fácil atrair o perigo.",
  [1139165182964224] = "Você é a pessoa escolhida pelo Sr. 'Tolo', com certeza você ficará bem!",
  [1139165182963968] = "Seja uma crise ou um apocalipse, enfrentaremos isso juntos.",
  [1139165182963712] = "Trouxe também a nova foto de grupo que tiramos dessa vez, olha.",
  [57314191084032] = "Uma tentativa",
  [1139165182963456] = "Rebeca! Você está de volta!",
  [1139165182963200] = "Isso mesmo, não fique tão nervoso.",
  [1139165182962944] = "Claro, lembre-se de relaxar ocasionalmente. Somente quando você estiver bem descansado você poderá ir mais longe.",
  [1139165182962688] = "De qualquer forma, aumentar seu Sequência e ficar cada vez mais forte é a melhor maneira de resistir agora.",
  [1139165182962432] = "<P_Heart> (Delicioso... um sabor quente... meu humor parece muito melhor...) </>",
  [1139165182962176] = "Esta é a revelação do Sr. Louco para você. O seu despertar do sonho representa uma nova esperança para o apocalipse.",
  [1139165182961920] = "Isso é... falar de mim?",
  [1139165182961664] = "Como disse o Sr. Louco: 'O corpo vem das estrelas, e o apocalipse se origina daí; a alma vem do Grande Antigo, e a esperança nasce daí.'",
  [1139165182961408] = "Neste jogo dos deuses, você é muito importante para o futuro do mundo.",
  [1139165182961152] = "Você se lembra da nossa conversa?",
  [1139165182960896] = "<P_Heart> (Acabei de escapar de um pesadelo de mortes repetidas... e agora vim para um mundo que enfrenta uma crise do Juízo Final?!) </>",
  [1139165182960640] = "Existem muitos deuses malignos poderosos como a Deusa Mãe da Depravação por aí, cobiçando o nosso mundo.",
  [1139165182960384] = "Não posso entrar em detalhes específicos porque envolve algumas existências de status muito elevado e envolve o céu estrelado.",
  [1139165182960128] = "\"Um olhar é lançado do céu estrelado, a terra será dilacerada e tudo no mundo deixará de existir.\"",
  [1139165182959872] = "“O apocalipse chegará em cerca de uma dúzia de anos, e todos poderão ser destruídos, incluindo os Deuses.”",
  [1139165182959616] = "Esta é a revelação divina dada uma vez pelo Sr. Louco -",
  [1139165182959360] = "Apocalipse?!",
  [1139165182959104] = "Sim. Sobre a verdade deste mundo... e o <P_Yellow> Apocalipse </> iminente.",
  [1139165182958848] = "Testes maiores?",
  [1139165182958592] = "Mas devo também lembrar-vos... que este dever de guarda enfrentará testes ainda maiores no futuro.",
  [1139165182958336] = "É isso mesmo, a guarda não é uma explosão momentânea de paixão, mas inúmeras batalhas e persistência.",
  [1139165182958080] = "A questão é: proteger.",
  [1139165182957824] = "“Somos um grupo de pobres almas que lutam constantemente contra o perigo e a loucura, e também somos os Guardiões de Tingen.”",
  [1139165182957568] = "Mas depois de experimentar tudo isto, sinto que estas duas frases são igualmente significativas quando lidas ao contrário.",
  [1139165182957312] = "\"Somos Guardiões e também um grupo de pobres coitados que lutam constantemente contra o perigo e a loucura.\"",
  [1139165182957056] = "Rozanne disse que eles se sacrificaram para proteger Tingen. Ela também disse que um ditado sempre foi transmitido entre os Vigias Noturnos:",
  [1139165182956800] = "Nesta crise, vi as figuras de muitos ex-colegas, Capitão Dunn, Velho Neil, Kenley...",
  [1139165182956544] = "Salvando e protegendo...",
  [1139165182956288] = "Lembre-se desta determinação de guardar, e Seu enfeitiçamento não terá sucesso.",
  [1139165182956032] = "Às vezes, a vontade dentro da humanidade é mais firme do que qualquer selo.",
  [1139165182955776] = "Desta vez, a influência dos sussurros sobre mim parece ter diminuído. Porque sempre penso nos cidadãos sacrificados e penso em como preciso salvar as pessoas...",
  [1139165182955520] = "Esse deus maligno nunca parou de tentar corromper você. Embora a vedação em você tenha flutuado ligeiramente, ela ainda está estável.",
  [1139165182955264] = "Em Tingen in the Mirror, ouvi novamente aquelas vozes dos pesadelos...",
  [1139165182955008] = "Felizmente, você também salvou muitas pessoas. Os guardiões de Tingen provaram mais uma vez que a escuridão nunca pode engolir completamente a luz.",
  [1139165182954752] = "Mas todos sabemos que a verdadeira dor ainda existe. Tingen perdeu alguns bons cidadãos; Karl, Charling... seus nomes merecem ser lembrados.",
  [1139165182954496] = "Ouvi do Sr. Leonard que você estabilizou o estado de todos no subconsciente coletivo.",
  [1139165182954240] = "Depois que Tingen no Espelho se desintegrou, fiquei no subconsciente coletivo por um tempo, tentando pacificar seus parentes e tornar a tristeza... um pouco mais suave.",
  [1139165182953984] = "\"Estrela\" já me disse, aqueles cidadãos que não puderam retornar do mundo dos espelhos...",
  [1139165182953728] = "Em Tingen in the Mirror, claramente tentamos o nosso melhor, mas ainda assim não conseguimos salvar todos. Só podíamos assistir impotentes enquanto eles se transformavam em fluxos de informação...",
  [1139165182953472] = "(Anel de opção)",
  [1139165182953216] = "Então, sobre o que você gostaria de falar hoje?",
  [1139165182952960] = "Você já é um qualificado Vigia Noturno . Parece que seu estado é muito bom, melhor do que eu imaginava.",
  [1147961275159040] = "Claro.",
  [1139165182952448] = "Depois de ingressar no Vigias Noturnos , primeiro me tornei um Beyonder , depois fui investigar casos de pessoas desaparecidas e mais tarde até entrei em Tingen in the Mirror...",
  [1139165182952192] = "Você deve ter passado por muita coisa, certo?",
  [1139165182951936] = "Já faz um tempo e a expressão de confusão em seu rosto parece ter desaparecido um pouco.",
  [1139165182951680] = "Vá em frente. Ajuste seu estado; em breve você terá que enfrentar a batalha final.",
  [1139165182951168] = "<P_Heart> (Um café... relaxamento mental...) </>",
  [1139165182950912] = "Às vezes, o “relaxamento mental” adequado é mais importante do que as técnicas de combate.",
  [1139165182950656] = "Isso mesmo, vamos dar um passeio, encontrar uma cafeteria e tomar um café para relaxar.",
  [1139165182950400] = "Coincidentemente, você também pode aproveitar esse tempo para descansar.",
  [1139165182950144] = "A extensão da mutação é desconhecida. Seria perigoso agir precipitadamente. Vamos examiná-lo primeiro para obter uma imagem clara.",
  [1139165182949888] = "Devemos fazer uma investigação profunda?",
  [1139165182949632] = "Nossa investigação descobriu que além de entrar no mundo dos espelhos, as pessoas desaparecidas também foram para a Mansão May.",
  [1139165182949376] = "Quando o Ritual de Sacrifício no mundo dos espelhos começou, anomalias também ocorreram na Mansão May na realidade.",
  [1139165182949120] = "É isso mesmo, a gestação da prole do deus do mal não parou.",
  [1139165182948864] = "Embora tenhamos destruído Tingen in the Mirror, a crise não parece ter sido completamente eliminada.",
  [1152495149663744] = "Depois de algum tempo...",
  [1139165182948352] = "E para guiar nosso sangue fresco.",
  [1139165182948096] = "Sim, estarei por aqui ultimamente. A extensão deste desastre é bastante grande e há muitas vítimas. Ficarei para trás para lidar com as consequências.",
  [1139165182947840] = "Volte e visite quando tiver tempo. Todo mundo sente sua falta.",
  [1139165182947584] = "Ei...",
  [1139165182947328] = "Claro que existe, você desceu as escadas.",
  [1139165182947072] = "Não se esqueça de mim; lembre-se de reservar um lugar para mim.",
  [1139165182946816] = "Quando estou livre, ainda consigo fazer alguns esboços, como o capitão procurando seu cachimbo, Daly provocando Rozanne, o Velho Neil ensinando Klein a preencher formulários de reembolso, Xiga, Luo Yao e Kenley jogando cartas...",
  [1139165182946560] = "Está tudo bem como está agora. Posso ficar em Tingen para sempre e continuar guardando este lugar.",
  [1139165182946304] = "Mas se eu me tornar um Vigia Noturno , não poderei ficar em Blackthorn.",
  [1139165182946048] = "Mas se você avançar, poderá se juntar às Luvas Vermelhas e poderemos trabalhar juntos.",
  [1139165182945792] = "Meus pensamentos não mudaram e não tenho intenção de continuar avançando em Sequência .",
  [1139165182945536] = "Talvez se você beber a poção de um Médium Espiritual, você possa completar a digestão na hora.",
  [1139165182945280] = "O acúmulo dos últimos anos, mais seus méritos desta vez, é suficiente para você trocar por diversas Sequência fórmulas e materiais de poções...",
  [1139165182945024] = "Fiquem todos parados, é hora de tirar uma foto!",
  [1139165182944768] = "Todos, cheguem perto de mim!",
  [1139165182944512] = "Tingen no Espelho está começando a se desintegrar!",
  [1139165182944256] = "Este mundo espelhado foi construído precisamente por causa disso. Com isso aqui, trazer todos de volta à realidade não é difícil.",
  [1139165182944000] = "Eu estava rastreando o Butler mais cedo e recuperei isto.",
  [1139165182943744] = "Não se preocupe, tenho uma maneira de tirar todo mundo.",
  [1139165182943488] = "Mas entramos pelo espelho, e esse caminho foi destruído há muito tempo...",
  [1139165182943232] = "Então devemos sair rapidamente. Trabalhamos tanto para salvar a todos...",
  [1139165182942976] = "Não demorará muito para que tudo aqui se transforme em nada, inclusive nós.",
  [1139165182942720] = "O Espelho Mágico do Desespero é a base deste espaço. Assim que o espelho for destruído, este lugar logo se desintegrará.",
  [1139165182942464] = "Com o Espelho Mágico do Desespero destruído, Tingen no Espelho... desaparecerá em breve, certo?",
  [1139165182942208] = "O que foi isso agora? Quase me matou...",
  [1139165182941952] = "Eu, na verdade, ainda estou vivo...",
  [1139165182941696] = "Tudo certo.",
  [1139165182941440] = "Apenas alguns arranhões.",
  [1139165182941184] = "Estão todos bem?",
  [1139165182940928] = "Afinal, os Vigias Noturnos protegeram Tingen mais de uma vez.",
  [1139165182940672] = "Boa sorte. Eu acredito que você pode destruir o Espelho do Desespero e salvar a todos.",
  [1139165182940416] = "Eu marquei todos eles e os coloquei nesta informação.",
  [1139165182940160] = "Esses espaços ocultos devem ser acessados ​​através de espelhos ocultos. Já os encontrei, mas não tenho tempo para lidar com eles...",
  [1139165182939904] = "(Entrega o Torrent)",
  [1139165182939648] = "Hmm, como podemos encontrar os outros espaços ocultos?",
  [1139165182939392] = "Eu entendo. Então vamos tentar despertar a vontade residual do Imperador.",
  [1139165182939136] = "Uma vez que esta vertente de conhecimento se manifeste e o Steam Palace reapareça na realidade, poderá provocar outra catástrofe devastadora. Devo recuperá-lo o mais rápido possível.",
  [1139165182938880] = "Foi a grande visão do meu pai, existente dentro da Coroa do Conhecimento, e agora também foi corrompida pela Deusa Mãe.",
  [1139165182938624] = "O Palácio do Vapor?",
  [1139165182938368] = "Não, essa é a Torrente de Conhecimento sobre o Steam Palace...",
  [1139165182938112] = "O que é aquilo? É também o testamento residual do Imperador?",
  [1139165182937856] = "Os outros quebra-cabeças também devem estar relacionados às suas experiências—",
  [1139165182937600] = "As respostas para esses enigmas são os contos de fadas que meu pai costumava me contar...",
  [1139165182937344] = "A Casa Segura é um desses espaços escondidos. Consegui isso depois de resolver o quebra-cabeça.",
  [1139165182937088] = "Assim.",
  [1139165182936832] = "Se conseguirmos encontrar e entrar nesses espaços ocultos e resolver os quebra-cabeças formados por suas obsessões, poderemos despertar uma parte deles...",
  [1139165182936576] = "Eu também estou tentando. Para controlar melhor Tingen no Espelho, o Servo da Lua usou o Espelho Mágico do Desespero para selar os restos do testamento de meu pai. As partes mais intensas foram divididas em vários pedaços e seladas em diferentes espaços escondidos.",
  [1139165182936320] = "Você sabe como despertar a vontade do Imperador aqui?",
  [1139165182936064] = "Bernadete Gustavo. Apenas me chame de Bernadete.",
  [1139165182935808] = "Seu pai... é o Imperador Roselle? Será que você está...",
  [1139165182935552] = "A vontade do meu pai permanece na “Coroa do Conhecimento”. Se eu puder despertar brevemente sua pós-imagem, talvez consiga destruir a barreira.",
  [1139165182935296] = "Existe alguma outra maneira? Não temos muito tempo...",
  [1139165182935040] = "Se tentarmos destruí-lo pela força, não seremos apenas corroídos pela corrupção, mas também potencialmente engolidos inteiros pela Torrente de Informação.",
  [1139165182934784] = "Esta barreira é composta por uma torrente de informações e corrupção carmesim; a primeira vem da 'Coroa do Conhecimento', e a última da Deusa Mãe da Depravação.",
  [1139165182934528] = "Leonard veio também, isso faz sentido...",
  [1139165182934272] = "Leonard mencionou você para mim; se tivermos a sua ajuda, a esperança de sucesso será muito maior.",
  [1139165182934016] = "Você sabe como destruir essa barreira? Queremos destruir o espelho e parar o sacrifício.",
  [1139165182933760] = "<P_Heart> (Relembrando) </> Lá, encontrei uma senhora vestida de pirata...",
  [1139165182933504] = "Parece uma barreira; vamos ver se podemos destruí-lo.",
  [1139165182933248] = "Sim, mas... o que é essa camada vermelha do lado de fora? Parece muito perigoso...",
  [1139165182932992] = "Assim como sugeriu a pista de Leonard, é o Espelho Mágico do Desespero.",
  [1139165182932736] = "Tudo bem. Podemos encontrar outros perigos, então tome cuidado!",
  [1139165182932480] = "Por que não nos separamos? Estamos fadados a encontrar um caminho!",
  [1139165182932224] = "É um ataque causado por uma torrente de informações. Parece que o Servo da Lua descobriu nossas ações e está tentando nos impedir!",
  [1139165182931968] = "Estou bem. O que foi isso agora?",
  [1139165182931712] = "{{PlayerName}}, você está bem?",
  [1139165182931456] = "Não resta muito tempo; devemos nos apressar para a Praça Central. Vamos.",
  [1139165182931200] = "Destruir o Espelho Mágico do Desespero pode interromper o progresso do sacrifício.",
  [1139165182930944] = "Mas... como podemos salvá-los?",
  [1139165182930688] = "As anomalias ambientais estão a piorar e os cidadãos estão constantemente a desintegrar-se... Receio que o Ritual de Sacrifício já tenha começado.",
  [1139165182930432] = "Eles foram completamente desintegrados e se tornaram sacrifícios para o deus do mal.",
  [1139165182930176] = "Onde estão meus projetos? Meus projetos!",
  [1139165182929920] = "Ok, ok, ok! Contanto que você me proteja, pagarei o que você quiser!",
  [1139165182929664] = "Senhor, não é seguro aqui. Siga-me primeiro.",
  [1139165182929408] = "<P_Heart> (balança a cabeça) </> Onde é isso? Onde fica minha fábrica? <P_Heart> (Aterrorizado) </> Eu me lembro agora, eles se transformaram em monstros!",
  [1139165182929152] = "Senhor, como você está se sentindo agora?",
  [1139165182928896] = "Devo encontrar Rozanne rapidamente.",
  [1139165182928640] = "Porque você ficou em Tingen in the Mirror por muito tempo e a corrupção era muito profunda, você se alienou completamente e se tornou um monstro?",
  [1139165182928384] = "Os fragmentos do espelho de bronze... poderiam ser os cidadãos desaparecidos?",
  [1139165182928128] = "O que devemos fazer agora é...",
  [1139165182927872] = "Que outras maneiras existem para entrar no “Reino do Espelho”…",
  [1139165182927616] = "Sobre aquelas pessoas desaparecidas...",
  [1139165182927104] = "Este pequeno espelho de bronze...",
  [1139165182926848] = "O que devemos focar agora é...",
  [1139165182926592] = "Cuidado com a Coroa do Conhecimento...",
  [1139165182926336] = "Rozanne, ela...",
  [514572247108352] = "Outro",
  [1139165182926080] = "Sobre May Manor...",
  [1139165182925824] = "Sobre Pete...",
  [1139165182924800] = "Tudo bem, vou voltar agora. Estranho... a condição de Alyosha não estava melhorando durante todo esse tempo?",
  [1139165182924544] = "<P_Heart> (Confirmando que o menino não está no local) </> Ele voltou primeiro, mas o médico não acredita em uma criança, você precisa dar um passo à frente. Volte rapidamente, será tarde demais se você chegar mais tarde!",
  [1139165182924288] = "Como poderia... Alyosha... onde está Richie?",
  [1139165182924032] = "Urso Pardo, volte rápido! O estado da sua filha piorou! O médico não a verá sem pagamento!",
  [1139165182923520] = "Deveria ser...",
  [1139165182923264] = "Rápido! Você entra primeiro.",
  [1139165182922240] = "Mas tenha cuidado; não queremos perder mais nenhum companheiro de equipe.",
  [1139165182921984] = "Ok, então junte-se a nós na guarda de Tingen e vamos iniciar a operação.",
  [1139165182921728] = "Além disso, posso ser confundido com “um dos nossos” pela Coroa do Conhecimento, então talvez eu esteja mais seguro.",
  [1139165182921472] = "Também estou pronto para entrar; assim teremos a chance de salvar a senhorita Rozanne e as pessoas desaparecidas.",
  [1139165182921216] = "Frye, devemos estar preparados para entrar no mundo dos espelhos a qualquer momento, devemos resgatar Rozanne.",
  [1139165182920960] = "{{PlayerName}}, você vai para o Lago Tingen, geralmente poucas pessoas vão lá.",
  [1139165182920704] = "Ainda irei para May Manor para investigar mais pistas e resgatar aquele grupo de trabalhadores.",
  [1139165182920448] = "Ok, irei bloquear a Praça Central para evitar que alguém se aproxime com um espelho de cobre.",
  [1139165182920192] = "Isso mesmo. Todos os outros têm tarefas, e Rebecca ainda está investigando outro Artefato Selado, então temos que dividir o trabalho entre nós três.",
  [1139165182919936] = "Já sabemos o motivo dos desaparecimentos. Resgatar Rozanne e as pessoas desaparecidas é importante, e evitar que outros cidadãos desapareçam também é importante.",
  [1139165182919680] = "Relacionado à Coroa do Conhecimento e ao Assassino Caminho ... Suspeito que seja um mundo espelhado alienado.",
  [1139165182919424] = "Também estou pensando nessa possibilidade, mas ainda não sabemos nada sobre o “Reino do Espelho”.",
  [1139165182919168] = "Podemos usar o espelho de bronze ou o feitiço para entrar no espaço oculto e resgatar Rozanne e as pessoas desaparecidas?",
  [1139165182918912] = "Esta pode ser a maneira de entrar ativamente no “Reino do Espelho”. Todos deveríamos lembrar deste encantamento, pode ser útil.",
  [1139165182918656] = "Quando eu estava na Mansão May, vi o mordomo desaparecer depois de entoar um encantamento para o espelho: “Com a torrente da era, abra o reino no espelho”.",
  [1139165182918400] = "Talvez porque você tenha selado a corrupção em você, a aura familiar fez a Coroa do Conhecimento tratá-lo como “um dos seus”.",
  [1139165182918144] = "Um pequeno espelho de cobre? Eu também tenho um. Por que não desapareci quando estava no Central Plaza e pude ver outros se dissipando?",
  [1139165182917888] = "Os espelhos de cobre foram distribuídos no festival de teatro e alguém os manipulou nos bastidores. Pedi a Luo Yao e Xiga que coletassem e destruíssem este lote de espelhos de cobre.",
  [519109611941376] = "Chegou, é isso.",
  [1139165182917632] = "Carregaram o espelho de bronze, passaram pelos pontos de desaparecimento e foram desintegrados pela Coroa do Conhecimento; as pessoas próximas não conseguiam perceber.",
  [1139165182917376] = "Há magia do Assassino Caminho no espelho de cobre, que permite ao portador se esconder nas sombras e também é a chave para abrir o espaço escondido.",
  [1139165182917120] = "As pistas fornecidas por Rebecca são muito oportunas. Este pequeno espelho de cobre é o ponto de ruptura, Rozanne deveria ter um também.",
  [1139165182916864] = "Mas como devemos encontrar o espaço oculto? Por que esses três lugares? Poderiam ser... três entradas?",
  [519109612073216] = "Tudo bem.",
  [519109612080896] = "Vou verificar a situação restante. Klein, você leva essas poções para todo mundo.",
  [1139165182916608] = "Se as pessoas recentemente desaparecidas ainda estiverem vivas, poderemos salvá-las, desde que descubramos onde estão?",
  [1139165182916352] = "É possível que tenham entrado em um espaço oculto na forma de uma torrente de conhecimento, o que não é incomum no reino Beyonder.",
  [1139165182916096] = "Os desaparecidos passaram por três locais e foram desintegrados pela Coroa do Conhecimento, será esta a verdade por trás dos casos de desaparecimento?",
  [1139165182915840] = "Há cada vez mais pistas, não sei se são boas ou ruins... Espero que Rozanne esteja bem.",
  [1139165182915584] = "Rozanne e os cidadãos se dissolvendo... Uma das habilidades da Coroa do Conhecimento é desintegrar objetos concretos em uma torrente de conhecimento.",
  [1139165182915328] = "Tentei praticar Mediunidade Espiritual nas pessoas desaparecidas recentemente, mas nenhuma delas conseguiu. Suspeito que as pessoas que desapareceram recentemente ainda estejam vivas.",
  [1139165182915072] = "OK. Através de adivinhação , determinamos que existem apenas três locais para os desaparecimentos: May Manor, Central Plaza e Tingen Lake.",
  [1139165182914816] = "Aliás, a Viscondessa e o mordomo também são membros do Moon Servant. Frye, conte-nos sobre as pistas que encontrou.",
  [1139165182914560] = "As macieiras estão crescendo de forma anormal, não de acordo com a estação. A viscondessa e o mordomo também agem de forma estranha e vão e vêm com frequência.",
  [1139165182914304] = "Moon Servant... Fui para May Manor, era muito estranho lá e alguns trabalhadores já desapareceram.",
  [1139165182914048] = "Também conheci os irmãos Pete do meu sonho. Pete é membro do Moon Servant e pode estar se preparando para um ritual.",
  [1139165182913792] = "Bom. Não há muita informação sobre os casos de pessoas desaparecidas, mas suas experiências estão todas relacionadas, até certo ponto, ao Imperador Roselle.",
  [1139165182913536] = "Rozanne... Nós não a protegemos. Vamos resumir e analisar rapidamente as pistas para encontrar o rumo da investigação.",
  [1139165182913280] = "A senhorita Rozanne passou por lá, mas logo ela e vários outros cidadãos... se transformaram em fragmentos e se dissiparam.",
  [1139165182913024] = "Encontrei o Central Plaza através de adivinhação , mas não vi a trabalhadora têxtil chamada Jenny.",
  [1139165182912768] = "Obrigado, senhorita Rozanne, adeus.",
  [1139165182912512] = "Se quiser trocar a louça, me encontre a qualquer hora. Não vou atrapalhar você de cumprir sua missão.",
  [1139165182912256] = "Se você estiver muito ocupado com o trabalho no futuro, ajudarei você a pedir refeições de trabalho.",
  [1139165182912000] = "Claro, o Old Will's Restaurant é acessível e tem um gosto muito bom também.",
  [1139165182911744] = "Senhorita Rozanne, eu escolhi, todos parecem deliciosos.",
  [1139165182911488] = "Esse é um cardápio que peguei quando passei pelo restaurante, dê uma olhada primeiro.",
  [1139165182911232] = "Eu entendo. O que posso pedir? Eu gostaria de experimentar.",
  [1139165182910976] = "Ele contará os pratos e as quantidades das refeições de trabalho e depois os entregará na hora do almoço e do jantar respectivamente.",
  [1139165182910720] = "Isso mesmo. Todos os dias, às 10h30 e às 15h, o Old Will's Restaurant enviará um garçom para Blackthorn.",
  [1139165182910464] = "Refeições de trabalho auto-pagas? Eles serão entregues à Blackthorn Security Company?",
  [1139165182910208] = "Aliás, você precisa pedir uma refeição de trabalho? Embora... seja às suas próprias custas.",
  [1139165182909952] = "A Sra. Orianna estava ocupada hoje, então vim ajudar Frye a comprar alguns materiais de escritório.",
  [1139165182909696] = "Eu os manterei seguros. Adeus, Sra.",
  [1139165182909440] = "Tudo bem, policial, mas por favor não os danifique, Jenny os estimava muito.",
  [1139165182909184] = "Sra. Slin, vou levar os manuscritos, talvez isso ajude a encontrar Jenny.",
  [1139165182908928] = "<P_Heart> (Então, de acordo com a orientação da vareta radiestesia, posso descobrir onde Jenny está.) </>",
  [1139165182908672] = "<P_Heart> (Deixe-me pensar... preciso usar os pertences pessoais de Jenny para realizar o adivinhação .) </>",
  [1139165182908416] = "<P_Heart> (Vara radiestesia adivinhação ? Esta é uma das habilidades que o Sr. Tolo enxertou em mim.) </>",
  [1139165182908160] = "A propósito, parecem desenhos mecânicos desenhados por Jenny—",
  [1139165182907904] = "Eu sei que ela quer estudar engenharia mecânica, deixe-me ver seus manuscritos primeiro.",
  [1139165182907648] = "Eu realmente espero que Jenny possa realizar seu desejo e entrar na Escola Técnica de Tingen.",
  [1139165182907392] = "Quando não estava ocupada, ela lia livros e escrevia ou desenhava no papel.",
  [1139165182907136] = "Ah, eu estava arrumando o armário hoje e encontrei alguns manuscritos de Jenny.",
  [1139165182906880] = "Ainda não... São poucas pistas, você se lembrou de mais alguma coisa?",
  [1139165182906624] = "Ah, jovem oficial. Pobre Jenny, houve algum progresso?",
  [1139165182906368] = "Olá, Sra. Slin, estou aqui para investigar o caso do desaparecimento de Jenny.",
  [1139165182906112] = "Sim, Charlie também é muito cauteloso; ele nunca toca pessoalmente nessas coisas perigosas.",
  [1139165182905856] = "Quer dizer que ele não esteve envolvido no comércio exterior recentemente, então não teve contato com contrabando?",
  [1139165182905600] = "Ele voltou do Continente Sul no início do mês e está em Tingen, aguardando a abertura do Roselle Drama Festival.",
  [1139165182905344] = "Isso... eu garanto que não, não recebo nenhuma mercadoria enviada por Charlie há quase um mês.",
  [1139165182905088] = "Eu quero saber, Charlie esteve em contato com algum item oculto recentemente?",
  [1139165182904832] = "Tudo graças às rotas marítimas abertas pelo Imperador Roselle, desta vez ele patrocinou 5.000 libras para o festival de teatro!",
  [1139165182904576] = "Tudo bem, Charlie é um bom homem, de um mestiço de favela a um magnata no Golden Phoenix District...",
  [1139165182904320] = "Sou responsável pela investigação do caso do desaparecimento de Charlie, não estou verificando hoje o comércio de contrabando.",
  [1139165182904064] = "Você é um policial? Os funcionários e a Igreja não ficam fora deste lugar?",
  [1139165182903808] = "Olá, Sr. Paul, esta é a minha identificação, estou aqui para lhe perguntar uma coisa.",
  [1139165182903040] = "Está tudo bem, eu vi sua coragem.",
  [1139165182902784] = "Eu perdi, Sr. Swain, mas...",
  [1139165182902528] = "Apenas diga a ele—\" <P_Yellow> A tempestade é mais violenta que uma bebida forte. </> \"",
  [1139165182902272] = "Encontre a sala de bilhar primeiro, se alguém te impedir...",
  [1139165182902016] = "Nada mal, uma luta maravilhosa, você tem potencial para ser boxeador.",
  [1139165182901760] = "Eu ganhei, Sr. Swain, posso...",
  [1139165182901504] = "Isso não será necessário... Posso subir e tentar.",
  [1139165182901248] = "Se você não ousar, volte e mande outra pessoa investigar.",
  [1139165182900992] = "Você está dizendo que quer que eu suba ao palco e lute uma luta de boxe?",
  [1139165182900736] = "Você tem coragem de brigar? Habilidade e coragem são mais convincentes do que um distintivo policial.",
  [1139165182900480] = "É claro que durante tantos anos tivemos um entendimento tácito, mas...",
  [1139165182900224] = "Isto envolve a segurança de um grande número de cidadãos em Tingen, por favor ajude.",
  [1139165182899968] = "Esta é a minha identificação, quero pedir informações ao Paul sobre o caso de pessoas desaparecidas.",
  [1139165182899712] = "Sinto muito, o mercado não aceita estranhos.",
  [1139165182899456] = "Tenho alguns negócios para tratar, quero entrar no mercado underground.",
  [1139165182899200] = "Uma cara nova, o que você quer comigo?",
  [1139165182897920] = "<P_Heart> (E esta é uma despesa oficial, talvez possa ser reembolsada?) </> Tudo bem, eu pago.",
  [1139165182897664] = "Ah? <P_Heart> (A senhorita Justiça me deu 20.000 libras de ouro, eu deveria usar esse dinheiro para fazer algumas boas ações também.) </>",
  [1139165182897408] = "Circunstâncias incomuns... A polícia pode ajudar a pagar o aluguel de Karl? 2 dólares.",
  [1139165182897152] = "Já anotei tudo, se houver alguma circunstância incomum, denuncie à polícia a tempo.",
  [1139165182896896] = "Não, o primeiro, Andy, sai às cinco da manhã, e o último, Dylan, volta à uma da manhã.",
  [1139165182896640] = "Há algo incomum nos outros? Quando eles saem e quando voltam?",
  [1139165182896384] = "Além de Karl e Tony, estão Andy, Bob, Kyle e Dylan.",
  [1139165182896128] = "Você acabou de dizer que seis pessoas moram em um quarto? Quem são todos eles?",
  [1139165182895872] = "Não se preocupe, estou apenas aprendendo algumas informações sobre o caso do desaparecimento de Karl.",
  [1139165182895616] = "Droga, Tony, você realmente chamou a polícia? Isso afetará o aluguel!",
  [1139165182895360] = "Olá, Sr. Franky, Sr. Tony, sou policial.",
  [1139165182895104] = "Não, ele estará de volta. Já denunciei à polícia, eles vão encontrá-lo.",
  [1139165182894848] = "E agora? Um limpador lavando locomotivas? Talvez ele tenha morrido nos esgotos há muito tempo.",
  [1139165182894592] = "Ele instalou cabos submarinos, construiu ferrovias, pontes de aço e até aeronaves.",
  [1139165182894336] = "Você não pode insultar Karl assim, suas contribuições quando ele era jovem são dignas do respeito de todos.",
  [1139165182894080] = "Não confio em vocês, pobres ratos, muito menos em um velho rato alcoólatra.",
  [1139165182893824] = "Karl deve ter encontrado alguma coisa, garanto que ele pagará quando voltar.",
  [1139165182893568] = "Mas Karl está com o aluguel atrasado há uma semana e ninguém sabe onde ele está agora.",
  [1139165182893312] = "Tony, sou o proprietário mais generoso de Tingen, permito que vocês seis aluguem um quarto juntos.",
  [1139165182893056] = "Por favor, não pode jogar a bagagem de Karl na rua, Sr. Franky.",
  [1139165182892800] = "Bom, muito sensato. Vamos nos separar. Lembre-se, estamos protegendo Tingen.",
  [1139165182892544] = "Tudo bem, então irei verificar primeiro as informações das pessoas desaparecidas e investigarei o assunto dos irmãos quando houver mais pistas.",
  [1139165182892288] = "Eu também tenho que completar minha própria tarefa, que é investigar um Artefato Selado relacionado ao Assassino Caminho.",
  [1139165182892032] = "Então você deve terminar a tarefa em questão primeiro. Rastrear \"Dandelion\" agora provavelmente será perigoso.",
  [1139165182891776] = "Na verdade não, o Capitão Frye me enviou para investigar e verificar algumas informações sobre os casos de desaparecimento.",
  [1139165182891520] = "Espere, o Sr. Leonard ou o Capitão Frye pediram para você investigá-lo?",
  [1139165182891264] = "Parece que o pesadelo é de fato uma espécie de presságio. Devo me apressar para encontrá-lo e detê-lo.",
  [1139165182891008] = "Os seguidores sacrificam ao deus maligno que adoram. É muito provável que \"Dandelion\" também esteja se preparando para um ritual de sacrifício.",
  [1139165182890752] = "O Servo da Lua só recentemente se tornou ativo em Tingen e as pistas que temos são muito limitadas.",
  [1139165182890496] = "Eu tenho um diagrama aqui, desenhei casualmente, dê uma olhada.",
  [1139165182890240] = "Então o irmão da garota também é membro do Moon Servant, e seu codinome é Sr. Dandelion.",
  [1139165182889984] = "Eles são seguidores de um deus maligno, e aqueles com codinomes são todos líderes ou chefes do Servo da Lua.",
  [1139165182889728] = "Os recentes sacrifícios e casos de deuses malignos em Tingen estão todos relacionados às atividades desta organização.",
  [1139165182889472] = "Todos eles pertencem a uma organização maligna que adora a Deusa Mãe da Depravação – a Serva da Lua.",
  [1139165182889216] = "Eles pareciam se referir um ao outro por codinomes: Jacinto, Dente de Leão...",
  [1139165182888960] = "A propósito, Rebecca, você sabe quem eram aquelas pessoas agora há pouco?",
  [1139165182888704] = "É muito simples, vou te ensinar, segure bem essa adaga de prata.",
  [1139165182888448] = "Já ouvi o Sr. Leonard mencionar isso, mas ainda não experimentei.",
  [1139165182888192] = "Precisamos limpar a cena o mais rápido possível. Você sabe como montar um Wall de Espiritualidade ?",
  [1139165182887936] = "Aliás, há vestígios de Beyonder combate aqui, bem como corrupção residual.",
  [1139165182887680] = "Não, por favor, me chame de Rebecca. Ainda não completei dezoito anos.",
  [1139165182887424] = "Tudo bem, então devo ligar para você... sênior?",
  [1139165182887168] = "Também sou um bom amigo da Susie e... há algumas coisas que são inconvenientes de revelar por enquanto.",
  [1139165182886912] = "Como sou um antigo funcionário da Blackthorn Security Company, daqui a dois anos fará dois anos.",
  [1139165182886656] = "Obrigado pela ajuda. A propósito, por que você me chamou de novo colega?",
  [1139165182886400] = "Apenas média. Meu nome é Rebecca e sou a proprietária do Fate Café.",
  [804913647078656] = "Sim.",
  [1139165182886144] = "Nos conhecemos no café? Você é realmente um Beyonder poderoso!",
  [1139165182885888] = "Olhando para seus olhos confusos, você não se lembra de mim tão cedo?",
  [1139165182885632] = "O café está pronto! Senhorita Justiça, uma nova convidada?",
  [1139165182885376] = "Se você se sentir entediado, vá brincar com meu lindo bichinho de estimação!",
  [1139165182885120] = "Desculpe, amigo, perdoe-nos por não levá-lo a sério agora.",
  [1139165182884864] = "O Sr. \"Dandelion\" é um dos servos de Deus mais valorizados e potenciais.",
  [1139165182884608] = "A diferença entre um servo de Deus e outro é maior do que entre um humano e um babuíno de cabelos cacheados.",
  [1139165182884352] = "Ambos são lixo, por que você tem tanto a dizer? Cale-se.",
  [360778595123968] = "Talvez...",
  [1139165182884096] = "Vocês são todos servos de Deus, por que tratam suas palavras como ordens?",
  [1139165182883840] = "O Sr. \"Dandelion\" me ordenou que o impedisse e devo obedecer.",
  [1139165182883584] = "Espere, eu sei o que você vai dizer, mas isso não é possível.",
  [1139165182883328] = "Bom, Leonard e eu também partiremos em breve.",
  [360778595239424] = "Mas...",
  [360778595198208] = "Celestial Digno do Céu e da Terra pela Imortalidade",
  [360778595233536] = "A cura está indo bem, acorde logo.",
  [1139165182883072] = "Tudo bem, então irei investigar primeiro os casos de pessoas desaparecidas.",
  [1139165182882816] = "Hmm... Ainda temos algumas coisas para conversar e relembrar os velhos tempos enquanto estamos nisso.",
  [1139301010114304] = "\"Você está acordado?\" \n Uma garotinha próxima cumprimenta você. Só então você percebe que está em um acampamento.",
  [1139301010119424] = "Você entrega sua mão para esta senhora. Um momento depois, um poder quente flui por todo o seu corpo.",
  [1139165182881536] = "Não tem problema, Capitão Frye. Talvez eu consiga encontrar algumas novas pistas.",
  [1139165182881280] = "Acabei de adicionar algumas dicas; você saberá como investigar quando terminar de lê-los.",
  [1139165182881024] = "Hmm, estes são os casos de pessoas desaparecidas transferidos do departamento de polícia; algumas informações precisam ser verificadas.",
  [1139165182880768] = "Quanto a mim? Como novo funcionário da Blackthorn Security Company, há algo que eu possa fazer?",
  [1139165182880512] = "Investigarei mais detalhadamente os casos de pessoas desaparecidas e verificarei se eles estão relacionados à Coroa do Conhecimento.",
  [1139165182880256] = "A direção da investigação é muito clara. Há menos pistas em May Manor, então irei investigar lá primeiro.",
  [1139165182880000] = "A propósito, conheci o mordomo de May Manor. Ele está recrutando trabalhadores temporários para podar o pomar de maçãs.",
  [1139165182879744] = "Sim, este lote de casos de desaparecimento tem muitos pontos em comum. Todos os rituais de sacrifício apontam para a Deusa Mãe da Depravação.",
  [1139165182879488] = "Essa é sua especulação agora? Muito afiado. Acho que o Capitão Frye pensa da mesma forma.",
  [1139165182879232] = "Poderia ser causado pela Coroa do Conhecimento, com o poder nos bastidores sendo a Deusa Mãe da Depravação e seus seguidores?",
  [862024900820992] = "Observar",
  [1139165182878976] = "Se um grande número de casos anormais aparecer numa área, há uma grande probabilidade de influência de uma força oculta.",
  [1139165182878720] = "A Coroa do Conhecimento foi ativada e escapou devido à corrupção... Poderia o poder nos bastidores ser a Deusa Mãe da Depravação?",
  [1139165182878464] = "Poderiam os casos bizarros de desaparecimentos e sacrifícios em Tingen estar relacionados com a desaparecida Coroa do Conhecimento?",
  [1139165182878208] = "Tingen teve um grande número de casos anormais recentemente. Com qual deles está relacionado?",
  [1139165182877952] = "Já está tonto? A investigação apenas começou, as pistas são escassas, é preciso aprender a analisar e fazer deduções razoáveis.",
  [1139165182877696] = "Isso parece tão complicado... Desaparecimentos, sacrifícios, um Artefato Selado de Grau 0, corrupção e o Imperador Roselle?",
  [1139165182877440] = "Há notícias ainda piores. As pistas indicam que o local onde a Coroa do Conhecimento desapareceu é provavelmente em Tingen.",
  [1139165182877184] = "Ativado e escapado? Sem selo, seu poder é suficiente para destruir um país, ou mesmo o mundo inteiro.",
  [1139165182876928] = "Pertence à Igreja do Deus do Vapor e da Máquina em Intis, e recentemente escapou para Loen devido à ativação da corrupção.",
  [1139165182876672] = "É uma relíquia de quando o Imperador Roselle foi assassinado e contém corrupção residual da Deusa Mãe da Depravação.",
  [1139165182876416] = "Sim, é chamada de “Coroa do Conhecimento”. Sua aparência é a de uma coroa, e suas habilidades estão relacionadas ao Espreitador de Mistérios Caminho.",
  [1139165182876160] = "Nota 0 novamente... Extremamente perigoso, não deve ser questionado, não deve ser divulgado, não deve ser descrito, não deve ser arrombado.",
  [1139165182875904] = "Mas de acordo com as ordens da sede da Igreja, devo primeiro informá-los sobre o desaparecimento do Artefato Selado Grau 0.",
  [1139165182875648] = "Eu entendo. Meu retorno a Tingen desta vez é para descobrir a verdade com você e proteger Tingen.",
  [1139165182875392] = "Parece que uma grave crise está se formando em Tingen. Esse sentimento não é muito bom.",
  [1139165182875136] = "Recentemente, tem havido casos frequentes de desaparecimentos e sacrifícios, e também há sinais de anormalidades em May Manor, nos subúrbios.",
  [1139165182874880] = "...Resumindo, caminhe pela estrada principal depois de descer e, se se perder, volte para a estrada principal.",
  [1139165182874624] = "Acontece que Leonard deveria estar procurando por você. Vá para o porão e dê uma olhada!",
  [1139165182874368] = "Inteligente, você tem as qualidades de um Vigia Noturno . Nossos colegas estão investigando.",
  [1139165182874112] = "É muito estranho... Poderia haver algum poder nos bastidores impulsionando tudo isso?",
  [1139165182873856] = "Mas Tingen está envolta na maré de uma era de mais de cem anos atrás, o que não é muito certo.",
  [1139165182873600] = "Há também pessoas que vivem na onda da Revolução Industrial impulsionada por Roselle.",
  [1139165182873344] = "Estou um pouco surpreso; acontece que este mundo tem mais do que apenas deuses e Beyonders ...",
  [1139165182873088] = "Aliás, também comprei um selo da Roselle... vou dar para você.",
  [1139165182872832] = "Sim, significa que ambos assinamos os nossos nomes no retrato da Roselle.",
  [1139165182872576] = "Senhorita Rozanne, você tem esse espelhinho de bronze também? Eu também tenho um.",
  [1139165182872320] = "Claro. Adeus, Tom, e desejo tudo de bom para você também!",
  [1139165182872064] = "Tudo bem, vendo jornais todos os dias em uma rota fixa, nos encontraremos novamente.",
  [1139165182871808] = "Desculpe, Tom, está ficando tarde, tenho outra coisa para fazer, preciso voltar.",
  [1139165182871552] = "{{Sr.| Sra.}}, pretendo ir à Iron Cross Street para vender jornais. Você ainda vai?",
  [1139165182871296] = "Adeus, Jack, desejo-lhe tudo de bom.",
  [1139165182871040] = "Adeus, Jack! Não se preocupe comigo também, venderei bem jornais.",
  [1139165182870784] = "Não se preocupe, voltarei em duas semanas com oito libras de ouro!",
  [1139165182870528] = "Meu? Desculpe... já tenho um emprego formal.",
  [1139165182870272] = "Como é? Depois de assistir por tanto tempo, você está interessado?",
  [1139165182870016] = "Ok, então vou acompanhar o irmão na fila e me inscrever!",
  [1139165182869760] = "Ouvi dizer que a Viscondessa de May Manor é muito generosa e não atrasa os salários.",
  [1139165182869504] = "Acabei de perder meu emprego e não posso ficar sentado. Eu poderia muito bem ir para May Manor para um trabalho de curto prazo.",
  [1139165182869248] = "Também basta comprar uma bicicleta. Mas parece muito difícil, o irmão vai se inscrever?",
  [1139165182868992] = "Oito libras por duas semanas, incluindo hospedagem e alimentação. Esse dinheiro é suficiente para ir para Backlund.",
  [1139165182868736] = "Tanto... quatro libras de ouro por semana, três vezes o salário de um operário siderúrgico!",
  [1139165182868480] = "Tem um edital de recrutamento ali, dá uma olhada no que precisa ser feito e quanto é o salário.",
  [1139165182868224] = "Não se aglomere, não tenha pressa. Quanto mais gente, melhor, não há limite de vagas.",
  [1139165182867968] = "Sr. Butler, Sr. Butler, estou me inscrevendo, sou muito capaz de trabalhar duro!",
  [1139165182867712] = "Empregos de curto prazo com altos salários em May Manor, quem quiser se inscrever, venha e faça fila para se inscrever!",
  [1139165182867456] = "Tom é incrível. Quando seu irmão economizar dinheiro suficiente, ele o levará a Backlund para ver a ponte.",
  [1139165182867200] = "Irmão, também economizei algum dinheiro. Posso pagar o aluguel e comprar comida.",
  [1139165182866944] = "Está tudo bem, há muitas oportunidades nesta época e em breve poderei encontrar outro emprego.",
  [1139165182866688] = "O irmão não pode mais trabalhar aqui? Você é o melhor metalúrgico!",
  [1139165182866432] = "Muitas pessoas estão passando por momentos difíceis e quero ver se consigo lutar por alguma compensação.",
  [1139165182866176] = "A siderúrgica atualizou recentemente seus equipamentos e uma dúzia de meus colegas de trabalho e eu fomos demitidos.",
  [1139165182865920] = "Estou bem, meu trabalho é segurança. O que aconteceu agora?",
  [1139165182865664] = "Obrigado pela sua ajuda, {{Sr.| EM.}}. Você não está ferido, está?",
  [1139165182865408] = "{{PlayerName}}{{ Sr.| Sra.}} é minha cliente e nova amiga.",
  [1139165182865152] = "Isso mesmo, então, como antes, vou levá-lo até lá.",
  [1139165182864896] = "Vá ao distrito fabril para vender jornais; os trabalhadores também precisam entender as novidades e acompanhar os tempos.",
  [1139165182864640] = "Eu entendo, um dia você economizará o suficiente. Para onde você vai a seguir?",
  [1139165182864384] = "Mas meu irmão e eu ainda temos que pagar aluguel e comer, então o dinheiro que podemos economizar a cada semana é muito pouco.",
  [1139165182864128] = "Ainda está muito longe. Uma bicicleta custa cerca de cinco libras de ouro, o que não parece muito...",
  [1139165182863872] = "Isso é ótimo, talvez você consiga comprar uma bicicleta em breve.",
  [1139165182863616] = "Muito bem, exceto o Jornal Honesto, todo o resto está quase esgotado.",
  [1139165182863360] = "Eu já vi o suficiente. E você, como estão as vendas?",
  [1139165182863104] = "Obrigado, acabei de assinar meu nome e tem até um presentinho?",
  [1139165182862848] = "Isto é para você, um pequeno espelho de bronze, um presente do patrocinador do festival de teatro.",
  [1139165182862592] = "Obrigado, seu nome também subirá ao céu junto com o retrato do Imperador.",
  [1139165182862336] = "Obrigado, por favor venha comigo.",
  [1139165182862080] = "Parece incrível, vou assiná-lo também.",
  [1139165182861824] = "Ah, estou trabalhando meio período no festival de teatro e gostaria de convidá-lo para assinar o retrato do Imperador Roselle.",
  [1139165182861568] = "Olá? Desculpe interromper, há algo que você precisa de mim?",
  [1139165182861312] = "Suspeito que ele veio de outro mundo, assim como está escrito nos romances populares!",
  [1139165182861056] = "Louvado seja o Imperador Roselle, ele é simplesmente um gigante que transcendeu a época.",
  [1139165182860800] = "Seu ato gentil protegeu um admirador do Imperador Roselle.",
  [1139165182860544] = "Com licença, meu nome é Danny, estou no segundo ano do Departamento de Engenharia Mecânica da Escola Técnica de Tingen.",
  [1139165182860288] = "Não... por favor, não pegue meu ingresso...",
  [1139165182860032] = "Na frente da Gangue Dragon Hunter, não fale se você quer ou não.",
  [1139165182859776] = "Eu, eu não quero vendê-lo. Eu realmente quero ver a peça do Imperador Roselle.",
  [1139165182859520] = "Muito lucrativo, certo? Também queremos ganhar dinheiro, por isso queremos comprar o seu bilhete.",
  [1139165182859264] = "Mas, se meu ingresso for revendido, valerá pelo menos 7 libras de ouro!",
  [1139165182859008] = "Poderíamos ter simplesmente roubado você, mas estamos dispostos a pagar-lhe um centavo.",
  [1139165182858752] = "Desculpe, também não estou vendendo ingressos.",
  [1139165182858496] = "Área VIP 10 libras, área frontal 7 libras, área intermediária 3 libras, área traseira 1 libra.",
  [1139165182858240] = "Então você está vendendo ingressos? Venda-os para mim, eu os comprarei por um preço alto.",
  [1139165182857984] = "Desculpe, estou apenas olhando, não comprando uma passagem.",
  [1139165182857728] = "Área VIP 15 libras, área frontal 10 libras, área intermediária 5 libras, área traseira 2 libras.",
  [1139165182857472] = "Comprando uma passagem, {{Sr.| EM.}}? Eu tenho alguns, não há necessidade de fazer fila.",
  [1139165182857216] = "Está muito certo; este é o poema mais famoso do Imperador Roselle!",
  [1139165182856960] = "Parece tão familiar... mas sempre sinto que algo não está certo.",
  [1139165182856704] = "\"Pés vermelho-alaranjados, cortando silenciosamente as ondas cintilantes.\"",
  [1139165182856448] = "\"Penas brancas flutuando e ondulando na superfície esmeralda da água.\"",
  [1139165182856192] = "\"Esticando o pescoço em direção ao céu, cantando canções elegantes.\"",
  [1139165182855936] = "\"Ah, três elfos brancos e macios—\"",
  [1139165182855680] = "A letra é bem escrita e o canto é muito comovente...",
  [1139165182855424] = "Elogie sua generosidade e elogie a grande invenção do Imperador Roselle!",
  [1139165182855168] = "Por apenas um sou, você pode experimentá-lo vezes ilimitadas. Sente-se quando quiser.",
  [1139165182854912] = "Tudo bem, agora que você mencionou... eu realmente quero tentar.",
  [1139165182854656] = "O do Museu Backlund é gêmeo daquele que está à sua frente.",
  [1139165182854400] = "É muito único; é o vaso sanitário com descarga dourada inventado pelo Imperador Roselle.",
  [1139165182854144] = "Huh? Eu não pretendia sentar nele... Por que tem um banheiro aqui?",
  [1139165182853888] = "Espere! Desculpe, {{Sr.| Sra.}}, você não pode sentar-se ainda.",
  [1139165182853632] = "Você está prestes a andar de bicicleta para levar o jornaleiro ao próximo missão local para conhecer os costumes locais das ruas de Tingen, <P_Yellow> levando cerca de 1-2 minutos </> . Você quer viajar rápido? (A escolha de fazer isso não afetará a aquisição de missão recompensas)",
  [1139165182853376] = "Realmente? Pelo bem da bicicleta, estarei ao seu dispor, {{Sr.| EM.}}.",
  [1139095388578560] = "Procure os itens necessários na barra",
  [1139094851815168] = "[Lugar] Carta de Tarô da Lua Vermelha",
  [1139094851684096] = "Esconder Deliberadamente",
  [1139094851690240] = "Você também está com a gangue Dragon Hunter?",
  [1139165182853120] = "Tudo bem, eu tenho uma bicicleta. Vou levá-lo até lá e você pode me dar instruções.",
  [1139165182852864] = "Claro, mas é um pouco longe e costumo caminhar até lá.",
  [1139165182852608] = "Também quero ir ao Grande Teatro para dar uma olhada. É conveniente para você me levar com você?",
  [1139165182852352] = "Sim, todo mundo está falando sobre Roselle ultimamente, e minhas coisas estão vendendo muito bem.",
  [1139165182852096] = "Grande Teatro? Festival de Drama Roselle? Por que é Roselle de novo...",
  [1139165182851840] = "Tenho que ir ao Grande Teatro. O Roselle Drama Festival está vendendo ingressos; deve ser muito animado.",
  [1139165182851584] = "Este selo tem significado comemorativo, 7 centavos. Obrigado pelo seu patrocínio novamente.",
  [1139165182851328] = "Terminei de procurar, aprendi muito conhecimento. Hmm... vou comprar um selo.",
  [1139165182851072] = "Olha a bicicleta? Claro, isso é um comércio justo.",
  [1139165182850816] = "Sem problemas. Você pode me permitir olhar sua bicicleta?",
  [1139165182850560] = "Você vende essas coisas também? Cavalheiro, posso dar uma olhada primeiro?",
  [1139165182850304] = "Além de jornais, há também cartazes, cartões postais e selos do Imperador Roselle.",
  [1139165182850048] = "Eu lembro. E quanto a outros jornais, como o Tussock Times ou o Story Reviews?",
  [1139165182849792] = "O jornal honesto de Tingen? Acho que já comprei.",
  [1139165182849536] = "Como pode haver um trabalho tão bom... Aliás, você quer comprar um jornal?",
  [1139165182849280] = "Você poderia dizer isso. Minha empresa dá uma bicicleta a cada funcionário.",
  [1139165182849024] = "Tenho que ir à festa de aniversário da Selena amanhã.",
  [1139165182848768] = "Embora esta não seja a primeira vez que estou acima da névoa cinzenta, ela ainda consumiu uma grande quantidade de espiritualidade . É melhor descansar um pouco.",
  [1139165182848512] = "Seguindo sua vontade.",
  [1139165182848256] = "Senhoras e senhores, lembrem-se disso. Isso é tudo por hoje.",
  [1139165182848000] = "<P_Heart> (Se a Magia Ritual realmente aponta para Ele, então, então devo usar o título honorífico \"Ele\" para me dirigir a Ele. Como sou afortunado; sempre me comportei de forma cooperativa e não fiz nada estúpido, até mesmo minha investigação estava dentro de limites razoáveis...) </>",
  [1139165182847744] = "<P_Heart> (Descrição em três partes... quase equivalente às sete existências ortodoxas.) </>",
  [1139165182847488] = "Você é o Rei do Amarelo e do Preto que exerce boa sorte",
  [1139165182847232] = "Você é o governante misterioso acima da névoa cinzenta",
  [1139165182846976] = "O tolo que não pertence a esta época",
  [1139165182846720] = "Isso é exatamente o que esperávamos. Sr. Tolo, posso perguntar qual é o encantamento correspondente?",
  [1139165182846464] = "Você pode experimentar um Ritual Mágico em seu tempo livre; permitirá que você ore por ajuda ou peça licença com antecedência quando encontrar problemas.",
  [1139165182846208] = "Por favor, me instrua.",
  [1139165182845952] = "Tenho algo que requer sua cooperação.",
  [1139165182845440] = "Muito provavelmente, morreria no local. Se conseguisse sobreviver, deveria se tornar uma criatura extraordinária e poderia até se tornar mais inteligente.",
  [1139165182845184] = "<P_Heart> (Que tipo de pergunta é essa... Não, as emoções de Justice estão um pouco confusas. Será que ela fez algo tolo assim?) </>",
  [1139165182844928] = "Eu tenho outra pergunta. Se, e quero dizer, se, um animal comum bebesse uma poção Sequência 9, o que aconteceria?",
  [1139165182844672] = "<P_Heart> (Como esperado do Sr. Tolo, entendi completamente o significado de \"Atuar\".) </>",
  [1139165182844160] = "A carta-convite é o nome da poção Sequência?",
  [1139165182843904] = "Devemos \"agir\" da maneira descrita na carta-convite para entrar furtivamente no castelo, eliminar os inimigos e nos tornar o mestre do castelo.",
  [1139165182843648] = "Deixe-me usar um exemplo vívido para explicar. O poder central de uma poção Sequência é como um castelo, e temos uma carta-convite dada pelo dono do castelo.",
  [1139165182843392] = "Sr. \"Tolo\", Sr. \"Enforcado\", tenho uma pergunta que gostaria de fazer. <P_Yellow> Atuar </> , o que isso realmente significa?",
  [1139165182843136] = "Desculpe, eu estava absorto na leitura.",
  [1139165182842880] = "<P_Heart> (No entanto, também preciso considerar me tornar mais forte para ter a chance de voltar para casa.) </>",
  [1139165182842624] = "<P_Heart> (Ei, Imperador, onde está sua integridade...) </>",
  [1139165182842368] = "Muito bom.",
  [1139165182842112] = "Eu tenho uma página.",
  [1139165182841856] = "Encontrei duas páginas do diário do Imperador Roselle.",
  [1139165182841600] = "Senhoras e senhores, encontraram o diário de Roselle?",
  [1139165182841344] = "Obrigado, Sr. Tolo.",
  [1139165182841088] = "Parabéns, senhorita Justiça. Você agora é um Beyonder .",
  [1139165182840832] = "<P_Heart> (Marinheiro... Abençoado pelo Mar... Tempestade... A cor de sua aura ficou um pouco mais pura... Ele avançou?) </>",
  [1139165182840576] = "Boa tarde, Sr. Enforcado.",
  [633321382011136] = "Obrigado",
  [1139165182840320] = "Boa tarde, Sr. Tolo.",
  [1139165182840064] = "Muito bem. Já era hora; Eu deveria ir acima da névoa cinzenta.",
  [633321918880000] = "Folhear",
  [1139165182839808] = "\"O Rei Amarelo e Preto que controla a boa sorte!\"",
  [1139165182839552] = "No entanto... e se houver vários governantes acima da névoa cinzenta? Eu deveria adicionar outra camada de seguro.",
  [1139165182839296] = "Dessa forma, posso prender a névoa cinzenta a mim mesmo.",
  [1139165182839040] = "\"O misterioso governante acima da névoa cinzenta\".",
  [1139165182838784] = "“O Louco que não pertence a esta época”... Não é suficientemente preciso, é necessário acrescentar uma frase.",
  [1139165182838528] = "\"O Louco de outro mundo\"? É bastante preciso. Não, isso irá expor meu maior segredo.",
  [1139165182838272] = "A descrição do encantamento apontando para mim...",
  [1139165182838016] = "Não é apenas esta a diferença entre mensagens online e offline no QQ!",
  [1139165182837760] = "Desta forma, não importa onde a Justiça e o Enforcado realizem seus rituais, poderei receber suas mensagens desde que entre no espaço acima da névoa cinzenta.",
  [1139165182476032] = "Se você estivesse lá, teria uma impressão tão profunda quanto eu. Depois que voltei, fiz um esboço querendo encontrá-lo para expressar minha gratidão.",
  [1139165181858816] = "Esse também pode ser o motivo pelo qual você não estava no local, mas cometeu suicídio em casa.",
  [1139165182476288] = "Você não pode imaginar que um menino tão tímido ficou firme diante de todos no pior e mais desesperado momento.",
  [1139165182836480] = "Dessa forma, não precisamos nos preocupar com ninguém nos perturbando.",
  [1139165182836224] = "Eu também!",
  [1139165182835968] = "Eu também irei!",
  [1139165182835712] = "Então continuarei a salvar pessoas e a trazer todos para a casa segura primeiro.",
  [1139165182835456] = "Hum! Eu acredito em você!",
  [1139165182835200] = "Acredite em nós, teremos sucesso.",
  [1139165182834944] = "Assim que destruirmos aquele Artefato Selado, poderemos retornar a Tingen.",
  [1139165182834688] = "Rozanne, o Capitão Frye e eu vamos rastrear um Artefato Selado.",
  [1139165182834432] = "Esta é uma pista sobre o “Espelho Mágico do Desespero”.",
  [1139165182834176] = "Deixe isso conosco.",
  [1139165182833920] = "Ok, deixe comigo.",
  [1139165182833664] = "Devo rastrear a “Coroa do Conhecimento” para evitar que ela continue a ser animada. Gostaria de confiar a você e a Frye a tarefa de destruir o \"Espelho Mágico do Desespero\".",
  [1139165182833408] = "\"Espelho Mágico do Desespero\" corresponde à Sequência 4 Bruxa do Desespero Característica de Beyonder , que é mais fácil de resolver do que a Sequência 1 \"Coroa do Conhecimento\".",
  [1139165182833152] = "\"Magic Mirror of Despair\" é a única entrada para Tingen in the Mirror.",
  [1139165182832896] = "Rebecca está investigando o pequeno espelho de cobre e obteve pistas sobre outro Artefato Selado, o “Espelho Mágico do Desespero”. Tingen no Espelho é construído pela \"Coroa do Conhecimento\" e não é um verdadeiro mundo espelhado.",
  [1139165182832640] = "Louvado seja a Deusa.",
  [1139165182832384] = "<P_Heart> (Pressionando a mão no peito) </> Louvado seja a Deusa.",
  [1139165182832128] = "Para evitar sermos vigiados, precisamos discutir o assunto sob a autoridade do “Segredo”.",
  [1139165182831872] = "A coroa na mão do mordomo é um Artefato Selado de Grau 0, que mostrou sinais de ativação devido à corrupção da Deusa Mãe da Depravação.",
  [1139165182831616] = "Pequena Rozanne, não se preocupe, não morreremos.",
  [1139165182831360] = "<P_Heart> (Preocupado) </> Ainda existe uma chance de fracasso? Você estará em perigo?",
  [1139165182831104] = "Mas com a ajuda dela, a probabilidade de sucesso será muito maior.",
  [1139165182830848] = "<P_Heart> (Sorrindo) </> Já que ela não quer ser exposta, vamos fingir que não sabemos.",
  [1139165182830592] = "<P_Heart> (Ponderando) </> Esta crise também envolve o conhecimento e o Imperador Roselle, então acho que adivinhei a identidade daquela senhora.",
  [1139165182830336] = "Ela não te disse o nome dela? Parece que ela está nos ajudando intencionalmente, mas... ela não quer revelar sua identidade?",
  [1139165182830080] = "Você também conheceu aquela senhora!",
  [1139165182829824] = "Lá, conheci uma senhora vestida de pirata, que me contou como entrar em Tingen no Espelho, e também me contou que Rozanne estava na Casa Segura.",
  [1139165182829568] = "O Vigias Noturnos rastreou os panfletos promovendo o Imperador Roselle e descobriu uma entrada de corrupção na Praça Central.",
  [1139165182829312] = "Esta crise envolve não apenas “Nova Vida”, mas também “Conhecimento”. Investiguei alguns fãs fanáticos do Imperador Roselle e descobri que existem organizações que usam escolas noturnas e aulas de alfabetização para espalhar conhecimento corrompido.",
  [1139165182829056] = "Capitão Frye, e você? Você também está investigando May Manor?",
  [1139165182828800] = "Atualmente, de acordo com as pistas, May Manor parece estar preparando um Ritual de Sacrifício direcionado à “Deusa Mãe da Depravação”.",
  [1139165182828544] = "No processo de investigação do “May Manor”, ​​descobri que a dona do feudo, a Viscondessa, estava com problemas. Localizei a Viscondessa e seu mordomo e vim para cá.",
  [1139165182828288] = "Sr. Leonard, por que está aqui?",
  [1139165182828032] = "Para estar seguro, você ainda deve beber um pouco de Poção da Tranquilidade.",
  [1139165182827776] = "Você acordou sem beber a poção; você tem uma boa constituição.",
  [1139165182827520] = "Acordado.",
  [1139165182827264] = "Os sortudos renascerão—",
  [1139165182827008] = "Quando o carmesim descer, todos aqui se tornarão alimento para a vida.",
  [1139165182826752] = "Filhos, não existe segurança eterna.",
  [1139165182826496] = "Ouvi dizer que você chama esse lugar de \"Casa Segura\"?",
  [1139165182826240] = "Vida nova de novo... <P_Heart> (Voz baixa) </> Rozanne, você vai primeiro para a Casa Segura, eu vou segurá-lo.",
  [1139165182825984] = "Ela é a Viscondessa, uma verdadeira nobre e a mensageira que trouxe nova vida a Tingen.",
  [1139165182825728] = "<P_Heart> (Elegante) </> Fico feliz que você se lembre da contribuição que a Senhora deu para isso.",
  [1139165182825472] = "Eu o conheço! Ele é o mordomo daquele patrocinador!",
  [1139165182825216] = "Já orientei algumas pessoas até a Casa Segura, não deve haver problema.",
  [1139165182824960] = "Vá para o Grande Teatro Tingen, há um espelho lá, e atrás do espelho está a Casa Segura.",
  [1139165182824704] = "Não é seguro aqui.",
  [1139165182824448] = "Conheci uma senhora vestida de pirata; foi ela quem me contou...",
  [1139165182824192] = "Casa Segura? Você acabou de dizer a Danny para ir ao Grande Teatro Tingen, isso é uma Casa Segura? Como você sabia?",
  [1139165182823936] = "Só posso orientar todos a escaparem primeiro para a Casa Segura.",
  [1139165182823680] = "Eu tentei o meu melhor para evitar os monstros... Não, na verdade eles são cidadãos desaparecidos... mas há cada vez mais monstros...",
  [1139165182823424] = "Eu já estive lá. Não há ninguém na delegacia...",
  [1139165182823168] = "Podemos ir procurar a polícia!",
  [1139165182822912] = "Podemos ir até a Estação Ferroviária e pegar um trem para sair daqui.",
  [1139165182822656] = "Mas... com o passar do tempo, as pessoas ao nosso redor começaram a agir de forma estranha.",
  [1139165182822400] = "É graças a {{PlayerName}} que chegou a tempo! No início, não havia tantos monstros; nos reunimos para encontrar uma maneira de escapar.",
  [1139165182822144] = "<P_Heart> (Aliviado) </> Graças a Deus você está bem, Rozanne.",
  [1139165182821888] = "<P_Heart> (Envergonhado) </> Esta é a tradição da nossa Blackthorn Security Company, proteger Tingen é nosso dever!",
  [1139165182821632] = "Você nos protegeu.",
  [1139165182821376] = "Obrigado à senhorita Rozanne.",
  [1139165182820096] = "Não, Beyonders são perigosos, você deveria fazer trabalho administrativo.",
  [1139165182968576] = "{{Sr.|Sra.}}, sua carteira!",
  [1139165182837504] = "No entanto, tenho apenas Sequência 9 anos agora e posso não ser capaz de recebê-lo... Talvez se eu me ligar àquele espaço misterioso acima da névoa cinzenta...",
  [1139165182821120] = "Eu sou... também um Guardião?",
  [1139165182819840] = "<P_Heart> (Engasgando com soluços) </> O Mundo Extraordinário é perigoso... Pai, não seja um Vigia Noturno ... Velho Neil, não acredite... Capitão Dunn, não vá...",
  [1139165182819584] = "<P_Heart> (Sonolento) </> Vigias Noturnos ... tenho que lidar com acontecimentos Extraordinários... o Mundo Extraordinário é perigoso...",
  [1139165182819328] = "{{PlayerName}} ! Como você entrou? Como esperado de... um Vigia Noturno ...",
  [1139165182245632] = "Um trabalho decente requer roupas decentes. É hora de comprar um terno formal adequado.",
  [1139165182819072] = "Rozanne, você está bem?",
  [1139165181920000] = "Hehe, um pouco de saliva, escovei os dentes.",
  [1139165181842176] = "Acordei com fome de novo... o pão usado no Ritual de Virada da Fortuna. é ideal para comer.",
  [1139165182708480] = "Hmm, você invadiu um ritual maligno envolvendo sacrifício e oração a um deus maligno.",
  [1139165182586624] = "Isso é... uma lâmpada a gás?",
  [1139165182444288] = "Você está pronto desta vez?",
  [1139165182313216] = "<P_Heart> (Ótimo! Não controlado.) </>",
  [1139165182296832] = "Não pense demais, Alice. Avisarei assim que houver novidades.",
  [1139165182818816] = "Mas Rozanne ainda deve estar na fábrica! Ela disse que traria todo mundo do avesso.",
  [1139165182818560] = "Já encontramos perigo na fábrica antes e ela nos deixou escapar. Mas não muito depois de sair, encontrei um monstro...",
  [1139165182818304] = "<P_Heart> (Surpreso) </> Você a conhece?",
  [1139165182818048] = "Você quer dizer Rozanne?",
  [1139165182817792] = "Ela tem cabelo curto, quase tão alto quanto você.",
  [1139165182817536] = "De nada, é o que devo fazer. Quero te perguntar, você viu uma garota com um vestido verde?",
  [1139165182817280] = "Obrigado, muito obrigado!",
  [1139165182817024] = "<P_Heart> (Olhos claros) </> Desenhos! Sim, meus desenhos não estão perdidos!",
  [1139165182816768] = "<P_Heart> (Levantando levemente a cabeça) </> Padaria... Sim, eu faço meus desenhos atrás do balcão depois de entregar o pão!",
  [1139165182816512] = "Esses desenhos estão muito bem desenhados e ainda têm aroma de pão.",
  [1139165182816256] = "Jenny, este é o seu desenho? Encontrei-o na padaria da Sra. Slin.",
  [1139165182816000] = "<P_Heart> (Parece que ele também está temporariamente incapaz de acordar; pode haver um quebra-cabeça de conhecimento por aqui.) </>",
  [1139165182815744] = "<P_Heart> (Alegre) </> Eu sei, o trabalho é cansativo. Mas nunca ficarei devendo o salário de ninguém. Enquanto trabalharmos arduamente juntos, construiremos um futuro melhor.",
  [1139165182815488] = "<P_Heart> (Olhando para você com entusiasmo) </> Jovem, você também está aqui para contribuir com a construção da nova era?!",
  [1139165182815232] = "Senhor, você ainda está consciente? Você se lembra do que aconteceu aqui?",
  [1139165182814976] = "<P_Heart> (sonolento) </> Futuro...",
  [1139165182814720] = "<P_Heart> (Atordoado) </> Era...",
  [1139165182814464] = "Não estamos apenas fazendo um trabalho; estamos criando uma era!",
  [1139165182814208] = "Mas também quero que todos vejam que a nossa fábrica produz o aço mais resistente, que é a base da indústria e o futuro do reino!",
  [1139165182813952] = "O ar da oficina está misturado com pó de carvão e é muito desconfortável respirar para os pulmões. Eu vejo tudo isso.",
  [1139165182813696] = "Trabalhadores, sei que todos estão muito cansados. As máquinas rugiram o dia todo e seus braços já estão doloridos e dormentes.",
  [1139165182813440] = "É complicado explicar. O tempo está apertado e ainda precisamos salvar outros, siga-me primeiro.",
  [1139165182813184] = "Você foi afetado por Beyonder poderes e perdeu sua sanidade.",
  [1139165182812928] = "Eu... por que estou aqui?",
  [1139165182812672] = "É o Imperador Roselle nos guiando!",
  [1139165182812416] = "Não, isso não está certo. Estes são personagens do diário do Imperador Roselle.",
  [1139165182812160] = "<P_Heart> (Lendo com atenção) </> O que são esses personagens? <P_Heart> (Pânico) </> Por que não reconheço nenhum? <P_Heart> (Rage) </> Por que sou tão estúpido! Mesmo depois de ir para a escola noturna, não reconheço um único personagem!",
  [1139165182811904] = "Não, não, devo aprender esse conhecimento primeiro. Somente com conhecimento não serei eliminado pela época.",
  [1139165182811648] = "Jack, vou te levar para sair, vou te levar para encontrar seu irmão.",
  [1139165182811392] = "Olha, conhecimento!",
  [1139165182811136] = "<P_Heart> (Ah, não, Jack ficou confuso, o nível de corrupção é mais profundo.) </>",
  [1139165182810880] = "<P_Heart> (Ficando cada vez mais animado) </> Conhecimento! Conhecimento! Uma época melhor!",
  [1139165182810368] = "Com dinheiro, posso deixar Tom ir para a escola, posso ir para a escola noturna para aprender a escrever, e Tom pode ir para a escola da igreja para aprender aritmética... Escola... uma vida melhor... uma era melhor!",
  [1139165182810112] = "Economize mais dinheiro e, com o dinheiro, posso ir para Backlund, levar Tom no trem e ver a ponte Backlund...",
  [1139165182809856] = "<P_Heart> (Murmurando para si mesmo) </> Irmão, este é o presente do meu irmão. Com a bicicleta posso entregar mais jornais, e também posso ir à taberna fazer outro trabalho depois de sair do trabalho...",
  [1139165182809600] = "Jack, você não me reconhece? Seu irmão mais novo também foi sugado para Tingen in the Mirror?",
  [1139165182809344] = "Vá embora! Ninguém está autorizado a levar minha bicicleta! Este é um presente que comprei para meu irmão mais novo!",
  [1139165182809088] = "Jack, você está bem?",
  [1139165182808832] = "<P_Heart> (Corando) </> É uma carta de confissão e um espelho de cobre. Eu, eu comprei o espelho na Cross Street, o chefe disse que era uma liquidação especial... eu não sabia que tinha relação com o caso.",
  [1139165182808576] = "O que há na sua caixa de presente?",
  [1139165182808320] = "<P_Heart> (Este homem parece ter pistas, mas não está disposto a dizer isso diretamente, deixe-me observar com Visão Espiritual ...) </>",
  [1139165182808064] = "Eu, não tenho certeza, quero confirmar primeiro com o oficial.",
  [1139165182807808] = "Sean, você viu?",
  [1139165182807552] = "Uh, policial, posso perguntar se este espelho é mercadoria roubada? Ou há algum outro motivo?",
  [1139165182807296] = "Não, raramente compramos itens decorativos tão pouco práticos.",
  [1139165182807040] = "Olá, sou um policial investigando um caso. Você já viu este pequeno espelho de cobre?",
  [1139165182806784] = "<P_Heart> (Não parece muito certo...) </>",
  [1139165182806528] = "<P_Heart> (Este lugar é exatamente igual ao lago do sonho...) </>",
  [1139165182806272] = "Lydia, você é a garota mais inteligente que já conheci. Talvez ainda este ano!",
  [1139165182806016] = "Nossa fábrica montou uma escola noturna e eu me inscrevi. No próximo ano... talvez no ano seguinte, posso procurar emprego como datilógrafa.",
  [1139165182805760] = "No entanto, em relação a esta questão, estou bastante curioso sobre a resposta de Dunn...",
  [1139165182805504] = "Somos companheiros que crescemos no time do Tingen Vigias Noturnos... Essa é uma longa história.",
  [1139165182805248] = "Se você estiver interessado, pergunte a Dunn.",
  [1139165182804992] = "Usei alguns pequenos truques para obter as respostas que queríamos. Mas por causa de alguns acordos de confidencialidade chatos e sérios, não posso contar mais nada.",
  [1139165182804736] = "Claro, espero que não seja na cena do crime da próxima vez.",
  [1139165182804480] = "Se houver uma oportunidade no futuro, podemos sentar juntos, tomar uma xícara de café e conversar.",
  [1139165182804224] = "Isso é tudo, ou... quer saber mais alguma coisa?",
  [1139165182803968] = "Eu sou o “Médium Espiritual” Daly, moro em Enmat Port e estou aqui para auxiliar no trabalho de Dunn desta vez.",
  [1139165182803712] = "Pequena, há mais alguma coisa?",
  [1139165182800384] = "É ele?! O irmão mais velho da menina do sonho?",
  [1139165182800128] = "Eh? Eu ainda queria pedir informações a ele...",
  [1139165182799872] = "Isso é bom, ainda não tenho muita habilidade para andar.",
  [1139165182799616] = "Quase, mas felizmente está tudo bem.",
  [1139165182799360] = "Desculpe, eu esbarrei em você?",
  [1139165182799104] = "Tudo bem! Senhorita Justiça deveria me convidar para um café.",
  [1139165182798592] = "Um viajante vagando pelas estrelas, um servo do Rei do Amarelo e do Preto, um mago registrando o mundo.",
  [1139165182798336] = "Venha orar comigo, só assim você poderá obter permissão...",
  [1139165182798080] = "A senhorita \"Justiça\" disse que você pode precisar de ajuda, o preço é uma xícara de café.",
  [1139165182797824] = "Meu nome é Fors, você também pode me chamar pelo meu codinome – “Mágico”.",
  [1139165182797568] = "Olá, posso perguntar quem você é...",
  [1139165182797312] = "Se você ficar parado como um peixe salgado, a estela não será ativada automaticamente.",
  [1139165182797056] = "Esta é a Estela de Viagem? Como faço para ativá-lo?",
  [1139165182796800] = "Eu vou voltar agora. A recepção não pode ficar sem vigilância por muito tempo.",
  [1139165182796544] = "Desça as escadas, <P_Yellow> siga em frente </> até o final e você chegará ao Portão Chanis. A interseção no meio <P_Yellow> vire à esquerda </> leva à Catedral de Santa Selena e à Sala de Alquimia, <P_Yellow> à direita </> fica a sala de armas, materiais e arquivos, não siga o caminho errado.",
  [1139165182796288] = "<P_Heart> (Melhor encontrar o Sr. Dunn primeiro.) </>",
  [1139165182795776] = "Que a Deusa proteja sua alma e lhe dê paz... Você desenha muito bem.",
  [1139165182795520] = "A vítima de um caso de desmembramento. Estou tentando restaurar sua aparência completa.",
  [519041160619520] = "Precisa de um adivinhação?",
  [1139165182795264] = "O que você está desenhando? <P_Heart> (Vigias Noturnos também precisa saber desenhar?) </>",
  [1139165182795008] = "Alguém está dormindo na sala de serviço; ela acabou de terminar o turno da noite e precisa descansar. Está tranquilo aqui.",
  [1139165182794752] = "Desenho? Este é o seu trabalho? Em um lugar tão escuro?",
  [1139165182793984] = "Procurando pelo capitão? O capitão está na sala de serviço próximo ao Portão Chanis, continue andando.",
  [1139165182793728] = "Sou Klein Moretti, estou aqui para encontrar o Sr. Dunn para começar meu trabalho.",
  [1139165182792960] = "Haverá muitas oportunidades de nos conhecermos mais tarde. O capitão deve estar esperando por você, vá em frente.",
  [1139165182792704] = "Eu sou Cohen, ela é Xiga, bem-vindo para se juntar a nós.",
  [1139165182792448] = "Desde que me tornei membro formal, Rozanne sempre reclamou que há muito pouco pessoal administrativo e muito trabalho. Ela deveria estar muito feliz agora.",
  [1139165182792192] = "Pessoal administrativo? Isso é ótimo.",
  [1139165182791936] = "Eu sou Klein. Vim hoje para iniciar meu trabalho como funcionário administrativo. Senhorita Rozanne me disse para descer para encontrar o Sr. Dunn.",
  [519041160984832] = "Hum...",
  [1139165182791680] = "Você é... nosso recém-chegado?",
  [1139165182790656] = "Hmph, quando você realmente entrar em contato com esse tipo de trabalho, saberá como é difícil!",
  [1139165182786048] = "Tudo bem, esta jornada histórica acabou. Volte e descanse bem. Estou ansioso para ver você na próxima vez.",
  [1139165182785792] = "Eu ouvirei.",
  [1139165182785536] = "Então reze para mim novamente, pedindo permissão para entrar na neblina da história.",
  [1139165182785280] = "Na hora e no lugar certos, a moeda de ouro irá guiá-lo. “Observe” a história que deixei para trás e deixe que as lacunas da história te aceitem mais.",
  [519041161272576] = "EU...",
  [1139165182785024] = "Parece... um pouco melhor. O que mais eu preciso fazer?",
  [1139165182784768] = "Parabéns, você reviveu minha história com sucesso uma vez. Como você está se sentindo?",
  [1139165182784000] = "Recite comigo, a oração é: O Louco que não pertence a esta época...",
  [1139165182783744] = "Sim, tire aquela moeda de ouro e reze para mim.",
  [519041161429760] = "E então?",
  [1139165182783488] = "Reviva... história?",
  [1139165182783232] = "Reviver meu passado irá ajudá-lo a combater a corrupção e estabilizar sua memória e humanidade.",
  [1139165182782976] = "{{PlayerName}}, posso abrir meu histórico para você.",
  [1139165182782720] = "Essa flutuação da aura me lembrou, talvez...",
  [1139165182782464] = "Então o que devo fazer?",
  [1139165182782208] = "Se você encontrar corrupção acidental novamente, poderá ser completamente controlado por Sua vontade e cair na loucura eterna.",
  [1139165182781952] = "Como está sua condição? Sua memória foi corrompida e seu espírito e corpo podem ficar instáveis ​​às vezes.",
  [1139165182781696] = "Tudo bem também.",
  [1139165182781440] = "Senti algumas flutuações em auras familiares, então vim dar uma olhada. Isso está interferindo demais no destino...",
  [1139165182781184] = "Senhor \"Tolo\"! Como você está aqui?",
  [1139165182780928] = "Lembrar",
  [1143492898212608] = "Compre materiais.",
  [1139165182780416] = "Poderia ser isso... Isso conta como o \"modelo mais recente\"?",
  [1139165182780160] = "Tudo bem, obrigado, senhorita Rozanne.",
  [1139165182779904] = "Leonard ainda precisa se preparar um pouco, vestir primeiro suas roupas novas, dar um passeio em Tingen e experimentar sua nova bicicleta!",
  [1139165182779648] = "É um pouco diferente, encomendamos especificamente o modelo mais recente para você, está estacionado na entrada da empresa.",
  [1139165182779392] = "Eu entendo, é o tipo de bicicleta que o carteiro anda?",
  [1139165182779136] = "Desde que as bicicletas se popularizaram nos últimos dois anos, novos colaboradores podem receber uma para facilitar suas missões.",
  [1139165182778880] = "Esta é uma chave de bicicleta. O Imperador Roselle disse, é preciso seguir em frente com as tendências da época!",
  [1139165182778624] = "Tantas coisas! Este é um conjunto de roupas novas e também uma... chave?",
  [1139165182778368] = "Uma foto danificada, mas pendurada em posição de destaque; deve ser muito precioso...",
  [1139165182778112] = "O canto superior direito da foto está queimado, e a parte superior do corpo daquele senhor também está queimada.",
  [1139165182777856] = "Uma foto de grande grupo. Esta é a Srta. Rozanne... e aquele é o Sr. Leonard?",
  [1139165182777600] = "Descanse um pouco, olhe ao redor ou dê um passeio novamente em Tingen.",
  [1139165182777344] = "Há outro assunto muito importante, primeiro preciso me preparar um pouco.",
  [1139165182777088] = "Sim, todos me ajudaram muito e devo dar o meu melhor para cumprir as minhas responsabilidades.",
  [1139165182776832] = "Mas ingressar na Blackthorn significa que você também deve assumir responsabilidades conosco.",
  [1139165182776576] = "Tingen ainda é muito estranho para você, Blackthorn é seu porto seguro temporário.",
  [1139165182776320] = "Bem-vindo, {{PlayerName}}, você se tornou oficialmente um de nós.",
  [1139165182776064] = "Eu decidi, estou disposto a ingressar na Blackthorn Security Company.",
  [1139165182775808] = "Que tal? Se não houver problema, assine o contrato.",
  [1139165182775552] = "Isto não é um disfarce; somos uma organização oficial e também uma verdadeira polícia.",
  [475333694326784] = "Nesses romances de aventura, isso se chama encontro dos dois protagonistas, e as rodas da história começam a andar.",
  [1139165182775296] = "Beyonder os poderes devem ser mantidos em segredo das pessoas comuns, e uma identidade policial torna mais conveniente a investigação dos casos.",
  [1139165182775040] = "O verdadeiro dever de Blackthorn é lidar com eventos extraordinários em Tingen.",
  [1139165182774784] = "Um contrato de trabalho e isto é... um distintivo policial?",
  [1139165182774528] = "Inteligente. Na verdade, este é o esquadrão Tingen Vigias Noturnos da Igreja da Deusa da Noite Eterna.",
  [1139165182774272] = "...Parece que entendo, a Blackthorn Security Company é um disfarce?",
  [1139165182774016] = "E se o poder por trás de nós for a Igreja da Deusa da Noite Eterna?",
  [1139165182773760] = "E se a segurança que protegemos for a segurança de toda a cidade de Tingen?",
  [1139165182773504] = "Eu entendo, mas a Srta. Justiça disse que você me orientaria a ingressar em uma organização Beyonder?",
  [1139165182773248] = "Você deve se adaptar em Tingen por um tempo, o que facilitará a proteção de sua segurança.",
  [1139165182772992] = "O Sr. \"Tolo\" nos orienta para permitir que você se junte primeiro à Blackthorn Security Company.",
  [1139165182772736] = "Você tem a corrupção selada de um deus maligno em você, e Tingen também esteve cheio de crises recentemente.",
  [1139165182772480] = "Eu costumava ser e ainda sou.",
  [1139165182772224] = "Empresa de segurança... Você trabalhava na segurança?",
  [1139165182771968] = "Estamos aqui, Blackthorn Security Company.",
  [1139165182771712] = "Sim, era onde eu trabalhava.",
  [1139165182771456] = "Indo para Blackthorn?",
  [1139165182771200] = "Entre no carro.",
  [1139165182770944] = "Visão Espiritual ? Pode ver coisas escondidas? Deixe-me tentar...",
  [1139165182770688] = "Visão Espiritual permitirá que você veja algumas coisas ocultas e até um tanto estranhas.",
  [1139165182770432] = "A propósito, depois que seu espiritualidade for aprimorado, você pode tentar ativar Visão Espiritual .",
  [1139165182770176] = "Eu entendo. Obrigado ao seu amigo e elogie o Sr.",
  [1139165182769920] = "Na revelação do Sr. Louco, terá um uso ainda mais importante no futuro.",
  [1139165182769664] = "A moeda de ouro pode ajudá-lo a suprimir a corrupção enquanto melhora seu espiritualidade .",
  [1139165182769408] = "Agora ele me confiou para seguir a orientação do destino e passar a moeda de ouro para você.",
  [1139165182769152] = "Ele tem uma moeda de ouro especial que o Sr. Louco lhe deu há dois anos.",
  [1139165182768896] = "A propósito, um amigo recentemente vislumbrou seu Unicidade do destino do futuro.",
  [1139165182768640] = "Meus colegas e eu já começamos a investigar e lidar com isso, mas ainda há poucas pistas.",
  [1139165182768384] = "Corrompendo a cidade inteira? Isso é tão sério... O que devemos fazer?",
  [1139165182768128] = "Você já tem a corrupção Dele sobre você, então é fácil se envolver em eventos relacionados.",
  [1139165182767872] = "Esse deus maligno não está apenas corrompendo você, mas também tentando corromper todo o Tingen.",
  [1139165182767616] = "Foi um pesadelo, mas este é apenas um dos perigos causados ​​pela corrupção do deus maligno em Tingen.",
  [1139165182767360] = "Obrigado, você é o Sr. Star? Acho que tive um pesadelo de novo agora há pouco?",
  [1139165182767104] = "Deixar você me encontrar sozinho em Blackthorn ainda é um pouco arriscado.",
  [1139165182766848] = "Blackthorn... Empresa de segurança? Deixe-me encontrar o caminho primeiro.",
  [1139165182766592] = "Ele irá guiá-lo para ingressar na <P_Yellow> Blackthorn Security Company </> .",
  [1139165182766336] = "Pronto, você deveria chamá-lo de Sr. Leonard.",
  [1139165182766080] = "Em seguida, vá para 36 Zoutland Street para encontrar o Sr. Star.",
  [1139165182765824] = "Muito bom! Parece que você ativou com sucesso a Estela de Viagem.",
  [1139165182765568] = "Qual será a próxima orientação da senhorita Justiça?",
  [1139165182765312] = "Bem, eles foram para longe tão rapidamente...",
  [1139165182765056] = "A pessoa já saiu?",
  [1139165182764800] = "Sucesso! Obrigado, posso perguntar...",
  [1139165182764544] = "Este é o jornal de hoje... A data é <P_Yellow> 28 de junho de 1354 </> .",
  [1139165182764288] = "O subsídio de transporte e alimentação é de apenas 3 soli? Então os 20.000... dinheiros dados pela Srta. Justiça?",
  [1139165182764032] = "Deusa da Meia Noite... Parece que há mais de uma divindade neste mundo.",
  [1139165182763776] = "Quem é Roselle de novo? Há mais de cem anos... a Revolução Industrial?",
  [1139165182763520] = "Que caso bizarro, Tingen está realmente envolta em crise...",
  [1139165182763264] = "Leia o jornal",
  [1139165182763008] = "Obrigado pelo seu patrocínio e tenha um bom dia.",
  [1139165182762752] = "Tudo bem então, cavalheiro, comprarei o jornal de hoje.",
  [1139165182762496] = "Vendendo jornais há um ano e conheço todos os grandes e pequenos eventos em Tingen!",
  [1139165182762240] = "Garotinho? {{Sr.| Sra.}}, esta forma de tratamento é depreciativa para mim.",
  [1139165182761984] = "Olá, garotinho... Vou comprar o jornal de hoje.",
  [1139165182761728] = "Talvez eu possa saber mais sobre Tingen através do jornal, comprar um exemplar e ver.",
  [1139165182761472] = "Vá embora! Os folhetos da campanha são suficientes para toda a nossa família limpar o traseiro.",
  [1139165182761216] = "O jornal Tingen Honest, as últimas notícias!",
  [1139165182760960] = "De nada. Espero que você esteja de bom humor e que tudo corra bem.",
  [1139165182760704] = "Obrigado pelo presente da Srta. Justiça, e obrigado também, Susie.",
  [1139165182760448] = "É pesado. Parece uma grande soma de “mesada”.",
  [1139165182760192] = "Pegue. São apenas 20.000 soli. O dinheiro está na minha bolsa; ajude-se.",
  [1139165182759936] = "Existe tal habilidade? Não admira que pareça que ninguém nos notou.",
  [1139165182759680] = "Esta é a habilidade Extraordinária do Espectador Caminho —Invisibilidade Psicológica.",
  [1139165182759424] = "Ah, não se preocupe, ninguém vai notar você falando comigo.",
  [1139165182758912] = "Bem... suponho que realmente não tenho muito dinheiro.",
  [1139165182758656] = "Então ela me mandou dar para você. Afinal, sou apenas um cachorro.",
  [1139165182758400] = "Ela quer patrocinar algum dinheiro para você, mas tem medo que você fique com vergonha de aceitá-lo.",
  [1139165182758144] = "Meu nome é Susie, sou assistente da Srta. Justiça.",
  [1139165182757888] = "Isso mesmo, esta é a natureza extraordinária do Mundo Extraordinário.",
  [1139165182757632] = "É você quem está falando? Um cachorro... falante?!",
  [1139165182757376] = "Eu realmente me lembro... Primeiro encontre o Central Plaza, depois procure o Travel Obelisk.",
  [1139165182757120] = "Depois de ativar a Estela do Viajante, será muito mais conveniente viajar pelo mundo.",
  [1139165182756864] = "O Obelisco de Viagem fica próximo à Praça Central, há uma enorme escultura na praça.",
  [1139165182756608] = "Procure o <P_Yellow> Travel Obelisk </> próximo, que é uma obra-prima da Miss Magician.",
  [1139165182756352] = "Exatamente, mas essas são apenas duas pequenas dicas. A chuva parou, prepare-se e saia para experimentar.",
  [1139165182756096] = "Parece incrível... Isso também faz parte da psicoterapia?",
  [1139165182755840] = "Você só precisa parar, pensar com cuidado e será capaz de se lembrar de minhas orientações.",
  [1139165182755584] = "Eu já lhe disse o que fazer a seguir em seu subconsciente.",
  [1139165182755328] = "Eu entendo. Sr. Star... onde devo ir para encontrá-lo?",
  [1139165182755072] = "<P_Yellow> Sr. Star </> irá orientá-lo para se juntar a uma das organizações para tornar mais fácil protegê-lo.",
  [1139165182754816] = "Mas não se preocupe, temos uma organização Beyonder confiável que está protegendo Tingen.",
  [1139165182754560] = "Não, uma crise está se formando e Tingen enfrenta o perigo de destruição.",
  [963379418113536] = "Eu transmigrei?",
  [1139165182754304] = "As pessoas vivem em grandes disparidades, mas a cidade parece bastante calma.",
  [1139165182754048] = "Aquele que me ajudou no meu sonho foi na verdade um deus... Louvado seja o Sr. Louco.",
  [1139165182753792] = "O Rei do Amarelo e do Preto que exerce boa sorte.",
  [1139165182753536] = "O misterioso governante acima da névoa cinzenta.",
  [1139165182753280] = "O Louco que não pertence a esta época.",
  [1139165182753024] = "Quando você encontrar perigo, você pode orar a ele assim para pedir proteção—",
  [1139165182752768] = "Ele espera que quando chover todos possam ter um lugar para se abrigar.",
  [1139165182752512] = "Ele também já foi uma pessoa comum, com sua própria família e amigos.",
  [1139165182752256] = "O Sr. \"Tolo\" é um deus benevolente e Tingen é seu ponto de partida.",
  [1139165182752000] = "Você acabou de dizer... O Sr. Louco também morava em Tingen?",
  [1139165182738176] = "Mas também tenha cuidado, não se deixe cair em perigo.",
  [1139165182737920] = "Hmm, vou aprender e me adaptar a este lugar o mais rápido possível para poder ajudar.",
  [1139165182737664] = "...A integração acabou e nós dois velhos amigos também devemos nos atualizar.",
  [1139165182737408] = "Já se passaram quase cinco anos, Leonard. Todos nós mudamos um pouco.",
  [1139165182737152] = "Frye, você não parece tão silencioso como costumava ser.",
  [1139165182736896] = "Na verdade, assim será mais familiar e seguro ao participar posteriormente nas investigações de casos.",
  [1139165182736640] = "Pretendo deixar {{ele | ela}} dar um passeio em Tingen novamente para aprender mais sobre este lugar.",
  [1139165182736384] = "Não se apresse, {{ele|ela}} acabou de beber a poção Sequência 9 e ainda precisa se adaptar.",
  [1139165182736128] = "Blackthorn está com falta de pessoal recentemente, este novo funcionário...",
  [1139165182735872] = "Eu entendo. Depois de dar as boas-vindas ao recém-chegado, irei participar da investigação.",
  [1139165182735616] = "Uma crise está se formando em Tingen e esse sentimento é muito ruim.",
  [1139165182735360] = "Você se senta também, não seja muito formal.",
  [1139165182735104] = "Está tudo bem, o Sr. Leonard e a Srta. Rozanne têm me ajudado.",
  [1139165182734848] = "Bem-vindo. Eu tinha um assunto urgente para investigar e não tive tempo de recebê-lo no trabalho.",
  [1143563228319488] = "Obrigado.",
  [1139165182734080] = "Este é o Capitão de Blackthorn...",
  [1139165182733824] = "Frye deveria estar de volta. Como novo funcionário, você deveria consultar seu capitão.",
  [1139165182733568] = "Obrigado pela sua orientação, Sr. Leonard. Estou bem agora.",
  [1139165182733312] = "No entanto, devo parabenizá-lo por se tornar um verdadeiro Beyonder .",
  [1139165182733056] = "Parece que ainda é necessária alguma psicoterapia, direi à senhorita Justiça.",
  [1139165182732800] = "E outra pessoa apareceu em minha mente, uma pessoa poderosa e estranha...",
  [1139165182732544] = "Talvez esteja afetado pela corrupção, não consigo me concentrar na meditação.",
  [1139165182732288] = "Como é? Parecia muito perigoso agora?",
  [1139165182732032] = "Existem, mas comparado a alguns anos atrás, é muito mais seguro.",
  [1139165182731776] = "Basta beber assim? Existem riscos?",
  [1139165182731520] = "É uma poção mágica que pode mudar a essência da vida. Beba.",
  [1139165182731264] = "A poção não é um café para refrescar a mente, nem uma bela coleção de poemas.",
  [1139165182731008] = "Feito? Essa cor e esse cheiro... não parece muito fácil de engolir.",
  [1139165182730496] = "Mas desta vez, a fórmula da sua poção é fornecida pela Igreja do Louco, e os ingredientes são patrocinados pela Senhorita Justiça.",
  [1139165182729472] = "Primeiro, prepare a poção Sequência 9 de acordo com os ingredientes e dosagens da fórmula.",
  [1139165182729216] = "Mas desta vez, a fórmula da sua poção é fornecida pela Blackthorn, e os ingredientes são patrocinados pela Miss Justiça.",
  [1139165182728960] = "De modo geral, as fórmulas e ingredientes das poções, principalmente os ingredientes principais, são muito caros.",
  [1139165182728704] = "Correto. Você já escolheu este Caminho sob a orientação do destino.",
  [1139165182728448] = "Esta é a fórmula da poção Sequência 9?",
  [1139165182728192] = "A seguir, seguirei a revelação do Sr. Louco e orientarei você a beber a poção Sequência 9.",
  [1139165182727936] = "Você deve se tornar um verdadeiro Beyonder e dominar suas próprias habilidades para tornar o Enxerto mais estável.",
  [1139165182727680] = "Quando isso acontecer, seus poderes Beyonder não poderão ser usados ​​normalmente e de forma estável, e você enfrentará sério perigo.",
  [1139165182727424] = "É possível. Agora que você chegou à realidade, juntamente com a influência da corrupção do deus maligno, é provável que o poder do Enxerto sofra interferência.",
  [1139165182727168] = "Mas encontrei duas anomalias... será porque o poder enxertado é instável?",
  [1139165182726912] = "Mas o Sr. Louco disse no sonho que meu poder veio de uma de suas tentativas – enxerto?",
  [1139165182726656] = "Não se preocupe, há Vigias Noturnos e funcionários da igreja vigiando atrás da porta. Vamos, siga-me até a <P_Yellow> Sala de Alquimia </>.",
  [1139165182726400] = "Eu entendo, não admira que esta porta parecesse tão perigosa agora...",
  [1139165182726144] = "Ao realizar missões no futuro, você poderá usar Artefatos Selados para ajudá-lo, mas tome cuidado com seus efeitos negativos.",
  [1139165182725888] = "O grau 0 é o nível de perigo mais alto; suas habilidades e efeitos negativos podem até destruir uma cidade.",
  [1139165182725632] = "Eles são classificados em diferentes níveis de perigo e precisam ser rigorosamente guardados ou selados.",
  [1139165182725376] = "Simplificando, um Artefato Selado é um item que possui várias habilidades extraordinárias, mas também traz efeitos negativos.",
  [1139165182725120] = "Isso não faz parte do 'treinamento de integração'. Não importa... deixe-me apresentá-lo brevemente.",
  [1139165182724864] = "Artefato Selado... o que isso significa?",
  [1139165182721792] = "<P_Heart> (Outro policial que veio investigar com o Sr. Dunn? Ele realmente é um Vigia Noturno também...) </>",
  [1139165182721536] = "Sem problemas. A psicoterapia levará algum tempo. Notificarei a todos antes de acordar {{ele|ela}}.",
  [1139165182721280] = "Finalmente prestes a terminar. Há uma última etapa. Senhorita Justiça, devo enviar {{ele | ela}} para Tingen agora?",
  [1139165182721024] = "Precisamos primeiro realizar alguma psicoterapia para estabilizar o espírito de {{ele|ela}}. Obrigado a todos pelo seu trabalho duro, deixe o resto comigo.",
  [1139165182720768] = "A corrupção é inicialmente selada, mas a vontade de {{ele | ela}} foi repetidamente devastada. Deveríamos acordar {{ele | ela}} no mundo real assim?",
  [1139165182720512] = "É isso mesmo, finalmente há uma nova esperança para o apocalipse.",
  [1139165182720256] = "Já se passaram quase dois anos e finalmente é um sucesso. O milagre prometido pelo Sr. Louco finalmente foi realizado!",
  [1139165182720000] = "Isso é realmente um sonho? Devo descobrir a verdade e escapar deste pesadelo?",
  [1139165182719744] = "Tantas perguntas, mas não sei nada, apenas as revelações no pergaminho...",
  [1139165182719488] = "Ugh, minha cabeça dói. Não consigo me lembrar de nada. Onde é isso...",
  [1139165182719232] = "O que está registrado no pergaminho são algumas profecias estranhas e revelações enigmáticas?",
  [1139165182718464] = "Está tudo bem, ainda há esperança. Vigésima primeira tentativa, recomeçando!",
  [1139165182718208] = "Desta vez, o Recém-Nascido abriu o caderno e suicidou-se, torcido pelo poder da loucura.",
  [1139165182717952] = "Na vigésima vez, outro fracasso? Existem muitos acidentes!",
  [1139165182717440] = "Tela preta",
  [1139165182717184] = "Tudo bem, Senhorita Mágica... o novo sonho está prestes a começar!",
  [1139165182716928] = "O tempo está acabando. O cartão de substituição <P_Yellow></> está instalado. Vamos prosseguir com a próxima tentativa.",
  [1139165182716672] = "Devemos também seguir a vontade do Sr. Louco e confrontá-la repetidamente para ter uma chance de sucesso.",
  [1139165182716416] = "A <P_Yellow> Deusa Mãe da Depravação </> é muito poderosa, mesmo que seja apenas a corrupção residual no sonho do Recém-nascido...",
  [1139165182716160] = "Mas <P_Yellow> Recém-nascido </> também está lutando muito. Esta é a <P_Yellow> humanidade </> que o Sr. Louco valoriza, e é a chave para o sucesso.",
  [1139165182715904] = "Na décima nona vez, outro fracasso? <P_Yellow> O recém-nascido </> sofrerá os estragos da morte e sempre...",
  [1139165182712832] = "Mas você também enfrentará o símbolo da corrupção no pesadelo diretamente até derrotá-lo completamente.",
  [1139165182712576] = "Enxertando em você a habilidade do seu destino futuro – um poder suficiente para resistir à corrupção do pesadelo.",
  [1139165182712320] = "Este cartão do Tolo é um presente meu para você. Vou usá-lo para fazer uma tentativa",
  [1139165182712064] = "É isso mesmo, meus companheiros também usam cartas de Tarô como codinomes, e nossa organização se chama Clube do Tarô .",
  [1139165182711808] = "A carta do Louco... o seu título deriva desta carta do Tarô?",
  [1139165182711552] = "Meu companheiro acabou de substituir aquela perigosa carta da Lua Vermelha. Vá e pegue.",
  [1139165182711296] = "Estamos ajudando você a resistir à corrupção, acabar com o pesadelo e acordar na realidade.",
  [1139165182711040] = "Isso mesmo, você não está. Lembre-se de seus pensamentos atuais e nunca vacile.",
  [1139165182710784] = "Filho de um deus maligno? Não, não estou. Como eu poderia ser filho de um deus maligno?",
  [1139165182710528] = "Ela está tentando usar a morte infinita para devastar e corromper sua vontade, forçando você a admitir que é filho dela.",
  [1139165182710272] = "A 'Grande Mãe' que ele adorava é um deus maligno chamado 'Deusa Mãe da Depravação', e a lua vermelha é o seu símbolo.",
  [1139165182710016] = "Eles ainda estão vivos no mundo real; este é o seu ciclo interminável de pesadelos.",
  [1139165182709760] = "Obrigado novamente pela sua ajuda. Mas por que todos eles desapareceram?",
  [1139165182709504] = "O próximo passo é resistir à corrupção do deus do mal. Não se preocupe, nós iremos ajudá-lo.",
  [1139165182709248] = "Não se culpe. Ativar o ritual foi um passo necessário para escapar daqui. Você se saiu muito bem desta vez.",
  [1139165181856768] = "Você já pensou sobre isso? Você vai aderir ou recusar?",
  [1139165182474752] = "Obrigado pela sua orientação para Anna, ela tem elogiado sua magia, quase não consegue parar de falar.",
  [1139165182701824] = "<P_Heart> Eu escolho - apostar! </>",
  [1139165182701568] = "<P_Heart> Sequência poções são todas perigosas e não consigo obter mais informações. Dadas estas premissas, confio nas informações deixadas pelo antecessor transmigrador! </>",
  [1139165182701312] = "<P_Heart> Então, qual Caminho devo escolher? </>",
  [1139165182701056] = "<P_Heart> Sim, preciso escolher um extraordinário Caminho que possa me ajudar a pesquisar, compreender e dominar melhor o conhecimento oculto. </>",
  [1139165182700800] = "<P_Heart> Então, para atingir esse objetivo, a Caminho habilidade que mais preciso é... </>",
  [1139165182700544] = "<P_Heart> Hmm, somente entrando no mundo Beyonder poderei aprender a verdade sobre minha transmigração e poder voltar para casa. </>",
  [1139165182700288] = "<P_Heart> Primeiro, meu principal objetivo para me tornar um Beyonder é... </>",
  [1139165182700032] = "<P_Heart> Vamos organizar meus pensamentos. </>",
  [1139165182691328] = "Boa noite, Klein.",
  [1139165182691072] = "Haha, uma companhia cheia de babuínos de cabelos cacheados... Obrigado, Benson. Durma, durma, começarei oficialmente a trabalhar amanhã.",
  [1139165182690816] = "Hmm... se você está realmente nervoso, imagine todos como babuínos de cabelos cacheados. É claro que, na realidade, o QI de muitas pessoas não é tão alto quanto o de um babuíno de cabelos encaracolados.",
  [1139165182690560] = "Eu entendo, Klein, não coloque muita pressão sobre si mesmo.",
  [1139165182690304] = "... <P_Heart> (O caderno misterioso, tornando-se um Vigia Noturno e um Beyonder ... Não posso discutir nenhuma dessas coisas com Benson.) </>",
  [1139165182690048] = "Aconteceu um pouco... demais ultimamente e não sei como será o futuro.",
  [1139165182689792] = "O que está errado? Preocupado com o próximo trabalho?",
  [1139165182689536] = "Parece que muita coisa aconteceu recentemente...",
  [1139165182689280] = "Há um mecanismo na parte de trás, deixe-me tentar...",
  [1139165182689024] = "Olha, que boneca linda!",
  [1139165182688768] = "Parece uma tartaruga, não importa como você olhe para ela...",
  [1139165182688512] = "...Olhando de perto, é mesmo uma boneca!",
  [1139165182688256] = "É uma boneca.",
  [1139165182688000] = "Isso é uma tartaruga, certo?",
  [1139165182687744] = "Melissa ainda não entende meu humor. Mas está tudo bem.",
  [1139165182687488] = "Eu vou coletar mais alguns materiais. Isto foi para a entrevista de Klein mais cedo...",
  [1139165182687232] = "Isso é incrível. Onde está o meu?",
  [1139165182686976] = "Fiz isso usando materiais que a escola não queria e coisas que peguei na estrada. Terminei há apenas dois dias.",
  [1139165182686720] = "Você fez isso?",
  [1139165182686464] = "Acabei de comprar alguns ingredientes mais cedo...",
  [1139165182686208] = "O que devo fazer? Primeiro, deve haver carne!",
  [1139165182685952] = "Você realmente cresceu...",
  [1139165182685696] = "Deixe isso comigo. Minhas habilidades culinárias são muito boas agora, não se preocupe!",
  [1139165182685440] = "Então jantar...",
  [1139165182685184] = "E a Sra. Stiller tem pensado em você. Você pode passar por aqui para comprar algumas coisas e conversar um pouco com ela.",
  [1139165182684928] = "De repente me lembrei que para comemorar precisamos também do bolo de limão que a Melissa gosta e, claro, da cerveja de gengibre!",
  [1139165182684672] = "<P_Heart> (Espere, Benson está cozinhando?!) </>",
  [1139165182684416] = "Sinto que estou vendo meu filho crescer. Devemos comemorar esta noite! Deixe-me mostrar minhas habilidades; Aprendi alguns pratos novos nesta viagem de negócios...",
  [1139165182684160] = "Hoje foi uma situação acidental; isso não deve acontecer com frequência no futuro. Eu gosto bastante deste trabalho.",
  [1139165182683904] = "Isso é ótimo, mas você chega em casa tão tarde... Fazendo hora extra logo após começar? Esses chefes odiosos!",
  [1139165182683648] = "<P_Heart> (Três libras convertidas para a moeda antes de eu transmigrar deveriam custar cerca de duas mil mais por semana, e isso é apenas o começo...) </>",
  [1139165182683392] = "Na verdade, não compareci à entrevista. Encontrei outro emprego com antecedência e comecei hoje, com um salário semanal de três libras.",
  [1139165182683136] = "Muito mal.",
  [1139165182682880] = "Haha, não se preocupe, não estou tão perdido a ponto de não conseguir encontrar o caminho de casa. Klein, como foi sua entrevista?",
  [1139165182682624] = "Benson, bem-vindo ao lar. Por que você não disse nada com antecedência? Poderíamos ter buscado você na estação.",
  [1139165182682368] = "Espreitador de Mistérios, Colecionador de Cadáveres e Vidente.",
  [1139165182682112] = "Quais 'Sequência 9 posso escolher agora?",
  [1139165182681856] = "<P_Heart> (Mas os acontecimentos recentes parecem mais como se o perigo estivesse me perseguindo...) </>",
  [1139165182681600] = "Claro, você também pode optar por permanecer como escriturário. Afinal, você já viu o quão perigoso é o mundo extraordinário.",
  [1139165182681344] = "Você encontrou o perigo várias vezes em um curto período, mas não podemos protegê-lo o tempo todo. Você precisa da capacidade de se proteger.",
  [1139165182681088] = "É uma situação rara, mas você tem talento e agora esse mérito.",
  [1139165182680832] = "Claro, você também pode optar por continuar acumulando mérito até que seja suficiente para se tornar um 'Vigia Noturno'. A Evernight Church mantém seu Sequência completo.",
  [1139165182680576] = "Você deseja se tornar um Beyonder ? Você só pode escolher um Beyonder inicial de um Sequência incompleto.",
  [1139165182680320] = "Humanos comuns se tornam <P_Yellow> Beyonders </> ao consumir poções, com a classificação mais baixa sendo Sequência 9. Quanto <P_Yellow> menor </> o número Sequência, mais <P_Yellow> maior </> a classificação da poção.",
  [1139165182680064] = "Por meio de experimentação e exploração de longo prazo, a humanidade formou algumas cadeias sequenciais que melhoram passo a passo e crescem continuamente, também conhecidas como <P_Yellow> Beyonder Caminhos </> .",
  [1130298758700032] = "O que é?",
  [1139165182679808] = "Você tem uma chance de escolher.",
  [1139165182679552] = "Considerando como o aumento da Inspiração ajuda a encontrar o notebook, bem como os perigos potenciais ocultos...",
  [1139165182679040] = "Sinto-me muito melhor, obrigado, capitão.",
  [1139165182678784] = "Como é?",
  [1139165182678272] = "É esta a habilidade extraordinária do Capitão Dunn, trazer inimigos para dentro de um sonho? Mesmo inventando um sonho estranho como o anterior...",
  [1139165182678016] = "Por que o Capitão parece estar... dormindo?",
  [1139165182677760] = "Poderia ser o que o Capitão Dunn mencionou, a perda de controle de um Beyonder ? Mas por que ele perderia o controle de repente?",
  [1139165182677504] = "Que tipo de monstro é esse? Mas ele ainda era humano quando apareceu pela primeira vez. Parece que ele está com muita dor agora...",
  [1139165182676992] = "Eu posso fazer alguma coisa, certo? Devo movê-los para um lugar mais isolado...",
  [1139165182676736] = "O que estava escrito no jornal... foi muito cruel.",
  [1139165182676480] = "Klein, você sabe sobre Welch e Naya? Li no jornal que eles foram mortos por invasores.",
  [1139165182676224] = "<P_Heart> (Eu não esperava que o Sr. Azik estivesse aqui também. Ele também é membro do corpo docente do Departamento de História da Universidade Khoy e me ajudou muito no passado.) </>",
  [1139165182675968] = "Bom dia, Sr. Azik.",
  [1139165182675712] = "Você chegou mais rápido do que eu esperava.",
  [1139165182675456] = "Sr. Dunn!",
  [1139165182675200] = "Este é o Portão Chanis, em homenagem ao Arcebispo Chanis, o fundador do sistema Vigia Noturno.",
  [1139165182674944] = "Um, dois... há sete emblemas sagrados sombrios nesta porta...",
  [1139165182674688] = "Estou subindo agora; a recepção não pode ficar sem vigilância por muito tempo.",
  [1139165182674432] = "Siga <P_Yellow> em linha reta </> por esta estrada para chegar ao Portão Chanis. No cruzamento do meio, <P_Yellow> vire à esquerda </> para chegar à Catedral de Santa Selena e à Sala de Alquimia, e <P_Yellow> à direita </> estão as armas, materiais e biblioteca de arquivos. Não siga o caminho errado.",
  [1139165182674176] = "O Capitão está na sala de serviço próximo ao Portão Chanis.",
  [1139165182673920] = "É aquele caso de desmembramento, que a Deusa nos proteja... Klein, apresse-se e vá encontrar o Capitão Dunn; Estou preocupado que ele esteja esperando ansiosamente.",
  [620129121475584] = "Entregar Poções",
  [1139165182673664] = "Vítima do último caso, estou tentando restaurar sua aparência completa.",
  [1139165182673408] = "<P_Heart> (Vigias Noturnos também precisa saber desenhar?) </>",
  [1139165182673152] = "O que você está desenhando?",
  [1139165182672896] = "Luo Yao está dormindo lá dentro; ela acabou de terminar o turno da noite e precisa descansar.",
  [1139165182672640] = "Desenhar em um lugar tão escuro? Por que não ir para a sala de recreação? Pelo menos há luz lá.",
  [1139165182672384] = "Desenho.",
  [1139165182672128] = "Uau! Você me assustou. Frye, o que você está fazendo aqui?",
  [1139165182671616] = "Bem-vindo à equipe, Klein.",
  [1139165182671360] = "Rozanne, haverá oportunidades para nos apresentarmos mais tarde. O capitão deve estar esperando por você.",
  [1139165182671104] = "Este é Xiga, um escritor. O outro é Kenley; ele acabou de ficar noivo, sua noiva é uma senhora muito bonita e ele tem trabalhado muito para economizar dinheiro recentemente...",
  [1139165182670848] = "Klein Moretti, o novo escriturário. Finalmente, alguém para dividir o turno de trabalho comigo. Louvado seja a Deusa, não preciso ficar acordado até tarde com tanta frequência!",
  [1139165182670592] = "Olá Rozanne, quem é? Nosso recém-chegado?",
  [1139165182670336] = "E agora vou entrar no Vigias Noturnos . Isso é realmente maravilhoso...",
  [1139165182670080] = "Depois que ela faleceu, Melissa e eu ainda íamos à catedral para orar de vez em quando. Posso ser considerada uma verdadeira crente na Deusa.",
  [1139165182669824] = "Minha mãe costumava ser uma crente devota da Deusa da Noite Eterna, e a família Moretti rezava para a Deusa todos os dias, então aprendemos alguns hinos.",
  [1139165182669568] = "<P_Heart> (Cantarolando) </> Além da 'Deusa da Noite Eterna', não há outras palavras.",
  [1139165182669312] = "<P_Heart> (Refrão) </> Olharemos para aquele céu noturno e falaremos com ternura o nome dela: Deusa da Noite Eterna...",
  [1139165182669056] = "Não, não, tenho que esperar a Melissa comer junto.",
  [1139165182668800] = "Ufa, que pão sufocante, tem um gosto horrível! Acabei de comprar cordeiro e legumes ontem, por que não...",
  [1139165182668544] = "Não, se não fosse Melissa considerando minha próxima entrevista, só comeríamos carne duas vezes por semana...",
  [1139165182668288] = "Suspiro, estou destinado a viver uma vida de pão preto pela manhã, pão preto ao meio-dia e apenas carne no jantar?",
  [1139165182668032] = "Dê um passo para trás",
  [1139165182667776] = "Dê um passo à frente",
  [1139165182667520] = "Close de passos",
  [1139165182667264] = "Desça",
  [1139165182667008] = "Mova-se e vire",
  [1139165182666752] = "Vire e mova",
  [1139165182666496] = "É isso, vamos descansar primeiro. Quando eu acordar, irei... encontrar o Sr. Dunn...",
  [1139165182666240] = "Quer seja a situação financeira da minha família ou o perigo que estou enfrentando atualmente, preciso manter o Clube do Tarô e ingressar no Vigias Noturnos .",
  [1139165182665984] = "Hmm... eventos bizarros provavelmente acontecerão novamente. Eu preciso da habilidade de resistir ao perigo...",
  [1139165182665728] = "Essas habilidades maravilhosas poderiam estar relacionadas à minha transmigração?",
  [1139165182665472] = "Dunn pode manipular sonhos, e a Sra. Daly usa Mediunidade Espiritual para obter informações... Eles parecem chamar pessoas com esses tipos de habilidades Beyonders .",
  [1139165182665216] = "Existem alguns incidentes secretos extraordinários neste mundo, como o misterioso espaço de névoa cinzenta guiado pelo Ritual de Virada da Fortuna. É realmente incrível...",
  [1139165182664960] = "Embora seja como funcionário civil, há um bom salário, o que é tentador...",
  [1139165182664704] = "Para minha segurança, o Sr. Dunn me convidou para me juntar a eles e me tornar membro do Vigias Noturnos .",
  [1139165182664448] = "Como único sobrevivente e pista, fui visitado e investigado pelo Vigias Noturnos . E tudo isso parece ser por causa daquele <P_Yellow> Antigonus Notebook </> perdido.",
  [1139165182664192] = "Eu estive envolvido em um incidente bizarro onde todos os envolvidos cometeram suicídio de uma forma estranha, mas eu morri e ressuscitei... É realmente assustador.",
  [1139165182663680] = "Deixe-me pensar...",
  [1139165182663424] = "Tudo bem, Sr. Klein Moretti, desejo-lhe um bom sonho novamente esta noite.",
  [1139165182663168] = "Sem pressa. Depois de considerar isso, venha me encontrar na 36 Zoutland Street, 2º andar, '<P_Yellow> Blackthorn Security Company </> '.",
  [1139165182662912] = "Parece muito desejável...",
  [1139165182662656] = "Sim, ela é um gênio e Vigias Noturnos deve confiar incondicionalmente em seus companheiros de equipe. Em Beyonder incidentes, a confiança é uma coisa muito importante.",
  [1139165182662400] = "A Sra. Daly também é uma Vigia Noturno ? Posso dizer que você confia muito nela.",
  [1139165182662144] = "Daly disse que não há vestígios de maldições ou espíritos malignos em você, então deve ser seguro. Não se preocupe.",
  [1139165182661888] = "Obrigado, vou considerar isso com cuidado.",
  [1139165182661632] = "Vamos, vou te levar de volta primeiro.",
  [1139165182661376] = "Este é um convite tentador.",
  [1139165182661120] = "O pessoal civil geralmente recebe um salário semanal de 2 libras e 10 soli, mais um subsídio de confidencialidade e risco de 10 soli. Não é muito pior do que um professor universitário.",
  [1139165182660864] = "Então... e quanto ao seu salário e benefícios?",
  [1139165182660608] = "Este é um convite. Você é um estudante do Departamento de História e tem sorte e é inteligente o suficiente. Precisamos de talentos como você.",
  [1139165182660352] = "Isto não é algo que você precise saber, nem é algo que você possa saber, a menos que você se torne um de nós.",
  [1139165182660096] = "Mais perigoso? Por que?",
  [1139165182659840] = "O caminho Beyonder não é seguro, ou melhor, é ainda mais perigoso e incontrolável.",
  [1139165182659584] = "Depende... mas se tornar um Vigia Noturno significa que você perderá muita coisa, como a liberdade.",
  [1139165182659328] = "Junte-se ao time do Tingen Vigias Noturnos e torne-se um Beyonder ? Posso?",
  [1139165182659072] = "Ou eles podem se tornar um Beyonder diretamente. Afinal, não somos suas babás; não podemos vigiar você dia e noite.",
  [1139165182658816] = "Você pode considerar juntar-se a nós como membro da equipe civil. Se houver sinais de perigo, podemos descobri-los a tempo.",
  [1139165182658560] = "Assim como Welch e Naya.",
  [1139165182658304] = "Alguém que estava sóbrio e saudável ontem, e que confirmamos repetidamente que não tinha vestígios de espíritos malignos, poderia potencialmente se estrangular em casa depois de algum tempo.",
  [1139165182658048] = "O reino extraordinário é sempre distorcido e contrário ao bom senso; nem a sua influência nem o seu fim podem ser previstos ou controlados por nós.",
  [1139165182657792] = "Teoricamente sim, mas...",
  [1139165182657536] = "Eu entendo. Enquanto eu mantiver o segredo, não haverá outros problemas, certo?",
  [1139165182657280] = "Klein, a investigação acabou, mas você deve garantir que este caso será confidencial, até mesmo de sua família.",
  [1139165182657024] = "Claro, se você tiver tempo, poderá voltar para visitar a qualquer momento.",
  [1139165182656768] = "“Você sempre será membro do Tingen Vigias Noturnos “... Isso é o que você disse, e eu também prefiro essa identidade.",
  [1139165182656512] = "Daly, você já foi transferido para a Diocese de Backlund; você não precisa mais me chamar de capitão.",
  [1139165182656256] = "Capitão, leve-o de volta. Não há razão para suspeitar dele por enquanto.",
  [1139165182656000] = "Nenhum vestígio foi deixado para trás; deve haver a influência e interferência de Beyonder poderes por trás disso.",
  [1139165182655744] = "Vamos apenas supor isso. Só podemos procurar <P_Yellow> aquele notebook </> através de outros canais.",
  [1139165182655488] = "<P_Heart> (Eu não disse que queria ir para casa... mas parece que blefei com sucesso.) </>",
  [1139165182655232] = "Sinto que tirei uma soneca...",
  [1139165182654976] = "Fofinho, você ficava respondendo que não sabia, não tinha certeza e queria ir para casa.",
  [1139165182654720] = "Acabou? O que aconteceu agora?",
  [1139165182654464] = "Tudo bem, acabou. Volte, volte...",
  [1139165182654208] = "Não sei... não sei...",
  [1139165182653952] = "O que mais você lembra?",
  [1139165182653696] = "Eu esqueci...",
  [1139165182653440] = "Para onde foi aquele caderno?",
  [1139165182653184] = "Nada... não me lembro...",
  [1139165182652928] = "Pequena, me diga, o que aconteceu ontem à noite?",
  [1139165182652672] = "Mediunidade Espiritual, está prestes a começar de verdade.",
  [1139165182652416] = "Capitão, você faz parecer que sou um pervertido.",
  [1139165182652160] = "Não se preocupe, Daly raramente faz isso. Ela só quer te acalmar e relaxar dessa forma. Na verdade, ela prefere cadáveres.",
  [1139165182651904] = "Eu realmente não pensei muito, sério. Parece tão, tão...",
  [1139165182651648] = "Você deve ser capaz de compreender este ponto; sua mãe era uma crente devota da Deusa, e você e seu irmão também frequentaram a escola dominical da igreja.",
  [1139165182651392] = "Não fique surpreso. Ao contrário dos caras da Igreja do Senhor das Tempestades, aqui as mulheres também podem provocar outras pessoas verbalmente.",
  [1139165182651136] = "Delicadamente, devagar... na fragrância tranquila e aconchegante, você vai se apaixonar por essa sensação.",
  [1139165182650880] = "Darei a você um pouco de fragrância, gentileza e orientação suficientes para que você se abra aos poucos e mergulhe verdadeiramente nesse sentimento.",
  [1139165182650624] = "Eu não vou te tratar rudemente. Afinal, você não é um inimigo. Isso deixaria você desconfortável, causaria dor e até deixaria sequelas.",
  [1139165182650368] = "Esta é sua primeira vez? Um pouco nervoso? Não se preocupe.",
  [1139165182650112] = "Pronto para quê?",
  [1139165182649856] = "Talvez eu possa descobrir algo dele. Você está pronto?",
  [1139165182649600] = "Este é Klein Moretti, o único sobrevivente dos três, mas perdeu a memória.",
  [1139165182649344] = "Olá, senhora.",
  [1139165182649088] = "Isso é realmente complicado...",
  [1139165182648832] = "Todos os espíritos que estavam originalmente aqui desapareceram, incluindo os de Welch e Naya. Os pequenos aqui não sabem de nada.",
  [1139165182648576] = "Daly, alguma descoberta?",
  [1139165182648320] = "Entrem, senhores, o que estão esperando?",
  [1139165182648064] = "Não se importe. Porém, sua Inspiração é alta; você tem algum talento.",
  [1139165182647808] = "Algo está errado aqui! Há, há alguma coisa?",
  [1139165182647552] = "Você saberá em breve. Vamos entrar.",
  [1139165182647296] = "Então qual é a identidade real dela?",
  [1139165182647040] = "A identidade disfarçada do especialista é—o <P_Yellow> Médium Espiritual </> mais famoso do condado de Awwa.",
  [752341905053696] = "Fantoche da Lua",
  [1139165182646784] = "Você deveria dizer que esteve aqui ontem. Aliás, esqueci de apresentá-la com antecedência...",
  [1139165182646528] = "Devo ter vindo aqui com frequência recentemente; Ainda tenho algumas vagas impressões deste lugar.",
  [1139165182646272] = "Para a cena do crime, residência do Sr. Welch. O “especialista” está nos esperando lá.",
  [1139165182646016] = "Tudo bem... para onde vamos agora?",
  [1139165182645760] = "Eu posso entender. Se fosse eu, faria o mesmo.",
  [1139165182645504] = "Receio que realmente tenha algo a ver comigo. Não me atrevo a apostar nisso, então prefiro fugir e começar uma nova vida.",
  [1139165182645248] = "Não me lembro do que fiz na casa de Welch, nem me lembro se causei diretamente a morte dele e de Naya.",
  [1139165182644992] = "Lógica interessante. Mas por que você fugiu no sonho? Do que você tem medo?",
  [1139165182644736] = "Talvez seja porque eu estava orando... esperando que tal poder me ajudasse.",
  [1139165182644480] = "Sim, mas você não parece surpreso. Meus clientes anteriores, mesmo depois de terem um sonho, não acreditariam em Beyonder poderes e prefeririam pensar que ainda não haviam acordado.",
  [1139165182644224] = "Sonhos... você me fez ter esse sonho agora há pouco? Esta é uma habilidade Beyonder?",
  [1139165182643968] = "Os acordados estão sempre cheios de mentiras, enquanto a verdade muitas vezes está escondida nos sonhos. Comparado ao você acordado, confio mais no você do sonho.",
  [1139165182643712] = "Você provavelmente ainda tem muitas dúvidas. Vamos conversar na carruagem; está nos esperando há muito tempo.",
  [1139165182643456] = "Tudo agora foi um sonho? Vigias Noturnos ? Beyonder incidentes?",
  [1139165182643200] = "Nós Vigias Noturnos pertencemos à <P_Yellow> Evernight Goddess Church </>, responsável por investigar e resolver incidentes extraordinários em Tingen. Por exemplo, este caso bizarro de suicídio.",
  [1139165182642944] = "Eu sempre estive aqui. Acabei de entrar no seu <P_Yellow> sonho </> e dei as orientações necessárias.",
  [1139165182642688] = "Como você está aqui!",
  [1139165182642432] = "<P_Heart> (E se eles descobrirem que sou um transmigrador, junto com aquele estranho espaço de névoa cinza...) </>",
  [1139165182642176] = "<P_Heart> (Se realmente fui eu quem causou a morte deles... não me lembro de nada. Serei preso?) </>",
  [1139165182641920] = "Um especialista?",
  [1139165182641664] = "Está tudo bem, eu tenho um jeito. Venha comigo ver um “especialista”; talvez ela possa ver a verdade oculta.",
  [1139165182641408] = "Mas eu realmente não me lembro de nada.",
  [1139165182641152] = "De qualquer forma, você agora é um suspeito de alto nível e deve vir comigo.",
  [1139165182640896] = "A ocultação não é uma boa escolha.",
  [1139165182640640] = "<P_Heart> (Ele acertou...) </>",
  [1139165182640384] = "Suspeito que, assim como seus amigos, você também sofreu um suicídio bizarro. É que por alguma razão especial você sobreviveu.",
  [1139165182640128] = "Você parece ter se limpado com cuidado, mas ainda há cheiro de sangue na sala.",
  [1139165182639872] = "Alguém já lhe disse que você é muito ruim em mentir?",
  [1139165182639616] = "Depois que saí da casa de Welch ontem, voltei direto para o apartamento e desde então estou me preparando para minha entrevista como palestrante...",
  [1139165182639360] = "No entanto, minha crença é inútil.",
  [1139165182639104] = "Eu acredito em você.",
  [1139165182638848] = "Isso se ajusta ao desenvolvimento que inferi e também à lógica oculta de eventos semelhantes, mas também não sei como você sobreviveu.",
  [1139165182638592] = "Você deveria ser capaz de ouvir minha sinceridade. <P_Heart> (Estou dizendo a verdade, claro, apenas parte da verdade!) </>",
  [1139165182638080] = "Mas parece que perdi algumas memórias, incluindo o que fiz ou vi no dia 27. Nem me lembro de ter ido à casa do Welch!",
  [1139165182637824] = "Só não sei por que minha cabeça ainda está intacta e ainda estou vivo.",
  [1139165182637568] = "Acordei no meio da noite passada e me vi em casa, mas havia uma pistola na minha mesa e sangue no quarto. Parecia que eu tinha experimentado um... suicídio.",
  [1139165182637056] = "Oficial, honestamente, também não me lembro. Por favor, acredite em mim.",
  [1139165182636800] = "<P_Heart> (Preciso pensar em como dizer isso...) </>",
  [1139165182636544] = "Um bom amigo, não é?",
  [1139165182636288] = "É apenas uma investigação de rotina. Um motorista de carruagem confirmou que você foi ontem à residência do Sr. Welch e até pagou sua passagem.",
  [1139165182636032] = "Você está... suspeitando de mim?",
  [1139165182635776] = "27 de junho, isso é ontem, onde você estava? O que você fez?",
  [1139165182635520] = "O caderno sumiu... <P_Heart> (Eu nem tinha pensado no paradeiro daquele caderno antes!) </>",
  [1139165182635264] = "O caderno que sobrou da Quarta Época não está em cena; não está na casa inteira e todos os outros envolvidos estão mortos.",
  [1139165182635008] = "Este não é um caso comum. Você é a única pista, e diz respeito ao paradeiro daquele <P_Yellow> Antígono Notebook </> .",
  [1139165182634752] = "Isso é impossível... Não consigo pensar em nenhuma razão para eles fazerem isso. Há alguma pista?",
  [1139165182634496] = "E a Sra. Naya se afogou em uma pia, hum, do tipo usado para lavar o rosto.",
  [1139165182634240] = "O Sr. Welch bateu a cabeça contra a parede, muitas vezes, cobrindo a parede de sangue.",
  [1139165182633984] = "A julgar pelos vestígios no local, eles cometeram suicídio – de uma forma assustadora e bizarra.",
  [1139165182633728] = "Como isso pôde acontecer?",
  [1139165182633472] = "Lamento muito, Welch faleceu ontem e a Sra. Naya também.",
  [1139165182633216] = "Aconteceu alguma coisa?",
  [1139165182632960] = "Hmm... o dono do notebook vem da família '<P_Yellow> Antigonus </> '. Esta família teve um status proeminente na Quarta Época, e há alguma história relacionada...",
  [1139165182632704] = "O que você interpretou?",
  [1139165182632448] = "Durante esse período, eu, ele e Naya nos encontrávamos frequentemente para interpretar e discutir um documento da Quarta Época que ele havia obtido recentemente.",
  [1139165182632192] = "Honestamente, tínhamos um relacionamento muito bom.",
  [1139165182631936] = "Você o viu recentemente?",
  [1139165182631680] = "Éramos colegas de universidade, ambos estudando com o professor associado sênior Cohen no Departamento de História.",
  [1139165182631424] = "Você conhece <P_Yellow> Welch </> , certo? Graduado pela Hoy University, em Coniston, Midseashire.",
  [1139165182631168] = "<P_Heart> (Por que alguém protestaria contra isso?) </>",
  [1139165182630912] = "Após a revogação das Leis do Milho, o país retomou a importação de grãos e cereais de países como Feysac, Masin e Lenburg, provocando a queda dos preços agrícolas...",
  [1139165182630656] = "...28 de junho de 1349 é a notícia de hoje.",
  [1139165182630400] = "O que há de errado com minha cabeça de novo? Tão tonto que tenho vontade de vomitar...",
  [1139165182630144] = "Parece que não poderei voltar para casa por um tempo... De agora em diante, sou Klein.",
  [1139165182629888] = "Como um sonho... o que exatamente é esse mundo de névoa cinzenta?",
  [1139165182628864] = "Tudo bem, vamos encerrar a reunião de hoje aqui.",
  [1139165182628608] = "<P_Heart> (O que está acontecendo? Minha cabeça dói um pouco, sinto que não aguento mais...) </>",
  [1139165182628352] = "<P_Heart> (Isso é como uma plataforma social online?) </>",
  [1139165182628096] = "<P_Heart> (Esta senhora é realmente pró-ativa. Participar de uma organização tão secreta tem prós e contras para nós. Pessoas de diferentes partes do mundo trocando informações neste espaço de névoa cinzenta...) </>",
  [1139165182627584] = "Você mesmo pode decidir esses assuntos triviais.",
  [1139165182627328] = "Tudo bem, então podemos nos considerar os membros fundadores do Clube do Tarô . Não tem problema, certo, Sr. Tolo?",
  [1139165182626816] = "<P_Heart> (Quem exatamente é o Sr. Tolo, uma existência tão majestosa e gentil...) </>",
  [1139165182626560] = "Decidido, meu título é: 'Justiça'!",
  [1139165182626304] = "Hmm, vou escolher as cartas do Tarô também.",
  [1139165182626048] = "Você é o Sr. Tolo, das cartas do Tarô. Como esta é uma “reunião” regular, de longo prazo e secreta, os títulos devem ser consistentes...",
  [1139165182625792] = "<P_Heart> (Boa ideia, não posso continuar chamando vocês de Sr. e Senhorita.) </>",
  [1139165182625536] = "Então não deveríamos nos dar títulos? Afinal, não podemos nos comunicar usando nossos nomes verdadeiros.",
  [1139165182625280] = "Toda segunda-feira, às três da tarde, irei convocá-lo regularmente aqui para uma reunião. Tente ficar sozinho.",
  [1139165182625024] = "Sou uma pessoa que gosta de troca equivalente e não vou deixar você ajudar incondicionalmente.",
  [1139165182624768] = "<P_Heart> (Não importa em que mundo, não existem apenas benefícios. Mas pelo menos a convocação e a dispensa da \"reunião\" estão sob meu controle...) </>",
  [1139165182624512] = "<P_Heart> (Mas quanto mais \"encontros\" houver, mais fácil será expor minha própria realidade...) </>",
  [1139165182624256] = "<P_Heart> ('Reuniões' podem me permitir obter mistérios mais extraordinários e conhecimento oculto, o que me ajudará a retornar ao meu mundo no futuro.) </>",
  [1139165182623744] = "Claro, dentro das nossas capacidades.",
  [1139165182623488] = "Sr. \"Tolo\", acho que esta é uma proposta muito boa. Contanto que a “reunião” se torne regular, se houver coisas que você achar inconveniente de resolver, você pode entregá-las totalmente para nós.",
  [1139165182623232] = "<P_Heart> (Uma senhora de nascimento nobre... Meu desempenho, meu sotaque é tão óbvio?) </>",
  [1139165182622976] = "A senhora da frente, que é claramente de origem nobre, e eu também temos nossos próprios recursos e conexões. Talvez um dia também possamos ajudá-lo a lidar com alguns pequenos assuntos.",
  [1139165182622720] = "Embora o seu poder exceda a nossa imaginação, sempre há áreas no mundo que você não entende ou nas quais não é bom.",
  [1139165182622464] = "Senhor “Tolo”, você não acha muito interessante esse tipo de “reunião”?",
  [1139165182622208] = "<P_Heart> (...talvez haja riscos, mas também é uma oportunidade!) </>",
  [1139165182621952] = "Sr. \"Tolo\", você se importa em ter mais algumas \"tentativas\" como essa?",
  [1139165182621696] = "Você pode continuar.",
  [1139165182621440] = "<P_Heart> (Um título do qual nunca ouvi falar, parece implicar segredos e poder terríveis...) </>",
  [1139165182621184] = "É nossa honra, Sr. Tolo.",
  [1139165182620928] = "Uma questão pequena.",
  [1139165182620672] = "Respeitado Sr. Tolo, permita-me fazer um pedido presunçoso: você pode ser a testemunha de nossa transação?",
  [1139165182620160] = "Você pode me ligar—",
  [1139165182619904] = "<P_Heart> (Em um lugar como este, não posso usar meu nome verdadeiro... Certo.) </>",
  [1139165182619648] = "Excelência, como devemos nos dirigir a você?",
  [1139165182619392] = "Muito bem.",
  [1139165182619136] = "<P_Heart> (Também não sei se a fórmula ou os materiais são reais, mas isso pode estar relacionado à minha transmigração...) </>",
  [1139165182618880] = "Sim! Excelência, por favor, seja testemunha da nossa transação.",
  [1139165182618624] = "Excelência, você pode nos puxar até aqui e possuir um poder além da nossa imaginação. Nem eu nem ela ousaríamos violar o testemunho que você forneceu.",
  [1139165182618368] = "Eu lhe darei um endereço. Quanto à garantia, penso que se tivermos o testemunho desta misteriosa Excelência, tanto você como eu ficaremos suficientemente tranquilos.",
  [1139165182618112] = "Se eu puder obtê-los, como devo entregá-los a você? E como posso garantir a autenticidade das fórmulas das poções?",
  [1139165182617600] = "Marinheiro e Espectador... então o que devo usar para trocar pelas fórmulas?",
  [1139165182617344] = "<P_Heart> ( Sequência 9? Fórmulas de poções? Marinheiro e Espectador? Beyonder se refere a alguém que possui habilidades extraordinárias?) </>",
  [1139165182617088] = "\"Marinheiro\" e \"Espectador\".",
  [1139165182616832] = "Realmente? Quais dois?",
  [1139165182616576] = "Não existe tal coisa de se tornar um Beyonder sem pagar um preço, mas... na verdade, tenho duas Sequência fórmulas de 9 poções em mãos.",
  [1139165182616320] = "Eu sei, mas me tornar oficial Beyonder significa perder minha liberdade... Não tem outro jeito?",
  [1139165182615808] = "... <P_Heart> (Este lugar respondeu aos meus pensamentos agora há pouco? Parece que consigo usar este espaço. Que incrível!) </>",
  [1139165182615552] = "<P_Heart> (Por exemplo, colocando aqui uma mesa comprida com inúmeras cadeiras de encosto alto esculpidas com padrões antigos e preenchidas com uma aura misteriosa, e eu me sentaria bem na cabeceira...) </>",
  [1139165182615296] = "<P_Heart> (Mas ficar aqui conversando? Não é muito sofisticado... Uma reunião misteriosa como essa deveria ser em um templo antigo e magnífico.) </>",
  [1139165182615040] = "<P_Heart> (Boa pergunta! Também quero saber a resposta...) </>",
  [1139165182614784] = "Não, o que quero dizer - o que quero dizer é, Excelência, o que devo fazer para me tornar um Beyonder ?",
  [1139165182614528] = "Esta é realmente uma experiência maravilhosa... bem, sempre estive ansioso por algo assim. Quer dizer, gosto de mistérios, gosto de milagres que transcendem a natureza.",
  [1139165182614272] = "Claro, se você solicitar formalmente, posso deixá-lo voltar agora.",
  [1139165182614016] = "<P_Heart> (Posso sentir sua leve conexão com essa névoa cinzenta. Se eu cortar essa conexão, as projeções se dissiparão e elas retornarão.) </>",
  [1139165182613760] = "<P_Heart> (Eles parecem ter sido trazidos aqui pelas estrelas vermelhas de antes, assim como as projeções das estrelas acima da névoa cinzenta...) </>",
  [1139165182613504] = "<P_Heart> (Eles estão me temendo... Neste incidente, eles são os convidados e eu sou o anfitrião!) </>",
  [1139165182613248] = "Excelência, a tentativa terminou? Você pode nos deixar voltar?",
  [1139165182612992] = "<P_Heart> (Uma tentativa? Uma única tentativa me permitiu 'vir' do meu quarto para este lugar cheio de névoa cinzenta? Isso é muito inconcebível!) </>",
  [1139165182612736] = "Uma tentativa.",
  [1139165182612480] = "<P_Heart> (Decidido. Usar o estado psicológico atual da outra parte e aproveitar minha maior vantagem!) </>",
  [1139165182612224] = "<P_Heart> (Talvez eu deva orientar o desenvolvimento como líder, manter um misterioso sentimento de opressão e obter informações e benefícios.) </>",
  [1139165182611968] = "<P_Heart> (Talvez eu deva fingir que não sei nada, esconder informações e ganhar confiança...) </>",
  [1139165182611456] = "Posso perguntar por que você me convocou aqui?",
  [1139165182611200] = "... <P_Heart> (Eu estava na sala e, num piscar de olhos, apareci neste lugar misterioso. Poderia ser... um incidente Beyonder!) </>",
  [1139165182610944] = "... <P_Heart> (Para poder me puxar à força para esse tipo de espaço sem que eu perceba qualquer anormalidade. Nunca ouvi falar de uma habilidade tão aterrorizante...) </>",
  [1139165182610688] = "... <P_Heart> (Onde é isso? O que eu quero fazer? Quem são vocês? Eu também quero saber...) </>",
  [1139165182610432] = "<P_Heart> (Meu destino foi adivinhado por um domador de feras? Como esperado, não existe adivinhação grátis neste mundo. Melhor fazer algo produtivo.) </>",
  [1139165182610176] = "Então esqueça, obrigado.",
  [1139165182609920] = "...Não.",
  [1139165182609664] = "É grátis?",
  [1139165182609408] = "Senhor, você precisa que eu interprete isso para você?",
  [1139165182609152] = "Não se importe; Eu simplesmente gosto disso, mas minhas adivinhações e interpretações às vezes são bastante precisas, na verdade...",
  [1139165182608128] = "<P_Heart> (O Louco? A carta zero do Tarô?) </>",
  [1139165182607872] = "O Louco, o início de todas as possibilidades, o conjunto de todas as incógnitas, o ponto de partida de todas as jornadas.",
  [1139165182607616] = "Tudo bem, qual cartão você deseja ver primeiro?",
  [1139165182607360] = "Tudo bem, por favor compre uma carta.",
  [1139165182606592] = "Por favor, entre na tenda.",
  [1139165182606336] = "...É tudo de graça, totalmente de graça, não será cobrado um único centavo, fique tranquilo.",
  [1139165182606080] = "Grátis adivinhação ? Poderia haver um problema... A interpretação é gratuita?",
  [1139165182605824] = "<P_Heart> (Grátis? As coisas que são gratuitas são as mais caras. Se você é tão capaz, divino que sou um transmigrador!) </>",
  [1139165182605568] = "Eu sou Sybil. Você é a primeira pessoa a vir para um adivinhação hoje, então é grátis.",
  [1139165182605312] = "Tarô? <P_Heart> (As cartas de tarô parecem ter sido inventadas pelo Imperador Roselle também. Eu me pergunto como isso difere do Tarô adivinhação da Terra...) </>",
  [1139165182605056] = "Senhor, adivinhação ? Meu Tarot adivinhação é muito preciso.",
  [1139165182604800] = "Senhor, você precisa de um adivinhação ?",
  [1139165182604544] = "Apresentação de circo? Melissa provavelmente gostaria disso. Gostaria de saber quanto custam os ingressos?",
  [1139165182603776] = "8 libras de pão, 9 centavos.",
  [1139165182603520] = "Não, sempre fui tão jovem. Quanto pão você quer comprar?",
  [1139165182603264] = "Muito obrigado, Sra. Stin, você parece uma senhora jovem e animada hoje.",
  [1139165182603008] = "Ele é um jovem diligente e você também se formou. Você estará ganhando dinheiro em breve e não deveria morar em um apartamento como este; você deveria pelo menos ter seu próprio banheiro.",
  [1139165182602752] = "Deveriam ser estes dias, que viagem de negócios longa e difícil.",
  [1139165182602496] = "Bom dia, pequeno Klein, Benson voltou?",
  [1139165182602240] = "Bom dia, Sra. Stin, estou aqui para comprar pão.",
  [1139165182601984] = "Espere! Ele poderia ser um antecessor transmigrador...",
  [1139165182601728] = "Este Sr. Roselle também inventou a máquina a vapor, melhorou os navios à vela e mais tarde transformou Intis em um império, autodenominando-se \"César, o Grande\"...",
  [1139165182601472] = "Eu me lembro... isto foi inventado por Roselle Gustav, a Cônsul da República Intis, há mais de cem anos.",
  [1139165182601216] = "Isso não é lutar contra o senhorio? Mas neste mundo, parece ser chamado de “Fight the Evil”, e a jogabilidade é bastante semelhante à da Terra.",
  [1139165182600960] = "Este é o último; vá comprar pão fresco. Melissa também me lembrou.",
  [1139165182600704] = "Tenho que tentar esse ritual novamente. Talvez eu possa voltar. Eu lembro... precisa de comida como meio para o ritual.",
  [1139165182600448] = "Eu realizei um <P_Yellow> Ritual de Virada de Fortuna. </> antes de dormir, aprendi com um livro que comprei em uma barraca de rua. Talvez seja por isso!",
  [1139165182600192] = "Esse “Resumo das Artes Secretas de Qin e Han”!",
  [1139165182599936] = "Espere, azar...?",
  [1139165182599680] = "Como eu transmigrei? Sou apenas uma pessoa comum vivendo no século XXI. Recentemente, além de um pouco de azar, não há nada de especial.",
  [1139165182599424] = "Hmm... estou com fome.",
  [1139165182599168] = "Pense bem novamente, como exatamente eu transmigrei?",
  [1139165182598912] = "Porém, eu não tenho uma irmã mais nova de verdade... Desculpe, Melissa, eu realmente quero <P_Yellow> ir para casa </> .",
  [1139165182598656] = "<P_Heart> (O olhar que Melissa acabou de me dar foi como se ela estivesse com pena de seu irmão com problemas mentais.) </>",
  [1139165182598400] = "Vejo você esta noite.",
  [1139165182598144] = "...Você está prestes a ter uma entrevista, vou fazer cordeiro guisado de ervilha para você.",
  [1139165182597888] = "Eu vou me atrasar! Lembre-se de comprar pão e também de cordeiro e ervilhas.",
  [1139165182597376] = "Você e Benson ainda não são casados ​​e cada centavo das despesas da família deve ser planejado.",
  [1139165182597120] = "E o aluguel semanal deste apartamento é de apenas 5 soli e 6 centavos.",
  [1139165182596864] = "Sem contar os domingos, são 12 soldos por semana.",
  [1139165182596608] = "Um total de 2 soli!",
  [1139165182596352] = "Se você e Benson também pegassem a carruagem, custaria 24 centavos por dia...",
  [1139165182596096] = "Uma viagem de carruagem só de ida custa 4 centavos e 8 centavos para uma viagem de ida e volta.",
  [1139165182595840] = "Cinquenta minutos? Você pode pegar uma carruagem, é muito longe.",
  [1139165182595584] = "Eu estou indo para a escola; leva cinquenta minutos para caminhar até lá. Klein, compre apenas quatro quilos de pão hoje. Está quente e estraga facilmente se comprarmos demais.",
  [1139165182595328] = "E você? São apenas seis horas; por que você está saindo tão cedo?",
  [1139165182595072] = "Obrigada, Melissa.",
  [1139165182594816] = "Mesmo que você não consiga, quero dizer, se você definitivamente conseguirá encontrar um emprego melhor!",
  [1139165182594560] = "<P_Heart> (Ela está preocupada que eu tenha insônia por causa da ansiedade em relação à entrevista?) </>",
  [1139165182594304] = "Hmm... Klein, na verdade você não precisa estar sob muita pressão. Você definitivamente passará na entrevista com professor universitário.",
  [598342094570752] = "Pensar",
  [1139165182593792] = "Isto... parece estar quebrado novamente.",
  [1139165182593280] = "Klein, o que você está fazendo tão cedo?",
  [1139165182593024] = "Não, não ficará limpo se eu limpar assim. Preciso usar algo para encobri-lo.",
  [1139165182592768] = "Na parede, no chão, na mesa, vermelho e branco... Ugh...",
  [1139165182592512] = "Não posso deixá-la ver isso!",
  [1139165182592256] = "Certo, Melissa está dormindo no quarto interno!",
  [1139165182591744] = "Por exemplo, o que exatamente aconteceu ontem...",
  [1139165182591488] = "Uma era estranha, um suicídio bizarro. Mas talvez porque uma bala passou pelo meu cérebro, há algumas coisas das quais não consigo me lembrar.",
  [1139165182591232] = "A Lua Vermelha se põe",
  [1139165182590976] = "E o ferimento na minha cabeça – na verdade, ainda estou vivo. Poderia essa estranha velocidade de cura ser um efeito terapêutico provocado pela minha transmigração?",
  [1139165182590720] = "Mas com minha formação familiar, onde eu teria dinheiro e canais para comprar uma arma?",
  [1139165182590464] = "Manchas de sangue e uma pistola, poderia ser... suicídio ou assassinato disfarçado de suicídio?",
  [1139165182590208] = "O que aconteceu no dia 27?",
  [1139165182589952] = "O diário só registra até o dia 26? A próxima página está escrita em Hermes: “Todos morrerão, inclusive eu”, e há manchas de sangue na página…",
  [1139165182589696] = "Hmm... o diário está gravado em Loenese e outras línguas. Felizmente, posso entendê-los fluentemente agora. Como esperado de um especialista em história...",
  [1139165182589440] = "Estou estudando um caderno antigo da Quarta Época com meus colegas Welch e Naya. Isto é muito interessante.",
  [1139165182589184] = "Algo especial recentemente é...",
  [1139165182588928] = "Acabei de me formar no Departamento de História da Universidade Hoy e estou trabalhando duro para me preparar para uma entrevista para um cargo de professor na Universidade Tingen, esperando começar a trabalhar em breve para aliviar a pressão financeira da nossa família.",
  [1139165182588672] = "A família agora depende inteiramente de Benson, que trabalha como escriturário, para nos sustentar. É muito difícil sustentar dois irmãos mais novos que ainda estão na escola ao mesmo tempo...",
  [1139165182588416] = "Moro neste apartamento com meu irmão mais velho, Benson, e minha irmã mais nova, Melissa; esta... é a nossa casa.",
  [1139165182588160] = "Ele era sargento do Exército Real, e a pensão após seu sacrifício me permitiu ter a oportunidade de estudar. Minha mãe também faleceu há alguns anos...",
  [1139165182587904] = "Um relógio de bolso? Também está quebrado. Parece... que esta é a coisa mais valiosa que meu pai deixou para trás.",
  [1139165182587648] = "Opções",
  [1139165182587392] = "Meu nome é... Klein Moretti, moro em Tingen, Reino de Loen, Continente Norte. Eu realmente transmigrei...",
  [1139165182587136] = "Junho de 1349, isto é um diário... Parece que me lembro de algo. É esta a memória deste corpo?",
  [1139165182586880] = "Certo, aquele caderno!",
  [1139165181856512] = "Ok, (Portão Chanis?)",
  [1139165182474496] = "Sr. Moretti, muito obrigado! Este é realmente o adivinhação mais mágico que eu já vi!",
  [1139165182553600] = "Eu preciso me apressar e avançar. Bem, depois de estabelecer as bases com o Capitão, apresentarei um pedido especial. Aliás, aproveitarei para dar uma dica do Método de atuação para ajudar o Capitão e os demais a reduzir o risco de perder o controle.",
  [1139165182553344] = "No entanto, eles provavelmente não esperavam que o ‘Tolo’, como líder, tivesse acabado de digerir a poção do ‘Vidente’.",
  [1139165182553088] = "Ufa, eu blefei... não, desenvolvi outro membro.",
  [1139165182552832] = "Vou obedecer às suas instruções.",
  [1139165182552576] = "Tudo bem, vamos parar por aqui por hoje.",
  [1139165182552320] = "Lembre-se de sua escolha; ele irá acompanhá-lo pelo resto da sua vida.",
  [1139165182552064] = "\"O Sol\", eu escolho \"O Sol\". Na Cidade de Prata, quando a luz do sol ainda brilha na terra, ainda há luz e ainda há esperança.",
  [1139165182551808] = "E agora você precisa determinar seu codinome. Exceto O Louco, a Justiça e o Enforcado.",
  [1139165182551552] = "Bem, espero que um dia você encontre uma maneira de se livrar da maldição.",
  [1139165182551296] = "Esta é a Cidade de Prata e é isso que conheço e experimentei.",
  [1139165182551040] = "Animação de grau B: Klein e Derrick seguram a espada, a mão de Derrick treme levemente, ele solta um soluço reprimido e, com um relâmpago no céu, ele insere a espada no Espírito Maligno de seus pais.",
  [1139165182550784] = "Pegue a espada e acabe com suas vidas.",
  [1139165182550528] = "Este é o nosso destino; essa é a vontade de Deus...",
  [1139165182550272] = "Não! Por que, por que estamos destinados a suportar tal maldição desde o nascimento e a ter que acabar com a vida de nossos pais com nossas próprias mãos?",
  [1139165182550016] = "Derrick, faça isso.",
  [1139165182549760] = "Vou descrevê-lo com sinceridade.",
  [1139165182549504] = "É a sua vez. Eu lhe dei uma chance de obter poder e você deve pagar o preço correspondente. A troca que exijo é: a história da Cidade de Prata.",
  [1139165182549248] = "Entendido, obedecerei às suas instruções.",
  [1139165182548992] = "Muito bem. Nos próximos dois dias, tente não ficar no mesmo quarto que os outros.",
  [1139165182548736] = "Eu quero me tornar um 'Sol' e obter a fórmula inicial da poção Sequência de você.",
  [1139165182548480] = "Eu posso te dar uma chance. O que você quer?",
  [1139165182548224] = "Não tenho interesse no sangue e nas almas dos mortais. No entanto-",
  [1139165182547968] = "Oferecerei minha alma e usarei sangue para agradar você.",
  [1139165182547712] = "Por que eu deveria ajudá-lo?",
  [1139165182547456] = "<P_Heart> (Ei, eu não sou uma máquina de realizar desejos. Espere, a Cidade de Prata que ele mencionou também foi mencionada no diário do Imperador Roselle antes. Deixe-me aprender sobre isso primeiro.) </>",
  [1139165182547200] = "Se, se for possível, também espero que meus pais possam ressuscitar.",
  [1139165182546944] = "Quer você seja um deus ou um tolo, minha oração permanece inalterada. Espero que todos na Cidade de Prata possam se livrar da maldição do destino e espero que o sol descrito nesses livros apareça no céu.",
  [1139165182546688] = "Eu não sou um deus; Sou apenas um tolo interessado em uma longa história.",
  [1139165182546432] = "Derrick abaixou repentinamente a cabeça: Não olhe diretamente para Deus.",
  [1139165182546176] = "Você é um deus?",
  [1139165182545920] = "[CS] Klein estende a mão para tocar a estrela vermelha no espaço de névoa cinza, de repente ondas de água emergem em seu corpo, e a estrela vermelha profunda irrompe com luz vermelha.",
  [1139165182545664] = "Bem, é isso que farei. Espero completar o avanço antes que a verdadeira crise chegue. Vamos voltar primeiro.",
  [1139165182545408] = "E com o caso da Sra. Daly como precedente, é bastante razoável inspirar-se nele para completar ainda mais o Método de atuação .",
  [1139165182545152] = "Recebi uma resposta positiva. Voltarei e estabelecerei algumas bases com o capitão, como descrever como meu espiritualidade se sente animado após cada visita ao Adivinhação Clube e, em seguida, descrever casualmente as regras resumidas de adivinhação ...",
  [1139165182544896] = "Talvez fazer uma inscrição especial e se tornar um 'Palhaço' abertamente seja uma escolha melhor.",
  [1139165182544640] = "No entanto, este caderno está atualmente com o Vigias Noturnos , e... eu vi nos documentos confidenciais do Vigias Noturnos ' que eles não forneceram os nomes das poções para o Vidente Sequência 8 e 7. Poderia haver algum segredo escondido dentro?",
  [1139165182544384] = "Este é o Caderno Antígono... Isso está me pedindo para usar o Caderno Antígono para atrair a Ordem Secreta para obter a fórmula do 'Palhaço', ou o próprio caderno contém a fórmula?",
  [1139165182544128] = "CS grau B: Na casa de Welch, Vincent e um membro da Ordem Aurora vendem o Caderno Antigonus para Welch, finalmente focando no caderno.",
  [1139165182543872] = "Pistas para a poção do palhaço...",
  [1139165182543616] = "Primeiro, use adivinhação para ver se existem outras maneiras de obter a fórmula 'Palhaço'.",
  [1139165182543360] = "Eu deveria obter a poção 'Palhaço' através da organização Vigias Noturnos. [Entre em Adivinhação Jogabilidade]",
  [1139165182543104] = "Se eu estabelecer algumas bases antes de me candidatar para lidar com a investigação, esta opção é claramente mais segura. Por segurança, é melhor executar um adivinhação .",
  [1139165182542848] = "A segunda é encontrar outras maneiras de obter a poção 'Palhaço' através de adivinhação .",
  [1139165182542592] = "Atualmente, existem duas opções: uma é seguir o exemplo da Sra. Daly e enviar um pedido especial ao Vigias Noturnos para promoção a 'Palhaço', mas posso ter que enfrentar uma investigação devido ao rápido avanço.",
  [1139165182542336] = "Lembro que no caso de Ray Bieber, o Palhaço de smoking mencionou que o Sequência 8 correspondente a 'Vidente' é 'Palhaço'.",
  [1139165182542080] = "Muita coisa aconteceu recentemente e finalmente tive a oportunidade de pensar adequadamente sobre meu avanço subsequente.",
  [1139165182541824] = "Bem, volte e aproveite o seu jantar. Pedirei a Swain para compensar o Feitiço do Sono que foi consumido agora; ele é um homem rico. Claro, não hoje; Eu tenho que considerar o humor dele.",
  [1139165182541568] = "Coincidentemente, também estou me preparando para voltar para casa.",
  [1139165182541312] = "Está ficando tarde, vou voltar. E você?",
  [813709739963136] = "OK.",
  [813709740047616] = "Por que?",
  [1139165182541056] = "<P_Heart> (O velho Neil me lembrou que a digestão da poção do Vidente ocorreu algumas semanas antes do esperado. Para o plano de avanço subsequente, é melhor ir para casa e adivinhá-la acima da névoa cinzenta.) </>",
  [1139165182540800] = "Você deve sempre permanecer vigilante no Mundo Extraordinário, especialmente durante a digestão e o avanço da poção.",
  [1139165182540544] = "Espero que esse dia nunca chegue.",
  [1139301010114560] = "Sua cabeça de repente dói violentamente. \n Enquanto isso, uma explosão de névoa vermelha se dissipa de seu corpo.",
  [1139301010116608] = "De repente, as cartas do Tarô voaram, resgatando você e Enid e apagando as velas rituais. Seu dono era—\n \"Um passageiro Vigia Noturno\".",
  [1139165182539776] = "Na verdade, uma grande parte dos casos de perda de controle que lidamos todos os anos são de nossos próprios colegas de equipe...",
  [1139165182539520] = "É verdadeiramente lamentável. Tal 'guarda' que matou muitos monstros finalmente perdeu o controle e se tornou um monstro...",
  [1139165182539264] = "Eu conheço esse Justiceiro. Ele seguiu Swain por muitos anos e eliminou fantasmas da água e capturou o mal que escapou Beyonders... mas agora...",
  [1139165182539008] = "Deixe o resto para Swain.",
  [1139165182538752] = "Eu sou um veterano Vigia Noturno ; Já lidei com muitos Beyonder incidentes no passado, só estou velho agora.",
  [1139165182538496] = "Você quer dizer que sou completamente diferente do que sou habitual, certo?",
  [1139165182538240] = "Sr. Neil, suas ações hoje foram muito ágeis e você estava mais calmo do que eu imaginava.",
  [1139165182537984] = "Esfaqueado por um fragmento voador. Se eu fosse mais jovem, definitivamente teria me esquivado.",
  [1139165182537728] = "Você está ferido?",
  [1139165182537472] = "Entendido.",
  [1139165182537216] = "Klein, prepare o Feitiço do Sono e jogue-o na hora apropriada.",
  [1139165182536960] = "Obrigado pelo seu trabalho duro, você pode deixar isso conosco.",
  [1139165182536704] = "Ele perdeu completamente a cabeça.",
  [1139165182536448] = "Seja meu apoio. Vamos.",
  [1139165182536192] = "<P_Heart> (O Velho Neil concordou diretamente sem dar desculpas...) </>",
  [1139165182535936] = "Ok, o que você precisa que façamos?",
  [1139165182535680] = "<P_Heart> (Embora eu tenha ouvido falar de oficial Beyonders perdendo o controle, esta é a primeira vez que o encontro, e é um Justiceiro. Como devo lidar com isso?) </>",
  [1139165182535424] = "Eu preciso de sua ajuda. Um membro do esquadrão dos Justiceiros perdeu o controle nas proximidades.",
  [1139165182535168] = "Vou tentar quando tiver oportunidade.",
  [1139165182534912] = "Muito bom. Se você precisar usar um feitiço em batalha, apenas entoe o encantamento, infunda-o com espiritualidade e jogue-o no alvo em três segundos.",
  [1139165182534656] = "Grave o feitiço 'Noite' no Antigo Hermes em ambos os lados de uma peça de prata e, em seguida, ore à Deusa para completá-lo.",
  [1139165182534400] = "Tudo comprado? A seguir, podemos usar os materiais e um ritual para fazer um Feitiço do Sono.",
  [1139165182534144] = "Você precisa de pó de ervas?",
  [1139165182533888] = "Você precisa de minerais naturais?",
  [1139165182533632] = "Você precisa de peças de prata semiacabadas?",
  [1139165182533376] = "<P_Heart> (Perdi outra chance de reembolso...) </>",
  [1139165182533120] = "Vamos ao mercado subterrâneo do Evil Dragon Bar.",
  [1139165182532864] = "Verifiquei sua cota de materiais para este mês esta manhã; infelizmente, já foi usado.",
  [1139165182532608] = "Sr. Neil, lembro que podemos solicitar materiais, certo?",
  [1139165182532352] = "Nada mal, então vamos começar a lição de hoje: fazer amuletos.",
  [1139165182532096] = "Eu estava pensando no que você disse antes e parece que obtive alguns insights.",
  [1139165182531840] = "<P_Heart> (Espere, digerindo a poção em um mês, essa velocidade definitivamente atrairá a suspeita dos superiores. É melhor estabelecer algumas bases primeiro.) </>",
  [1139165182531584] = "Como você está se sentindo? Você se acalmou?",
  [1139165182531328] = "Animação de grau B: \n Klein relembra as adivinhações desse período, um cristal amarelo aparece em sua mente e de repente ele tem alguns insights.",
  [1139165182531072] = "Adivinhação não é onipotente...",
  [1139165182530816] = "Só podemos guiar as coisas em uma boa direção a partir de símbolos vagos. Você pensa sobre isso primeiro...",
  [1139165182530560] = "Você tem usado adivinhação para resolver problemas recentemente, mas isso não significa que você pode confiar nele. Adivinhação não é onipotente.",
  [1139165182530304] = "No Mundo Extraordinário, há muitas maneiras de interferir em adivinhação , e Trissy deve ser de alta Sequência . Não é fácil capturar um Extraordinário deste nível.",
  [1139165182530048] = "Eu queria usar adivinhação para localizar para onde ela escapou, mas adivinhação sofreu interferência.",
  [1139165182529792] = "Interrompemos o ritual com sucesso, mas Trissy escapou.",
  [1139165182529536] = "Como foi seu caso ontem?",
  [1139165182529280] = "Klein, quer uma xícara de café?",
  [1139165182529024] = "Já era hora; Eu deveria voltar para a Blackthorn Security Company.",
  [1139165182528768] = "Será que ela sofreu um golpe muito forte e seu estado mental está instável? É uma pena que Visão Espiritual tenha sido interrompido. Parece que só posso respeitar os arranjos do destino.",
  [1139165182528512] = "Desculpe, vamos verificar a situação dela primeiro. Se eu encontrar algum pertence pessoal de Ince Zangwill, irei procurá-lo novamente.",
  [1139165182528256] = "Megose, espere por mim.",
  [1139165182528000] = "Eu deveria ir para casa... talvez o pai dele volte e deixe uma fortuna para ele.",
  [1139165182527744] = "Animação de grau C: Assim que Klein levantou a mão, antes que pudesse alcançar a glabela, Megose de repente se virou, caminhou rapidamente em direção à porta e saiu do clube.",
  [879891427886850] = "Caderno",
  [1139165182527488] = "<P_Heart> (O bebê em sua barriga zumbe e assobia? Isso não parece certo... É melhor verificar com Visão Espiritual .) </>",
  [1139165182527232] = "Ele me chuta suavemente todos os dias para me dizer seu humor, e ele cantarola músicas, assobia e usa música para me ajudar a adormecer...",
  [1139165182526976] = "Não, ele não é como o pai. Ele é uma criança muito atenciosa e simpática.",
  [1139165182526720] = "Mas se você for à clínica agora, ainda terá a chance de recomeçar, e isso pode nos ajudar a encontrar Ince Zangwill e recuperar o dinheiro que foi fraudado.",
  [1139165182526464] = "Acredito que manter esta criança tornará sua vida futura difícil; afinal, seu pai é um vigarista.",
  [1139165182526208] = "Vários meses... Até lá, ele terá gasto todo o dinheiro. Não, Megose, acho que você deve tomar uma decisão.",
  [1139165182525952] = "Se for uma criança que já nasceu, tenho como adivinhar. No entanto, dada a situação actual, ainda demorará vários meses.",
  [1139165182525696] = "<P_Heart> (Este Ince Zangwill é verdadeiramente desprezível; ele não apenas roubou dinheiro, mas também a enganou emocionalmente.) </>",
  [1139165182525440] = "Então seu filho conta como um item relacionado? Megose está grávida de seu filho. Sinto muito e estou arrependido; Achei Ince Zangwill um jovem notável e excelente, por isso os apresentei.",
  [1139165182525184] = "De um modo geral, sim.",
  [1139165182524928] = "Já ouvi antes que desde que você tenha um item relacionado à pessoa, você pode tentar adivinhar o paradeiro dela?",
  [1139165182524672] = "<P_Heart> (10.000 libras?! Com base no salário semanal anterior de Benson, levaria 208 anos para ganhar 10.000 libras. Essa quantia de dinheiro poderia tornar alguém uma pessoa rica, mesmo em Backlund!) </>",
  [1139165182524416] = "Sr. Moretti, queremos adivinhar o paradeiro de alguém. O nome dele é Ince Zangwill e ele roubou mais de 10.000 libras.",
  [1139165182523904] = "Sr. Moretti, olá. Meu nome é Christina e esta é minha sobrinha—",
  [1139165182523648] = "Hoje temos um membro que até trouxe um amigo para cá, por ter ouvido falar da sua reputação.",
  [1139165182523392] = "Todos ficam maravilhados com isso e dizem que é o adivinhação mais mágico que já ouviram falar.",
  [1139165182523136] = "O adivinhação que você fez para Anna da última vez já se espalhou por todo o clube.",
  [1139165182522880] = "O que há de errado, Angélica?",
  [1139165182522624] = "Bom dia, Sr. Moretti. Você finalmente veio para o clube.",
  [1139165182522368] = "<P_Heart> (Antes que o perigo em Tingen chegue, preciso me apressar e digerir minha poção para aumentar minha força.) </>",
  [1139165182522112] = "<P_Heart> (Meio dia de folga amanhã... É perfeito ir ao Adivinhação Clube pela manhã para atuar, e voltar para Blackthorn à tarde para continuar meus estudos de ocultismo.) </>",
  [1139165182521856] = "Hoje é muito tarde, você pode ir para casa primeiro e tirar meio dia de folga amanhã.",
  [1139165182521600] = "Além disso, farei com que o departamento de polícia fique atento a pistas sobre a mulher encapuzada.",
  [1139165182521344] = "Vou relatar os acontecimentos de hoje à Santa Catedral e emitir um mandado para Trissy. No mínimo, ela não poderá mais conduzir rituais de sacrifício abertamente.",
  [1139165182521088] = "Como esperado da Seita Demoness que tem estado ativa no cenário do continente desde a época anterior...",
  [1139165182520832] = "Há uma força interferindo no adivinhação ...",
  [1139165182520320] = "Klein, tente adivinhar o local da fuga de Trissy.",
  [1139165182520064] = "Então o que fazemos agora?",
  [1139165182519808] = "As coisas parecem mais complicadas do que eu pensava.",
  [1139165182519552] = "O desastre de Tingen, os casos de sacrifício, o Verdadeiro Criador, a Seita Demoness... quem poderia controlar tantos eventos e forças?",
  [1139165182519296] = "Embora tenhamos interrompido o ritual, parece que a crise ainda não foi resolvida.",
  [1139165182519040] = "Sim, ela está guiando o avanço de Trissy e criando essas tragédias.",
  [1139165182518784] = "Você acabou de mencionar que também havia uma mulher encapuzada?",
  [1139165182518528] = "É possível... talvez isso seja uma característica da poção deles, não, dela Sequência, onde em um certo Sequência , alguém muda de homem para mulher.",
  [1139165182518272] = "Trissy é Trissy; isso explica perfeitamente o mistério do súbito desaparecimento de Trissy.",
  [1139165182517760] = "Tenho uma ideia ousada.",
  [1139165182517504] = "Eles apareceram aqui, poderiam ser cúmplices?",
  [1139165182517248] = "O jovem em frente à mulher encapuzada parece ter alguma semelhança com Trissy, principalmente nos olhos.",
  [1139165182516992] = "Eu não tive tempo de investigá-la naquela época!",
  [1139165182516736] = "Lembro-me agora, já conheci Trissy na parada de carruagens públicas em frente a Blackthorn.",
  [1139165182516224] = "Três pessoas apareceram na imagem adivinhação: uma mulher misteriosa de capuz, um jovem bonito e Trissy, que acabou de escapar. Sempre sinto que já vi dois deles antes.",
  [1139165182515968] = "Algum ganho?",
  [1139165182515712] = "Trissy, se você quiser sobreviver, terá que pagar um preço, não é?",
  [1139165182515456] = "Chega de vagar, chega de passar fome, chega de ser comprado e vendido...",
  [1139165182515200] = "Esta é a resposta.",
  [1139165182514944] = "Você nem sempre achou estranho o fato de nossos superiores serem todos mulheres?",
  [1139165182514688] = "Devo avançar para uma Bruxa? Você está brincando?",
  [1139165182514432] = "Bruxa?!",
  [1139165182514176] = "Claro, o próximo Sequência para o seu avanço é—Bruxa.",
  [1139165182513920] = "Eu completei a missão. Você me prometeu os materiais para meu avanço.",
  [1139165182513664] = "(Espaço reservado para animação de grau B) Muito bem. Tingen tornou-se ainda mais caótico... O medo e a morte são sempre o melhor alimento.",
  [1139165182513408] = "Rezo para que este espelho seja brevemente restaurado e rezo para que ele revele todas as pessoas que refletiu no último mês.",
  [1139165182513152] = "Rezo pelo favor da Deusa;",
  [1139165182512896] = "Rezo ao poder do Sigilo;",
  [1139165182512640] = "Rezo ao poder da Noite;",
  [1139165182512384] = "Eu vou tentar.",
  [1139165182512128] = "Talvez possamos adivinhar as pessoas ou eventos que uma vez refletiu através do espelho?",
  [1139165182511872] = "Fragmentos de um espelho...",
  [1139165182511616] = "Isso mesmo. Este foi um ritual de maldição aterrorizante, mas felizmente foi interrompido.",
  [1139165182511360] = "Então salvamos pelo menos quarenta vidas?",
  [1139165182511104] = "Seus nomes aparecerão na lista de mortos da próxima semana.",
  [1139165182510848] = "Se não chegarmos a tempo, essas pessoas malditas...",
  [1139165182510592] = "Ela organizou uma causa de morte diferente para cada um.",
  [1139094851813376] = "Verifique a barriga da boneca",
  [1139094851684352] = "Dissuadir Enid",
  [1139094851686400] = "Anomalia à beira do lago",
  [1139165182510080] = "Lawrence... morreu de uma infecção no cadáver.",
  [1139165182509824] = "Joyce... morreu em consequência de um naufrágio.",
  [1139165182509568] = "Precisamos entrar na sala primeiro para interromper o Ritual de Sacrifício.",
  [1139165182509312] = "Não, ela é muito vigilante e também muito poderosa... pelo menos um Sequência 7 Extraordinário. Levará algum tempo para rastreá-la.",
  [1139165182509056] = "Devemos continuar a perseguição?",
  [1139165182508800] = "O alvo escapou...",
  [1139165182508544] = "Klein, você deve ter muito cuidado ao substituir Frye como suporte. Vou tentar puxá-la para um sonho.",
  [1139165182508288] = "Você se saiu bem. No entanto, ela cometeu várias tragédias e será definitivamente difícil de lidar. Deixe as ações subsequentes para Leonard e eu.",
  [1139165182508032] = "Segundo a revelação do adivinhação , o alvo está naquela casa azul à frente.",
  [1139165182507776] = "Eu não, fomos nós...",
  [1139165182507520] = "Você encontrou a localização do alvo?",
  [1139165182507264] = "Capitão, você está aqui.",
  [1139165182507008] = "Pense nisso de novo?",
  [1139165182506752] = "Assim como eu suspeitava. Vou avisar o Capitão, você vai até o altar e espera por nós.",
  [1139165182506496] = "Então ela escolheria o Distrito Sudoeste.",
  [1139165182506240] = "Então ela estaria em...",
  [1139165182505984] = "Para um criminoso que planeja e age com propósito, os alvos escolhidos no início seriam definitivamente distantes da área onde está localizado o altar, decorrente do instinto de busca por segurança.",
  [1139165182505728] = "Existem 2 locais que correspondem.",
  [1139165182505472] = "Este é o mapa de Tingen.",
  [1139165182505216] = "Eu vi um rio, uma casa azul-acinzentada de dois andares a noroeste e um jardim em ruínas na frente...",
  [1139165182504960] = "A localização do altar.",
  [1139165182504704] = "<P_Heart> (Esse cara geralmente é muito casual, mas na verdade ele é bastante confiável quando se trata de trabalho real. Vamos tentar com base em sua descrição.) </>",
  [1139165182504448] = "Tente adivinhar a localização do altar com base nessas características.",
  [1139165182504192] = "E a 'vida' roubada da Sra. Lowis, Sols e outros.",
  [1139165182503936] = "Deixe-me adivinhar... o cheiro da morte é denso e centrado em torno do altar, a temperatura ambiente está pelo menos 5 graus Celsius abaixo do normal e há um vento frio e gelado...",
  [1139165182503680] = "De acordo com o seu raciocínio, o objetivo do assassino é realizar um sacrifício, então como devemos encontrar a localização do altar?",
  [1139165182503168] = "Estou feliz por termos chegado a um consenso.",
  [1139165182502912] = "Compartilho dessa mesma atitude.",
  [1139165182502656] = "Claro, é melhor não contar essas coisas aos superiores. Esses caras são rígidos e conservadores, sempre acreditando que pessoas especiais como nós serão inevitavelmente atraídas por deuses e demônios malignos para a queda.",
  [1139165182502400] = "Da mesma forma, espero que você me veja com uma atitude semelhante.",
  [1139165182502144] = "Não acredito que um Extraordinário que esconde segredos seja necessariamente uma pessoa má. Contanto que suas ações não prejudiquem a mim ou ao Vigias Noturnos , você ainda é meu companheiro de equipe.",
  [1139165182501888] = "Certa vez eu lhe disse que existem muitas pessoas especiais neste mundo, como você e também como eu.",
  [1139165182501632] = "(Espaço reservado para animação de grau A) Klein, não há necessidade de fingirmos um com o outro.",
  [1139165182501376] = "Claro, é uma intuição instintiva.",
  [1139165182501120] = "Você tem certeza? Mas nossa amostra de investigação ainda é de apenas dois por enquanto.",
  [1139165182500864] = "Vamos, vamos procurar o assassino.",
  [1139165182500608] = "É o suficiente. Tenho certeza de que o objetivo do assassino ao criar a morte e o horror é invocar um deus maligno ou executar uma maldição terrível e em grande escala.",
  [1139165182500352] = "É colher uma grande quantidade de vida em pouco tempo para realizar um Sacrifício? No entanto, investigamos apenas dois casos até agora e o tamanho da amostra não é suficiente.",
  [1139165182500096] = "Mas o ponto mais crítico é o seu propósito em criar múltiplas mortes.",
  [1139165182499840] = "Isso está correto. Se pessoas saudáveis ​​morressem inexplicavelmente, isso certamente atrairia a atenção após mais de três casos.",
  [1139165182499584] = "Escolher pessoas que estão prestes a morrer é uma forma de encobrir a causa da morte?",
  [1139165182499328] = "Por que o assassino faria isso?",
  [1139165182499072] = "A Sra. Lowis e o incendiário estavam ambos destinados a morrer num futuro próximo; o assassino simplesmente antecipou suas mortes.",
  [1139165182498560] = "Também descobri algo bastante estranho.",
  [1139165182498304] = "A mesma voz; é a mesma pessoa que está causando essas mortes.",
  [1139165182498048] = "O que você encontrou?",
  [1139165182497792] = "Hum, vou tentar.",
  [1139165182497536] = "Embora o motivo e o comportamento correspondam aos de um incendiário, é melhor realizar outro adivinhação .",
  [1139165182497280] = "Claro.",
  [1139165182497024] = "Presidente, precisamos conduzir uma investigação especial aqui. Você poderia, por favor, sair por um momento?",
  [1139165182496768] = "Depois que ele faliu, parece que ele estava preparado para morrer há muito tempo.",
  [1139165182496512] = "Segundo a pessoa que dormia ao lado dele, Sols ficou ressentido depois de falir. Mas ninguém esperava que ele pretendesse quebrar todas as lamparinas de querosene enquanto todos dormiam...",
  [1139165182496256] = "Havia algo incomum nele antes de morrer?",
  [1139165182496000] = "Sim, foi Sols. Felizmente, foi descoberto a tempo, caso contrário todos os moradores do asilo teriam morrido no incêndio.",
  [1139165182495744] = "Dizem que um incendiário morreu queimado aqui há alguns dias?",
  [1139165182495488] = "Obrigado pela sua generosidade.",
  [1139165182495232] = "Este é o dinheiro para o enterro. Assim que o caso estiver encerrado, por favor providencie o funeral da Sra. Lauwis.",
  [1139165182494976] = "Você pode deixar o corpo na mesa à noite, e quando comer é só levar ela para a cama...",
  [1139165182494720] = "Tudo bem. Na verdade, ainda não tenho dinheiro para enterrá-la; Ainda preciso economizar para mais alguns dias... Ainda bem que o tempo esfriou recentemente.",
  [1139165182494464] = "Aliás, o corpo pode esperar mais um dia pelo enterro? Talvez haja mais um exame.",
  [1139165182494208] = "Você pode entrar agora.",
  [1139165182493952] = "Vamos verificar o asilo ao lado e ver se há alguma semelhança entre os dois casos.",
  [1139165182493696] = "Sim, mas esta é apenas a minha interpretação; adivinhação geralmente é vago.",
  [1139165182493440] = "Quer dizer, o fator sobrenatural existia no tapinha que a Sra. Lauwis recebeu, vindo daquela senhora ou senhorita de mãos finas.",
  [1139165182493184] = "Vi um par de mãos finas e claras, que parecem pertencer a uma senhora.",
  [1139165182492928] = "Tudo bem, vá em frente. Morto, não há mais necessidade de morrer de fome.",
  [1139165182492672] = "Embora o atendimento médico beneficente seja gratuito... leva um dia inteiro... esqueça, se eu não trabalhar hoje, não terei comida amanhã...",
  [1139165182492416] = "(Espaço reservado para nível C) Meu peito está tão entupido...",
  [1139165182492160] = "Sim, espero ganhar algo com o resíduo espiritualidade da Sra. Lowis.",
  [1139165182491904] = "Tudo bem, Klein, você pode começar a Mediunidade Espiritual.",
  [1139165182491648] = "Tudo bem.",
  [1139165182491392] = "Precisamos examinar o corpo, então, por favor, espere lá fora por alguns minutos. Faremos um exame aprofundado do cadáver e não acho que você gostaria de ver o que se segue.",
  [1139165182491136] = "Existem muitas situações assim aqui... Só podemos tentar o nosso melhor para ajudá-los a encontrar a verdade, e o resto só pode depender da consciência dos vereadores.",
  [1139165182490880] = "Fazer 130 caixas de fósforos só rende o suficiente para comprar um quilo de pão preto...",
  [1139165182490624] = "Um tapete custa 1 xelim por semana, então só precisamos pagar 2 xelins e 10 centavos por semana...",
  [1139165182490368] = "Uma cesta tem cerca de 130 caixas, então só posso alugar o espaço livre para outras pessoas...",
  [1139165182490112] = "Não, ele é apenas um inquilino. Este quarto custa 3 xelins e 10 centavos por semana, e minha esposa só ganha 2,25 centavos por colar 1 cesta de caixas de fósforos.",
  [1139165182489856] = "O homem que está na porta também é membro da sua família?",
  [1139165182489600] = "Ela disse que estava cansada e me pediu para conversar com as duas crianças, e ela iria descansar um pouco. Quando olhei para ela novamente, ela tinha... parado de respirar.",
  [1139165182489344] = "Depois que o sol se pôs, ela parou de trabalhar. Velas e querosene são muito mais caras que caixas de fósforos.",
  [1139165182489088] = "Você pode descrever o processo das mortes?",
  [1139165182488832] = "Desde a semana passada, hum, talvez anteontem, ela sempre dizia que estava abafado aqui e que ela não conseguia respirar.",
  [1139165182488576] = "Houve algo incomum antes de sua esposa morrer?",
  [1139165182488064] = "Este é o nosso dever, por favor coopere.",
  [1139165182487808] = "Alguém voltando a entender... de que adianta entender? As pessoas não voltarão à vida.",
  [1139165182487552] = "Queremos entender algumas coisas.",
  [1139165182487296] = "Com este tempo, deveria haver cheiro de cadáveres em decomposição, o que significa que os corpos ainda não foram enterrados.",
  [1139165182487040] = "Você sente o cheiro? Parece haver um cheiro.",
  [1139165182486784] = "A renda da grande maioria deles não consegue nem manter alimentos e roupas básicas.",
  [1139165182486528] = "Seus braços, suas pernas, finos como fósforos.",
  [1139165182486016] = "Vamos primeiro para a casa da Sra. Lauwis, vamos.",
  [1139165182485504] = "Você deve ir ao Distrito da Fábrica e conduzir uma investigação mais aprofundada. Klein pode fornecer suporte com adivinhação ou Ritual Magic.",
  [1139165182485248] = "Você está dizendo que existe um poder extraordinário causando deliberadamente essas mortes?",
  [1139165182484992] = "O número de mortes nas últimas duas semanas é cinco vezes a taxa normal... O Departamento de Polícia de Tingen descobriu isso enquanto compilava estatísticas e imediatamente transferiu o assunto para nós.",
  [1139165182484736] = "Isso não é um pouco demais?",
  [1139165182484480] = "Além da tragédia que Klein acabou de mencionar, aqui está um relatório de investigação.",
  [1139165182484224] = "Vamos falar primeiro sobre a situação no Distrito Fabril.",
  [1139165182483968] = "No entanto, é como se Trissy tivesse evaporado de Tingen. As autoridades continuarão a investigar este assunto.",
  [1139165182483712] = "Não admira que o Sr. Meyer tenha mencionado que todos no Clover pareciam estar possuídos por um demônio.",
  [1139165182483456] = "Essa possibilidade não pode ser descartada. Um “Instigador” é bom em induzir desejos malignos no coração de todos e criar conflitos.",
  [1139165182483200] = "Ele incitou brigas internas, fazendo com que as pessoas no navio se matassem?",
  [1139165182482944] = "Os Punishers e Vigias Noturnos já intervieram na investigação do incidente Clover. Eles suspeitam que Trissy é uma Sequência 8 'Instigadora' e já emitiu um mandado.",
  [1139165182482688] = "Klein, você fala primeiro.",
  [1139165182482432] = "Coincidentemente, eu também.",
  [1139165182482176] = "Capitão, tenho algo a relatar.",
  [1139165182481920] = "Não tive tempo de verificar com Visão Espiritual . Esqueça, voltarei para Blackthorn primeiro.",
  [1139165182481664] = "Desça da carruagem rapidamente; não bloqueie a porta.",
  [1139165182481408] = "Obrigado pela sua preocupação, estou bem, só um pouco cansado.",
  [1139165182481152] = "Senhorita, você está bem?",
  [1139165182480896] = "<P_Heart> (Tenho que admitir, essa é a garota mais linda que já vi desde que transmigrei. Estranho, por que ela fica tremendo o tempo todo?) </>",
  [1139165182480640] = "Vapor acima, minha pobre Joyce, você deve ter ficado apavorada, vamos para casa primeiro.",
  [1139165182480384] = "<P_Heart> (Mencionando o Distrito Fábrica novamente... Isso tem alguma conexão com o desastre de Tingen que aprendi anteriormente? Independentemente disso, devo retornar a Blackthorn para relatar isso ao Capitão.) </>",
  [1139165182480128] = "Comparados aos marinheiros do Distrito das Fábricas e da Rua Cruz de Ferro que foram enterrados no mar, já somos considerados sortudos.",
  [1139165182479872] = "Que desastre, felizmente, todos vocês obtiveram segurança.",
  [1139165182479616] = "<P_Heart> (Triss... será que ele salvar as pessoas foi apenas uma fachada, e ele estava realmente empurrando todos para o abismo?) </>",
  [1139165182479360] = "Eu... eu vi. Ele é— <P_Yellow> Triss </>.",
  [1139165182479104] = "Talvez o seu espiritualidade esteja lembrando você de que essa pessoa é anormal, mas você está inconscientemente evitando suspeitar dela, e é por isso que você não consegue ver sua aparência. Tente ver claramente o dono dessas mãos.",
  [1139165182478848] = "Eu vi um par de mãos me salvar, mas finalmente, elas de repente me soltaram com um sorriso. Não consegui ver seu rosto com clareza e então todo o meu corpo começou a cair rapidamente.",
  [1139165182478592] = "Sr. Meyer, por favor feche os olhos agora e descreva em detalhes as imagens que viu em seu sonho.",
  [1139165182478336] = "Para um Vidente, os sonhos são revelações dadas pelos deuses e um lembrete do seu espiritualidade .",
  [1139165182478080] = "<P_Heart> (Possessão demoníaca... Poderia a tragédia de Clover não ter sido um acidente?) </>",
  [1139165182477824] = "Desde a tragédia, tenho tido o mesmo pesadelo. Eu sonho que o Clover estava normal por um segundo, e então um conflito irrompeu de repente, como se eles estivessem possuídos por demônios. Sr. Moretti, você consegue interpretar esse sonho?",
  [1139165182477312] = "No entanto...",
  [1139165182477056] = "<P_Heart> (Triss... esse garoto, realmente capaz de permanecer racional e calmo em um momento tão perigoso.) </>",
  [1139165182476800] = "Se não fosse ele, eu poderia ter acabado como aqueles marinheiros e passageiros do convés inferior, enterrados no mar.",
  [1139165182967808] = "A passagem mais rápida é em três dias; os ingressos de convés custam 3 soli, os ingressos de cabine custam 6 soli.",
  [1139165182836736] = "Eu me pergunto se a senhorita Justiça e o Enforcado encontraram um ambiente adequado. É uma pena que este mundo não tenha telemóveis e internet, impossibilitando a comunicação instantânea.",
  [1139165182475776] = "Triss, Triss, você mencionou esse nome o tempo todo.",
  [1139165182475520] = "Depois que encontramos piratas, houve uma briga interna repentina. Todos eram como uma fera, matando uns aos outros no navio. Minha visão estava cheia de sangue... Felizmente, havia um herói no navio—",
  [1139165182475264] = "Falando francamente, ainda sinto que estou sonhando que consegui voltar vivo, e ainda não consigo acreditar que sobrevivi à tragédia do <P_Yellow> Clover </>...",
  [1139165182245888] = "Depois de reservar o aluguel da nova casa, deve sobrar bastante dinheiro, o suficiente para que todos comprem um conjunto de roupas novas.",
  [1139165182475008] = "Estou simplesmente contando a ela o destino que vi.",
  [1139165181919232] = "Vá despejar já!",
  [1139165181842432] = "Nada mal, você não pode dizer que esta é uma pobre alma que morreu ontem.",
  [1139165182708736] = "O ritual atraiu o olhar de um deus maligno e tudo ao redor foi corrompido.",
  [1139165182585856] = "Isso... acorde, Zhou Mingrui! O que está acontecendo? Eu poderia ter transmigrado?",
  [1139165182444544] = "Então, vamos começar...",
  [1139165182312448] = "Mas se eu correr o risco de voltar assim, não há garantia de segurança... E se eu for controlado pelo 2-049 novamente?",
  [1139165182296064] = "Ray não é uma pessoa má, se você puder vê-lo...",
  [1139165182474240] = "Você pode descansar no corredor e esperar pelo próximo cliente que precisa de um adivinhação . Vou preparar uma xícara de chá preto Sibe para você.",
  [1139165182473984] = "Obrigado. Espero que tudo corra bem.",
  [1139165182473728] = "<P_Heart> (Este também é um agradecimento por sua recomendação.) </>",
  [1139165182473472] = "Obrigado por cuidar do meu convidado. Ela me deu uma dica, então eu também deveria te dar uma dica.",
  [1139165182473216] = "Sim.",
  [1139165182472960] = "Um bom resultado?",
  [1139165182472704] = "Oh, Senhor do Vapor, isso é verdade? Eu vou voltar agora. Se for verdade, voltarei para agradecer.",
  [1139165182472448] = "Parabéns, senhorita Anna, o senhor Joyce Meyer está visitando sua casa. Se você voltar correndo agora, ainda poderá pegá-lo.",
  [1139165182472192] = "Esse foi um presente que ele me deu, está bem na minha porta. Como, como você sabia?",
  [1139165182471936] = "Existe um moinho de vento de brinquedo na sua porta?",
  [1139165182471680] = "Como é o resultado?",
  [1139165182471424] = "Senhorita Anna, tenho o resultado.",
  [1139165182471168] = "<P_Yellow> Hornacis </> ... Não importa, vamos resolver o problema da Srta. Anna primeiro.",
  [1139165182470912] = "A propósito, aquele caderno mencionava a Terra da Noite na cordilheira <P_Yellow> Hornacis </>! O palácio do sonho agora estava no pico da montanha!",
  [1139165182470656] = "Um palácio não-humano no pico de uma montanha... o olhar silencioso sobre mim... as imagens distorcidas e estranhas de vermes...",
  [1139165182470400] = "O sonho inicial era o resultado adivinhação, e a última parte? Parece ser direcionado a mim?",
  [1139165182470144] = "É melhor verificar isso com dream adivinhação também.",
  [1139165182469888] = "A julgar grosseiramente, é seguro, mas a primeira ordem diz respeito à minha reputação.",
  [1139165182469632] = "Retornando com segurança.",
  [1139165182469376] = "A situação atual de Joyce...",
  [1139165182469120] = "Por favor, espere lá fora por um momento.",
  [1139165182468864] = "Joyce Meyer partiu em 3 de junho de 1349.",
  [1139165182468608] = "Pêndulo adivinhação , mas preciso do nome do seu noivo e horário de partida.",
  [1139165182468352] = "<P_Heart> (Esta situação é mais adequada para astrolábio adivinhação , mas não trouxe astrolábio hoje, então só posso usar pêndulo adivinhação .) </>",
  [1139165182468096] = "Você é o adivinho, você decide.",
  [1139165182467840] = "Que tipo de adivinhação você gostaria de usar?",
  [1139165182467584] = "Quero adivinhar a situação do meu noivo. Ele saiu para o mar para um negócio e ainda não voltou.",
  [1139165182467328] = "Senhorita Anna, o que você gostaria de adivinhar?",
  [1139165182467072] = "Vocês dois, a Sala do Cristal Amarelo está atualmente gratuita, por favor, sigam-me.",
  [1139165182466560] = "Posso confirmar que o Sr. Moretti é um excelente adivinho. Ele acabou de executar um adivinhação para um cavalheiro e o resultado foi muito preciso.",
  [1139165182466304] = "Klein Moretti... diz aqui que ele se juntou ao clube hoje. O nível dele é confiável?",
  [1139165182466048] = "Então recomendo este Sr. Moretti.",
  [1139165182465792] = "Apenas me chame de Anna. Você pode recomendar um?",
  [1139165182465536] = "Senhora, você pode escolher qualquer adivinho.",
  [1139165182465280] = "Olá, gostaria de fazer um adivinhação.",
  [1139165182465024] = "Tudo bem. A partir de hoje você é membro oficial do Clube Adivinhação e seu nome já está na lista de adivinhos.",
  [1139165182464768] = "Realmente? Esta é a nossa honra. Vou registrar suas informações de adesão.",
  [1139165182464512] = "Ah, estou aqui hoje para me juntar ao clube, aqui está a taxa de adesão.",
  [1139165182464256] = "<P_Heart> (Como já estou aqui, posso muito bem entrar no clube e ver se algum cliente pode fornecer novas pistas.) </>",
  [1139165182464000] = "Sinto muito, estava muito ocupado ficando triste e esqueci de entretê-lo. Você está aqui hoje para um adivinhação ou para entrar no clube?",
  [1139165182463744] = "<P_Heart> (As emoções e reações de todos são muito razoáveis...) </>",
  [1139165182463488] = "Ele era um cavalheiro gentil, educado e verdadeiro, e um mentor espiritual para muitos membros...",
  [1139165182463232] = "Seu resultado adivinhação é muito preciso. O Sr. Vincent nos deixou para sempre devido a um ataque cardíaco repentino.",
  [1139165182462976] = "Vi que Haines não estava aqui quando entrei, então fiz uma rápida adivinhação sobre a situação dele, mas não esperava obter um resultado tão lamentável.",
  [1139165182462720] = "Sr. Moretti, você ouviu falar disso tão rapidamente?",
  [1139165182462464] = "Senhorita Angélica, você está triste com o que aconteceu com o Sr. Haines Vincent?",
  [1139165182462208] = "Ele, ele ainda era tão jovem... como ele poderia...",
  [1139165182461952] = "Tudo bem, Sr. Neil, vou indo agora.",
  [1139165182461696] = "A propósito, não se esqueça da aula de ocultismo de amanhã.",
  [1139165182461440] = "Solicitarei o reembolso imediatamente após pagar a taxa anual.",
  [1139165182461184] = "Ou você prefere usar seu próprio dinheiro para fazer isso?",
  [1139165182460928] = "O Clube Adivinhação tem cultistas e membros de organizações malignas misturados. Como padrão Beyonder do esquadrão Vigias Noturnos, juntar-se a eles torna mais fácil monitorá-los. Isso é inteiramente para fins de trabalho.",
  [1139165182460672] = "Isso também pode ser reembolsado?",
  [1139165182460416] = "Quanto à anuidade do clube... você pode reembolsá-la.",
  [1139165182460160] = "Seu pensamento é muito parecido com o de Daly; ela sempre diz que quer ser uma médium espírita de verdade.",
  [1139165182459904] = "As habilidades da minha poção estão relacionadas a adivinhação , e devo realizar adivinhações para um grande número de pessoas para acelerar meu domínio. Então pretendo me juntar ao clube e me tornar um verdadeiro Vidente.",
  [1139165182459648] = "E o seu dinheiro não é para a anuidade do Clube Adivinhação? A propósito, o que você está fazendo aí?",
  [1139165182459392] = "Não, eu tenho meus próprios caminhos.",
  [1139165182459136] = "Sr. Neil, então você precisa de dinheiro emprestado?",
  [1139165182458880] = "Para Beyonders como nós, que precisamos frequentemente explorar segredos, praticar e tentar rituais, o salário nunca é suficiente.",
  [1139165182458624] = "Sr. Neil, você também precisa de dinheiro?",
  [1139165182458368] = "Que invejável. Se você encontrar comissões semelhantes no futuro, lembre-se de me avisar.",
  [1139165182458112] = "10 libras! Louvado seja a Deusa, a taxa anual do Clube Adivinhação está coberta.",
  [1139165182457856] = "A recompensa total é de 200 libras. De acordo com as regras do capitão, metade vai para fundos extras e metade vai para você e Leonard. Como você não é um membro formal, recebe apenas dez por cento dessa metade.",
  [1139165182457600] = "Obrigado, nosso excelente graduado da Hoy University, essas 10 libras pertencem a você.",
  [1139165182457344] = "Bom dia, dona Orianna, você está linda como sempre todos os dias.",
  [1139165182457088] = "<P_Heart> (Essa recompensa chegou na hora certa; felizmente o capitão não esqueceu!) </>",
  [1139165182456832] = "10 libras!",
  [1139165182456576] = "Quase esqueci, a recompensa pelo caso anterior de sequestro de Elliot chegou; você pode ir até a Sra. Orianna para coletar 10 libras.",
  [1139165182456320] = "Klein, você vai ao Clube Adivinhação e observa as reações dos membros à morte repentina de Haines Vincent.",
  [1139165182456064] = "No entanto, só podemos partir de outras pistas agora. Leonard, vá primeiro à delegacia e veja se houve algum caso incomum no distrito fabril recentemente.",
  [1139165182455808] = "Isso é realmente muita coincidência.",
  [1139165182455552] = "Ele morreu quando estávamos prestes a continuar a investigação?",
  [1139165182455296] = "Ataque cardíaco repentino, nenhuma outra anormalidade foi encontrada.",
  [1139165182455040] = "Haines Vincent está morto... qual foi a causa da morte?",
  [1139165182454784] = "Ela parece muito focada... Eu deveria ir até ela e cumprimentá-la.",
  [1139165182454528] = "Sério, quando haverá uma linha direta para a Baía de Disi? Não quero pegar um barco de novo; é muito desconfortável!",
  [1139165182454272] = "O trem a vapor \"Flying\" para Constant City abre hoje...",
  [1139165182454016] = "Aguardemos ansiosamente o próximo encontro.",
  [1139165182453504] = "Eu obedeço à sua vontade.",
  [1139165182453248] = "Para aqueles que não são membros do encontro, não devem divulgar os segredos deste lugar sem minha permissão.",
  [1139165182452992] = "Este é o começo do Clube do Tarô , mas ainda precisamos permanecer escondidos atrás da história e das massas. Portanto-",
  [1139165182452736] = "Se não houver mais nada, vamos encerrar aqui o encontro de hoje. <P_Heart> (Minha cabeça dói um pouco, sinto que não aguento mais...) </>",
  [1139165182452224] = "...Estou me preparando para experimentar um novo Ritual de Magia em você, sua coisinha nojenta!",
  [1139165182448896] = "Há algo ruim no copo à <P_Yellow> direita </> .",
  [1139165182446080] = "Frase de dedução três",
  [1139165182445824] = "Frase de dedução dois",
  [1139165182445568] = "Frase de dedução um",
  [1139165182445312] = "O que devo fazer com os ingredientes de casa... É hora de mostrar a ela alguns verdadeiros dotes culinários!",
  [1139165181856256] = "Sr. Moretti, por favor, venha comigo. O capitão está guardando o <P_Yellow> Portão Chanis </> hoje e não pode sair.",
  [1139165182421248] = "Como antes, cante o nome honorífico do grande mestre e ore pedindo permissão para entrar na névoa da história.",
  [1139165182420992] = "Estou pronto para entrar novamente na névoa da história.",
  [1139165182420736] = "3 Texto formal ainda não definido; este é um texto temporário para o fluxo de trabalho.",
  [1139165182420480] = "Aham, não é nada. Entrei no <P_Yellow> sonho de Haines </> ontem e descobri algumas coisas...",
  [1139165182420224] = "Capitão, você está bem?",
  [1139165182419968] = "Eu irei agora.",
  [1139165182419712] = "O capitão está de volta, ele quer que você vá ao escritório dele <P_Yellow></> . Porém, o rosto do capitão está excepcionalmente pálido, não sei o que aconteceu.",
  [1139165182419456] = "...Rozanne, o que há de errado?",
  [1139165182419200] = "Klein, acorde.",
  [1139165182418944] = "Capitão, Haines Vincent - está <P_Yellow> morto </> .",
  [1139165182418688] = "...Está tudo bem, talvez eu tenha descansado muito pouco ultimamente.",
  [1139165182418432] = "Capitão, o que aconteceu com você?",
  [1139165182418176] = "Parece que é necessária uma investigação mais aprofundada sobre Haines para descobrir a conspiração da organização por trás dele.",
  [1139165182417920] = "Essa possibilidade não pode ser descartada. O ressentimento no distrito fabril... o desastre em Tingen...",
  [1139165182417664] = "Existe uma organização secreta criando uma crise em Tingen?",
  [1139165182417408] = "<P_Heart> (Isso é um pouco semelhante ao Verdadeiro Criador adorado por várias organizações secretas, mas também há diferenças significativas...) </>",
  [1139165182417152] = "A investigação foi assim: no sonho de Haines, eu vi um <P_Yellow> homem nu pendurado </>. A proteção do meu espiritualidade me fez desmaiar imediatamente.",
  [1139165182416896] = "Capitão...",
  [1139165182416640] = "O apocalipse cairá sobre Tingen... o que exatamente eles estão tentando fazer?",
  [1139165182416384] = "Até então, oferecerei todos os cordeiros da cidade de Tingen ao Senhor.",
  [1139165182416128] = "Esse plano também está em andamento... embora a possibilidade seja pequena, o ressentimento no distrito fabril está crescendo dia a dia e o apocalipse cairá sobre Tingen. O ritual pode ter sucesso.",
  [1139165182415872] = "O notebook já foi vendido...",
  [1139165182415616] = "Isso poderia ser muita coincidência?",
  [1139165182415360] = "Na verdade, o caderno foi vendido para Welch por Haines, e eu conheci Haines no clube...",
  [1139165182415104] = "Venda. Já encontrei um comprador, Welch.",
  [1143492898197504] = "Nada mais.",
  [1139165182414592] = "E esse caderno?",
  [1139165182414336] = "Organização interna... que organização secreta poderia ser?",
  [1139165182414080] = "Essa jovem deveria ser Selina.",
  [1139165182413824] = "Claro, mas preciso observar o seu progresso no aprendizado antes de decidir se devo recomendá-lo para ingressar em nossa organização interna.",
  [1139165182413568] = "Eu também quero aprender Mirror Adivinhação .",
  [1139165182413312] = "Deixe o resto da investigação conosco. Você descansa no Blackthorn Hall e eu o notificarei assim que houver resultados da investigação.",
  [1139165182413056] = "Quando encontrei Haines no Clube Adivinhação ontem de manhã, seu cartão de visita tinha seu endereço.",
  [1139165182412800] = "Hum. Depois de encontrar sua residência, irei guiá-lo remotamente para entrar em um sonho. O sonho apresentará pistas mais relevantes.",
  [1139165182412544] = "Acho que é necessário iniciar uma investigação sobre Haines.",
  [1139165182412288] = "Quanto a esse adivinho chamado Haines, ele provavelmente é membro de alguma <P_Yellow> organização secreta </>.",
  [1139165182412032] = "Você lidou bem com isso, realizando o ritual interrompido antes que o espírito maligno pudesse possuí-la completamente.",
  [1139165182411776] = "Diga-me a situação específica.",
  [1139165182411520] = "Capitão, acabei de encontrar um evento extraordinário.",
  [1139165182411264] = "É tão tarde, ainda pensando no trabalho? Tenha cuidado no caminho.",
  [1139165182411008] = "Eu não esperava que você fosse um especialista em pôquer. Certo, preciso voltar para a empresa, tenho alguns assuntos urgentes para tratar.",
  [1139165182410752] = "Klein, ganhei 2 soli e 8 centavos.",
  [1139165182410496] = "Vou deixar Selina para você cuidar. Tenho algo para fazer, preciso sair um pouco.",
  [1139165182410240] = "<P_Heart> (Será que uma organização secreta está envolvida por trás do caso... é necessário reportar ao Capitão.) </>",
  [1139165182409984] = "<P_Heart> (Criador? Verdadeiro Criador? Muitas organizações secretas realmente reverenciam esta existência antiga.) </>",
  [1139165182409728] = "Deixe-me pensar... parece haver palavras como <P_Yellow> \"Wander\", \"Spirit\", \"Creator\", \"Attendant\" </> .",
  [1139165182409472] = "Haines Vincent do Clube Adivinhação?! Ele ainda está ensinando negros adivinhação em particular... A propósito, você ouviu Selena entoar algum encantamento?",
  [1139165182409216] = "Selena mencionou que seu professor de ocultismo é <P_Yellow> Haines Vincent </>.",
  [1139165182408960] = "Ela pode dormir profundamente por alguns minutos, mas não há outros problemas. No entanto, seu professor de ocultismo não é confiável; ele nem mesmo contou a ela os tabus básicos.",
  [1139165182408704] = "Corrigi o erro no espelho dela Adivinhação , o assunto está resolvido.",
  [1139165182408448] = "C-como é?",
  [1139165182407936] = "Estou animado, certo, animado.",
  [1139165182407680] = "Tenho a sensação de que você está com muito medo, por quê?",
  [1139165182407424] = "Entre primeiro na sala e depois conversaremos.",
  [1139165182407168] = "Elizabeth, você disse que havia um presente surpresa nesta sala?",
  [1139165182406912] = "Não fique nervoso, contanto que você faça o que eu digo, não haverá nenhum perigo. Além disso, lembre-se, não perturbe as outras senhoras lá dentro.",
  [1139165182406656] = "Em cinco minutos, leve Selena para a sala do outro lado do corredor e eu corrigirei seu ritual errôneo.",
  [1139165182406400] = "A sala do outro lado do corredor.",
  [1139165182406144] = "Você sabe em qual sala o <P_Yellow> item místico </> da Selena está?",
  [1139165182405888] = "O-o que eu preciso fazer?",
  [1139165182405632] = "Eu sei que é difícil acreditar só com palavras, você entenderá quando entrar e ver o espelho mágico de Selina. Se você quiser salvar seu amigo, você precisa fazer uma coisa por mim.",
  [1139165182405120] = "Ouça-me, o espelho da Selena Adivinhação deu errado.",
  [1139165182404864] = "Por que você pergunta? Aconteceu alguma coisa?",
  [1139165182404608] = "Elizabeth, deixe-me fazer uma pergunta primeiro. Se sua amiga estivesse com problemas, você gostaria de salvá-la?",
  [1139165182404352] = "Oh, tudo bem!",
  [1139165182404096] = "Melissa, o que você está pensando? Elizabeth é uma entusiasta do ocultismo, quero discutir a questão da antiga língua Fusac com ela.",
  [1139165182403840] = "Klein, você não gostaria... ela só tem dezesseis anos.",
  [1139165182403584] = "Elizabeth, tenho algumas coisas que quero discutir com você, você pode sair comigo?",
  [1139165182403328] = "<P_Heart> (Certo, Elizabeth é uma entusiasta do ocultismo, ela deveria ser capaz de ajudar.) </>",
  [1139165182403072] = "<P_Heart> (Um ritual interrompido requer uma sala separada e itens ocultos. Parece que preciso de um ajudante...) </>",
  [1139165182402816] = "<P_Heart> (Selena provavelmente está orando para uma existência maligna. Se isso continuar, ela se transformará em um espírito maligno e todos os presentes estarão em perigo... É melhor realizar um ritual interrompido imediatamente.) </>",
  [1139165182402304] = "<P_Heart> (Verifique primeiro a condição de Selina, geralmente o espelho mágico refletirá seu estado atual.) </>",
  [1139165182402048] = "<P_Heart> (Relate para o Vigias Noturnos ... espere, leva 30 minutos para ir e voltar de Blackthorn, e se as coisas piorarem...) </>",
  [1139165182401792] = "<P_Heart> (Próximo...) </>",
  [1139165182401536] = "<P_Heart> (Irmã, você realmente precisa escolher o Espelho mais perigoso Adivinhação?) </>",
  [1139165182401280] = "Estamos jogando Mirror Adivinhação, Selena sabe muito.",
  [1139165182401024] = "O que você está jogando?",
  [1139165182400768] = "Calma, Klein. Melissa ainda está lá dentro, não posso agir precipitadamente. Deixe-me bater primeiro na porta para entender a situação lá dentro.",
  [1139165182400512] = "O pêndulo está girando no sentido horário... há perigo causado por <P_Yellow> fatores extraordinários </> na sala!",
  [1139165182400256] = "Somos uma pessoa curta para lutar contra o mal, Klein, quer participar?",
  [1139165182400000] = "<P_Heart> (A expressão de Selena está um pouco errada, deixe-me verificar com Visão Espiritual .) </>",
  [1139165182399744] = "Klein, vamos passear pela festa. Dê às meninas algum espaço próprio.",
  [1139165182399488] = "Como um entusiasta do ocultismo, é claro que tenho que tentar.",
  [1139165182399232] = "A propósito, Elizabeth, Melissa, recentemente aprendi um <P_Yellow> novo adivinhação </> com um professor, vocês querem vir até minha sala e experimentar?",
  [1139165182398976] = "Talvez seja porque estive ocupado me preparando para a festa de aniversário recentemente.",
  [1139165182398720] = "Selina, sua pele parece um pouco pálida, você está bem?",
  [1139165182398464] = "Obrigado por terem vindo, espero que todos tenham uma noite agradável.",
  [1139165182397952] = "Feliz aniversário, Selina. Esses dois são meus irmãos, Benson e Klein.",
  [1139165182397696] = "Tudo bem, devemos partir.",
  [1139165182397440] = "Benson, você fica muito bem nisso também.",
  [1139165182397184] = "Estou pronto. Nada mal, Melissa, esse vestido combina muito com você.",
  [1139165182396928] = "No entanto, você está ótimo agora, realmente ótimo.",
  [1139165182396672] = "Talvez seja porque tenho um bom emprego e uma renda decente, então me tornei mais confiante.",
  [1139165182396416] = "<P_Heart> (Diferente? Melissa descobriu alguma coisa? Embora eu tenha aceitado as memórias do proprietário original, posso acidentalmente revelar minha verdadeira personalidade nos detalhes... Só consigo encontrar uma desculpa.) </>",
  [1139165182396160] = "Klein, você se tornou um pouco diferente.",
  [1139165182395904] = "Na verdade, não era caro, porque no início era apenas um produto semiacabado. Imitei os artefatos que tinha visto antes e gravei neles um encantamento de bênção e lindos padrões.",
  [1139165182395648] = "Quanto?",
  [1139165182395392] = "Tudo bem, preparei um para você.",
  [1139165182395136] = "Como senhora, ainda falta um colar para acentuar isso.",
  [1139165182394880] = "Como é?",
  [1139165182394624] = "Estou de folga hoje, vou voltar para o meu quarto e descansar um pouco.",
  [1139165182394368] = "<P_Heart> (Ainda falta algum tempo antes das três horas, talvez eu possa entrar acima da névoa cinzenta mais cedo. Aproveite esta oportunidade para explorar aquele lugar adequadamente!) </>",
  [1139165182394112] = "Melissa, por acaso estou saindo, vou levá-la à loja de departamentos no caminho. Klein, e você?",
  [1139165182393856] = "Tudo bem.",
  [1139165182393600] = "Não me diga que você quer usar um vestido velho na festa de dezesseis anos do seu colega?",
  [1139165182393088] = "Benson e eu somos quase do mesmo tamanho, ele pode usar meu smoking. Melissa, você deveria comprar um vestido novo. Se você não procura tecidos caros ou designs mais recentes, não será muito caro.",
  [1139165182392832] = "<P_Heart> (Eu estava planejando ir para casa primeiro para replanejar minhas despesas e economizar dinheiro para a taxa anual do Adivinhação Clube. Agora, estou cada vez mais longe de economizar 5 libras. Esqueça, a família é mais importante.) </>",
  [1139165182392576] = "<P_Heart> (Tenho um smoking que posso dar para Benson e para Melissa... bem, compre um vestido novo.) </>",
  [1139165182392320] = "Eu... eu não preciso... Quero primeiro conseguir uma promoção e um aumento, para que possamos viver uma vida melhor.",
  [1139165182392064] = "Você sabe, haverá muitas jovens e mulheres notáveis ​​​​comparecendo a esse tipo de festa de aniversário.",
  [1139165182391808] = "Não é meu aniversário. Acho melhor economizar dinheiro ou preparar primeiro um set para Benson.",
  [1139165182391552] = "Estou bem com isso. Mas devíamos preparar um vestido novo para a Melissa.",
  [1139165182391296] = "Sim, ela e Elizabeth são entusiastas do ocultismo. A propósito, você está livre amanhã à noite?",
  [1139165182391040] = "<P_Heart> (Nada de extraordinário deve acontecer, certo?) </>",
  [1139165182390784] = "<P_Yellow> Adivinhação </> ... Ela é uma entusiasta do ocultismo?",
  [1139165182390528] = "Deve ser de <P_Yellow> Selena </> . Ela disse que queria convidar nossa família para um jantar e também disse que aprendeu um novo adivinhação para me mostrar.",
  [1139165182390272] = "Melissa, o carteiro acabou de entregar um convite de aniversário.",
  [1139165182390016] = "Você está de volta, Klein.",
  [1139165182389760] = "Uma carta-convite?",
  [1139165182389504] = "Sr. Moretti, há uma <P_Yellow> carta-convite </> endereçada ao senhor.",
  [1139165182389248] = "Que pena. Parece que teremos que esperar até a próxima para conversar.",
  [1139165182388992] = "Ahem, de repente me lembrei que tenho outros assuntos para tratar mais tarde.",
  [1139165182388736] = "Você é realmente um cavalheiro prudente. Aguardo com expectativa o nosso próximo encontro.",
  [1139165182388480] = "Parece muito bom, mas preciso ir para casa e pensar bem antes de tomar uma decisão.",
  [1139165182388224] = "<P_Heart> (Parece ótimo, mas não tenho dinheiro... Só posso ir para casa primeiro e replanejar minhas despesas familiares.) </>",
  [1139165182387968] = "Além disso, depois de ingressar no clube, você pode fornecer serviços pagos adivinhação aos clientes, e cobramos apenas uma pequena porcentagem como taxa. Mais importante ainda, você pode encontrar um grupo de amigos com os mesmos interesses.",
  [1139165182387712] = "Bem, os membros podem usar as adivinhação salas e ferramentas gratuitamente e desfrutar de nosso café e chá gratuitamente.",
  [1139165182387456] = "<P_Heart> (5 libras?! São quase duas semanas do meu salário... e acabei de me mudar recentemente; depois de pagar o aluguel, tenho menos de 2 libras restantes.) </>",
  [1139165182387200] = "Você precisa preencher informações detalhadas e pagar a taxa anual de adesão. São 5 libras pela primeira vez e 1 libra todos os anos depois disso.",
  [1139165182386944] = "Há algum requisito para aderir?",
  [1139165182386688] = "Sr. Moretti, você está aqui para um adivinhação , ou para se juntar ao nosso clube?",
  [1139165182386432] = "Sr. Moretti, por favor sente-se e vamos conversar.",
  [1139165182386176] = "Olá, meu nome é Klein Moretti.",
  [1139165182385920] = "Sempre feliz em poder servir. Este é o meu cartão de visita.",
  [1139165182385664] = "Este é Haines Vincent, nosso adivinho mais famoso daqui.",
  [1139165182385408] = "Boa tarde, meu nome é Angélica, recepcionista do Clube Adivinhação.",
  [1139165182385152] = "A maioria das pessoas só rezam para as Igrejas Ortodoxas... mesmo que não recebam uma revelação, não deveria haver nenhum perigo.",
  [1139165182384896] = "Após o banho, certifique-se de que as cortinas estejam totalmente fechadas, coloque uma vela em frente ao espelho e ore piedosamente ao Deus em que você acredita...",
  [1139165182384640] = "Precisamos limpar o espelho com cuidado. Deve ser um espelho folheado a prata, e deve ser colocado em casa em uma posição que simbolize a lua...",
  [1139165182384384] = "Em relação a isso, acho que a <P_Yellow> Angélica </> é mais profissional do que eu.",
  [1139165182384128] = "Gostaria de saber sobre o Clube Adivinhação.",
  [1139165182383872] = "Senhor, há algo que eu possa fazer por você?",
  [1139165182383616] = "Temos um novo convidado. Parece que nossa classe Mirror Adivinhação terá que ser colocada em espera.",
  [1139165182383360] = "Desculpe, com licença.",
  [1139165182383104] = "Eu lembro, este não é um método seguro adivinhação. Ao pedir a uma existência desconhecida que forneça uma resposta direta, o adivinho é facilmente corroído pelas forças do mal.",
  [1139165182382848] = "Ele está ensinando <P_Yellow> Espelho Adivinhação </> ...",
  [1139165182382592] = "O espelho é uma porta de entrada para o desconhecido, para o mundo de espiritualidade ...",
  [1139165182382336] = "Não, não é explorar, é atuar!",
  [1139165182382080] = "Foi isso que o Imperador Roselle quis dizer com atuação? Talvez eu possa tentar; não fará mal nenhum de qualquer maneira.",
  [1139165182381824] = "Atuando... então eu deveria <P_Yellow> agir </> como um \"Vidente\" para ajudar na digestão da poção?",
  [1139165182381568] = "Portanto, a chave para digerir a poção é—",
  [1139165182381312] = "Certo, o manuscrito do Imperador Roselle mencionou a chave para digerir poções…",
  [1139165182381056] = "O Clube <P_Yellow> Vidente </>...",
  [1139165182380800] = "Devo digerir a poção do Vidente e alcançar o avanço o mais rápido possível para lidar com as crises subsequentes.",
  [1139165182380544] = "O caso do Caderno da Família Antigonus chegou a um fim temporário, mas a verdade por trás da minha transmigração, a Cordilheira Hornacis e outros mistérios permanecem sem solução...",
  [1139165182380288] = "Tudo bem. Está um dia tão lindo hoje, e amanhã também estará. Viverei bem, levando também a parte de Ray.",
  [1139165182380032] = "Desculpe atrapalhar seu trabalho.",
  [1139165182379776] = "<P_Heart> (Um grito do lado de fora da porta) </> Alice, a nova remessa chegou, saia e dê uma olhada.",
  [1139165182379520] = "Sim, é realmente uma loja muito bonita.",
  [1139165182379264] = "Certa vez, meu noivo e eu sonhamos em abrir nossa própria joalheria. Olha, eu consegui. Minha loja não é linda?",
  [1139165182379008] = "Estou bem, não se preocupe. Muitas pessoas morreram, mas aqueles que estão vivos devem continuar a viver.",
  [1130504917104896] = "Animação",
  [1139165182378496] = "Não, isto... é uma lembrança do meu noivo.",
  [1139165182378240] = "...A propósito, você parece estar usando uma aliança de casamento? Você está casado agora?",
  [1139165182377984] = "Ah, nada de especial. Eu estava de passagem, então vim dar uma olhada.",
  [1139165182377728] = "Hum, volte e descanse. Deixe isso conosco.",
  [1139165182377216] = "Se você encontrar situações semelhantes no futuro, nunca as ignore; eles podem ser itens muito importantes.",
  [1139165182376960] = "Dessa forma, uma determinada parte do seu corpo pode ter concentrado Beyonder características, tornando-se um material de maior qualidade.",
  [1139165182376704] = "Um item contendo poder mágico. Riel Bieber enlouqueceu e perdeu o controle, virando um monstro, o que significa que não absorveu totalmente o poder Beyonder fornecido pelo notebook.",
  [1139165182375424] = "Vamos para casa primeiro, tente relaxar...",
  [1139165182375168] = "O que é esse símbolo estranho... Não entendi, há muitas coisas que não entendo...",
  [1139165182374912] = "Essas coisas vermelhas são... estrelas?",
  [1139165182374656] = "Onde é isso... por que me tornei assim? Esse ritual realmente foi estranho!",
  [1139165182374144] = "Apresentação de circo? Melissa deveria gostar... Será que quanto custam os ingressos?",
  [1139165182373888] = "Uma espetacular apresentação de circo, somente esta noite! Venha ver o espetáculo de circo mais incrível!",
  [1139165182373376] = "Tudo bem. Adeus, mentor, Sr. Azik.",
  [1139165182373120] = "Klein, se precisar de alguma coisa, lembre-se de nos escrever. O endereço ainda é o escritório do Departamento de História da Hoy University.",
  [1139165182372864] = "A reunião está prestes a começar, Azik. Não podemos demorar mais.",
  [1139165182372608] = "Sinto tristeza e arrependimento pelo que aconteceu com Welch e os outros...",
  [1139165182372352] = "<P_Heart> (O Sr. Azik também não sabe.) </>",
  [1139165182372096] = "Não tenho nenhuma impressão disso, talvez...",
  [1139165182371840] = "Você já ouviu falar desse caderno?",
  [1139165182371584] = "Antígono...",
  [1139165182371328] = "O nome desse caderno é - o <P_Yellow> Caderno da Família Antigonus </>.",
  [1139165182371072] = "Fui algumas vezes, mas depois fiquei ocupado com o trabalho e parei de ir. A polícia também veio me investigar ontem.",
  [1139165182370816] = "Há algum tempo, Welch obteve um caderno da Quarta Época e me pediu para ajudá-lo a decifrá-lo.",
  [1139165182370560] = "<P_Heart> (Tais eventos realmente não deveriam ser conhecidos pelos cidadãos comuns, mas me pergunto se os professores já ouviram falar desse caderno?) </>",
  [1139165182370304] = "Também não conheço muito bem os detalhes específicos.",
  [1139165182370048] = "Azik, por que você ainda não entrou?",
  [1139165182369792] = "Todo mundo tem suas próprias escolhas. Estou satisfeito que você tenha se lembrado de vir à universidade para avisá-los, em vez de simplesmente faltar.",
  [1139165182369536] = "<P_Heart> (Não posso dizer exatamente que estive envolvido em acontecimentos estranhos e tive que aceitar este emprego para salvar minha vida...) </>",
  [1139165182369280] = "Você sabe, gosto de explorar a história, não de resumi-la.",
  [1139165182369024] = "É... uma empresa que cuida da busca, coleta e segurança de antiguidades. Eles precisam de consultores profissionais.",
  [1139165182368768] = "Azik e eu estamos aqui para participar de uma reunião. Que tipo de trabalho você encontrou?",
  [1139165182368512] = "<P_Heart> (Meu mentor, Sr. Quentin Cohen, espero que ele não me culpe por cancelar repentinamente a entrevista.) </>",
  [1139165182368256] = "Mentor, por que você está aqui?",
  [1139165182368000] = "Moretti, você encontrou outro emprego?",
  [1139165182367744] = "Parabéns. Você é realmente um jovem educado. Informarei o professor e os professores associados seniores.",
  [1139165182367488] = "É assim mesmo...",
  [1139165182367232] = "Já encontrei um emprego, por isso estou aqui para cancelar a entrevista de hoje.",
  [1139165182366976] = "Lembro-me de você, vi sua carta de recomendação. Mas há algo acontecendo? Não sou responsável pelas entrevistas.",
  [1139165182366720] = "Olá, sou Klein Moretti, aluno do Professor Associado Sênior Cohen da Hoy University.",
  [1139165182366464] = "Isso é ótimo. Se meu filho pudesse ser como você e ter um emprego adequado e decente, eu acordaria sorrindo nos meus sonhos...",
  [1139165182366208] = "A entrevista de hoje é no <P_Yellow> Escritório Administrativo </> . Basta seguir a estrada principal e você estará lá.",
  [1139165182365952] = "É realmente uma pena.",
  [1139165182365696] = "Você quer cancelar? Que grande oportunidade, que pena!",
  [1139165182365440] = "Já consegui outro emprego, por isso estou aqui para cancelar a entrevista de hoje.",
  [1139165182365184] = "Você está aqui para a entrevista?",
  [1139165182364928] = "Olá, posso perguntar onde devo ir para a entrevista de hoje com o professor universitário?",
  [1139165182364672] = "Agora tenho dinheiro, vou de carruagem!",
  [1139165182364416] = "Mas primeiro preciso <P_Yellow> cancelar minha entrevista na Universidade de Tingen </>. Afinal, foi uma oportunidade apresentada pelo meu mentor, por isso é educado ir cumprimentá-lo.",
  [1139165182364160] = "E eles até me adiantaram uma quantia tão grande de dinheiro... Devo presentear Melissa e os outros com uma boa refeição!",
  [1139165182363904] = "É muito bom; os benefícios são generosos e os colegas parecem muito amigáveis.",
  [1139165182363648] = "Melhor ir fazer um trabalho de verdade.",
  [1139165182363392] = "...Meu destino foi adivinhado por um Domador de Bestas?",
  [1139165182363136] = "Não se preocupe, eu simplesmente gosto disso, mas minhas adivinhações e interpretações às vezes são muito precisas, realmente...",
  [1139165182362880] = "Volte! Você é apenas um domador de animais!",
  [1139165182362624] = "Por que você está fingindo ser eu de novo! Fazer adivinhações é meu trabalho!",
  [1139165182362112] = "Você terá um status nobre, estará cercado de amor e suas perspectivas para ter filhos deverão ser muito boas.",
  [1139165182361856] = "A Imperatriz em pé, significando \"Colheita\".",
  [1139165182361600] = "Você pode tirar outra carta do Tarô para adivinhar como resolver a crise.",
  [1139165182361344] = "No entanto, como o desastre é inevitável, só depois do colapso da torre poderá haver esperança de reconstrução.",
  [1139165182361088] = "...Torre... Você parece estar prestes a enfrentar uma grande crise, por favor, tome cuidado.",
  [1139165182360832] = "Estranho, esta carta não está no baralho de Tarô. Talvez alguém tenha misturado outras cartas. Podemos sortear outro mais tarde...",
  [1139165182360576] = "Peguei o cartão errado? O que está acontecendo com este cartão?",
  [1139165182360320] = "Eh? Estranho...",
  [1139165182360064] = "Parece que você está prestes a embarcar em uma nova jornada, hehe.",
  [1139165182359808] = "O Louco... o início de todas as possibilidades, a coleção de todas as incógnitas, o ponto de partida de todas as jornadas.",
  [1139165182359552] = "Qual cartão você deseja ver?",
  [1139165182359296] = "Tudo bem, por favor compre três cartas deles.",
  [1139165182359040] = "O passado, o presente e o futuro.",
  [1139165182358784] = "Você embaralha e corta as cartas. O que você quer adivinhar?",
  [1139165182358528] = "Minha transmigração provavelmente foi devido ao Ritual de Virada de Fortuna... independentemente disso, tenho que tentar!",
  [1139165182358272] = "...Mas desculpe, eu realmente quero ir para casa.",
  [1139165182358016] = "A maneira como Melissa olhou para mim agora há pouco... era como se ela estivesse com pena de seu irmão com problemas mentais.",
  [1139165182357760] = "Eu realmente vou me atrasar! Vejo você hoje à noite, Klein!",
  [1139165182357504] = "Você vai ao mercado hoje para comprar alguns ingredientes e também precisa comprar pão de centeio da Sra.",
  [1139165182357248] = "Benson escreveu dizendo que logo estará de volta a Tingen. Precisamos preparar alguma comida com antecedência.",
  [1139165182356992] = "Quase esqueci!",
  [1139165182356736] = "Eu vou me atrasar!",
  [1139165182356480] = "E nem você nem Benson são casados ​​ainda. Cada centavo das despesas da família deve ser planejado cuidadosamente.",
  [1139165182356224] = "Tudo bem, tudo bem, Melissa. Já compreendi seu excelente talento matemático.",
  [1139165182355968] = "O aluguel semanal do apartamento Frankie é de apenas 5 soli e 6 pence, e o salário semanal de Benson é de apenas 1 libra e 10 soli. Precisamos economizar!",
  [1139165182355712] = "Uma viagem de carruagem só de ida custa 4 centavos e uma viagem de ida e volta custa 8 centavos. Se você e Benson pegassem a carruagem, custaria 24 centavos por dia – são 2 soli! Excluindo domingos, são 12 soli por semana!",
  [1139165182355456] = "Quase uma hora? Por que não pegar uma carruagem?",
  [1139165182355200] = "Demora cinquenta minutos para caminhar até a escola e preciso chegar cedo para ver minhas aulas.",
  [1139165182354944] = "Saindo tão cedo?",
  [1139165182354688] = "Não há realmente nada! Eu estou indo para a escola!",
  [1139165182354432] = "Secreto e sorrateiro, deve haver algo suspeito acontecendo.",
  [1139165182354176] = "Você tem que agradecer à revogação das Leis do Milho por isso, e àqueles que marcharam.",
  [1139165182353920] = "Apenas 9 centavos? Foram 11 centavos há dois dias. O preço do pão caiu?",
  [1139165182353664] = "Rezo por seu favor, rezo para que me conceda permissão e bênçãos para entrar na névoa da história...",
  [1139165182353152] = "Quando estiver pronto, retire aquela pedra de cristal; ele registra uma parte do poder do mestre.",
  [1139165182352896] = "Se você estiver pronto, retire aquela pedra de cristal; ele registra uma parte do poder do mestre.",
  [1139165182352640] = "É a vez de Arrodes fazer uma pergunta. Você está pronto?",
  [1139165182352384] = "Retire o Cristal Cocoon de Bênção dado a você pelo grande mestre, ore ao grande mestre e implore por permissão para entrar na névoa da história.",
  [1139165182352128] = "Como devo entrar novamente na névoa da história?",
  [1139165182351360] = "Mas uma coisa é certa: não posso voltar por enquanto.",
  [1139165182351104] = "Voltar? Parecia ter um sonho. O que diabos era aquele mundo de névoa cinzenta...",
  [1139165182350848] = "<P_Heart> (Quem exatamente é o Sr. Tolo, um deus tão majestoso e gentil... mas, não se pode olhar diretamente para um deus, não se pode questionar um deus.) </>",
  [1139165182350592] = "Você é realmente um cavalheiro generoso e uma existência nobre.",
  [1139165182350336] = "Era exatamente isso que eu esperava... Depois disso, todas as segundas-feiras, às três da tarde, irei convocá-los regularmente aqui para reuniões.",
  [1139165182350080] = "Embora ainda estejamos fracos, temos os nossos próprios recursos e conexões. Talvez um dia também possamos ajudá-lo a lidar com alguns pequenos assuntos.",
  [1139165182349824] = "Mas tal reunião é verdadeiramente interessante e significativa. Você estaria disposto a permitir que continuemos nos comunicando aqui no futuro?",
  [1139165182349568] = "Respeitado Sr. Tolo, seu poder excede minha imaginação. Atualmente, não tenho outros pedidos.",
  [1139165182349312] = "<P_Heart> (Também não sei se a fórmula ou os materiais são reais. Porém, parece que preciso me tornar um Beyonder o mais rápido possível...) </>",
  [1139165182349056] = "Confio plenamente na justiça e no poder do Sr. Louco. Vou procurar o sangue do Tubarão Fantasma.",
  [1139165182348800] = "Heh, talvez você realmente não tenha percebido o significado desta reunião... Sob o olhar do Sr. Louco, nenhum de nós ousaria mentir ou quebrar um acordo.",
  [83769847451136] = "O Louco que não pertence a esta época, o misterioso governante acima da névoa cinzenta, o Rei do Amarelo e do Preto que exerce a boa sorte.",
  [1139165182348544] = "Se eu conseguir, como devo dar a você? E como posso garantir a autenticidade da fórmula?",
  [1139165182348288] = "Sangue de Tubarão Fantasma, pelo menos 100 mililitros.",
  [1139165182348032] = "Ótimo! Então o que devo usar para trocar pela fórmula?",
  [1139165182347776] = "<P_Heart> (Sequência 9? Fórmula da poção?) </>",
  [1139165182347520] = "...Eu tenho duas fórmulas de Sequência 9 poções em mãos, \"Sailor\" e \"Spectator\".",
  [1139165182347264] = "<P_Heart> ( Vigias Noturnos ... O Sr. Dunn mencionou que pertence ao esquadrão Tingen Vigias Noturnos.) </>",
  [1139165182347008] = "Eu sei, mas me tornar um Vigia Noturno , Mandated Punisher ou Machine Hivemind significa perder minha liberdade... Não há outro jeito?",
  [1139165182346752] = "Você é um Loenese, certo? Você pode ingressar na Igreja da Deusa da Noite Eterna, na Igreja do Senhor das Tempestades ou na Igreja do Deus do Vapor e das Máquinas para ter a oportunidade de se tornar um Beyonder.",
  [1139165182346496] = "... <P_Heart> (Um Beyonder como o Sr. Dunn? Não, não sou, e também quero saber.) </>",
  [1139165182346240] = "Ufa, isso é incrível, e então... posso perguntar o que devo fazer para me tornar um Beyonder , assim como você?",
  [1139165182345984] = "A seguir, nós...",
  [1139165182345728] = "“O Enforcado”.",
  [1139165182345472] = "\"Justiça\".",
  [1139165182345216] = "Muito bom, vamos começar, a primeira reunião do Clube do Tarô .",
  [1139165182344960] = "<P_Heart> (O que é isso, 'Transmigração: sou um Chefe em uma organização secreta'?) </>",
  [1139165182344704] = "<P_Heart> (Esta senhora é realmente pró-ativa. Participar de uma organização secreta tem seus prós e contras... mas talvez eu possa encontrar pistas para voltar para casa depois disso.) </>",
  [1139165182344448] = "Então nós somos o Clube do Tarô , e esta é a primeira reunião do Clube do Tarô . Não há problema, Sr. Tolo?",
  [1139165182344192] = "Eu escolho... 'O Enforcado'.",
  [1139165182343936] = "<P_Heart> (Não posso recusar, então vou seguir o fluxo e aderir. Pode haver riscos, mas também é uma oportunidade!) </>",
  [1139165182343680] = "<P_Heart> (Ainda não concordei em me juntar... mas uma existência tão grande não consideraria nossos desejos, e Justice parece uma nobre dama que foi muito bem protegida.) </>",
  [1139165182343424] = "Meu codinome é – Justiça!",
  [1139165182343168] = "Como organização secreta, nossos títulos devem ser consistentes, e o nome do Sr. Louco vem das cartas do Tarô... Está decidido!",
  [1139165182342912] = "Essa reunião secreta é exatamente o tipo de evento que imaginei inúmeras vezes. Para se dirigirem uns aos outros por codinomes em uma organização tão misteriosa e trocarem histórias lendárias!",
  [1139165182342656] = "<P_Heart> (Boa ideia. Não posso continuar chamando você de 'senhor' e 'senhora'.) </>",
  [1139165182342400] = "O Louco, isso é ótimo... Quer dizer, talvez devêssemos também nos dar codinomes por conveniência?",
  [1139165182342144] = "O Louco... <P_Heart> (Um título do qual nunca ouvi falar, mas parece implicar segredos e poder aterrorizantes... Não posso investigar mais, é muito perigoso!) </>",
  [1139165182341888] = "O tolo.",
  [1139165182341632] = "Alguns já me chamaram assim antes. Você pode me ligar—",
  [1139165182341376] = "<P_Heart> (Em uma reunião tão secreta, não posso usar meu nome verdadeiro... Certo.) </>",
  [1139165182341120] = "<P_Heart> (Ele fica em silêncio, poderia ser... não, não teste... um deus?) </>",
  [1139165182340864] = "Excelência, como devemos nos dirigir a você?",
  [1139165182340608] = "<P_Heart> (A mudança aqui agora mesmo! Que poder aterrorizante! Este é o Seu reino... um Reino Divino? Ele deve ser uma existência como um deus! Qual ser desconhecido desceu, ou é uma grande existência despertando do segredo?) </>",
  [1139165182340352] = "...Esta também é uma honra, obrigado pelo convite.",
  [1139165182340096] = "Um convite? Esse espelho realmente... Excelência, seu reino é tão magnífico e grandioso; Sempre desejei testemunhar tal milagre.",
  [1139165182339840] = "Este é o meu reino. Bem-vindos, convidados que foram convidados. <P_Heart> (Eles parecem ter sido trazidos aqui pelas estrelas vermelhas agora há pouco... bem, vamos apenas dizer isso!) </>",
  [1139165182339584] = "<P_Heart> (Boa noite... Melissa... Benson...) </>",
  [1139165182339328] = "<P_Heart> (Durma... amanhã... amanhã...) </>",
  [1139165182339072] = "A vida está melhorando lentamente, é ótimo.",
  [1139165182338816] = "Depois que eu começar a trabalhar, a situação financeira da família vai melhorar e posso pensar em me mudar.",
  [1139165182338560] = "Esta noite foi tão feliz. Benson voltou para casa e Melissa também parecia muito feliz.",
  [1139165182338304] = "Um pouco animado, mas também um pouco assustado...",
  [1139165182338048] = "O Capitão disse que somos guardiões, mas também um grupo de pobres coitados que lutam constantemente contra o perigo e a loucura.",
  [1139165182337536] = "Tornei-me um Vidente e também possuo algumas habilidades mágicas, que agora podem desempenhar um certo papel nas missões.",
  [1139165182337280] = "Contanto que seja recuperado, esse assunto acabou.",
  [1139165182337024] = "Tudo isso decorre deste caderno, embora eu esteja um pouco curioso para saber por que... esqueça, a curiosidade matou o gato.",
  [1068726107532544] = "EU",
  [1139165182336768] = "O caderno da Família Antigonus foi finalmente recuperado e levado pelo Capitão para ser lacrado.",
  [1139165182336512] = "Após a transição de funcionário civil para Vigia Noturno , meu salário também deverá aumentar.",
  [1139165182336256] = "O capitão Dunn pode ter péssima memória, mas é muito confiável e todos na empresa são boas pessoas... mesmo que Leonard sempre fale de maneira estranha.",
  [1139165182336000] = "Eu, Klein Moretti, agora sou um oficial Vigia Noturno . Tenho muito para entender e aprender.",
  [1139165182335744] = "Beyonder incidentes são realmente aterrorizantes... mas somente me tornando mais forte poderei ter a habilidade de lidar com tais eventos e evitar que mais pessoas se machuquem.",
  [1139165182335488] = "Mas Welch, Naya, Ray Bieber e sua mãe morreram por causa do incidente do caderno, e Alice também perdeu seu amante...",
  [1139165182335232] = "O assunto chegou ao fim. O capitão disse para não me preocupar com qualquer influência ou perigo subsequente e que posso ter uma boa noite de sono.",
  [1139165182333696] = "Além disso, Beyonder incidentes são realmente aterrorizantes... mas somente me tornando mais forte poderei ter a habilidade de lidar com o perigo e evitar que mais pessoas se machuquem.",
  [1139165182333440] = "Essa sensação não é ruim, embora eu tenha ouvido algumas vozes estranhas e visto algumas coisas estranhas...",
  [1139165182333184] = "Tornei-me um Vidente e também possuo algumas habilidades mágicas, que podem desempenhar um certo papel nas missões.",
  [1033542272291584] = "Recusar",
  [1033542272308992] = "Beber café",
  [1139165182332928] = "Eu, Klein Moretti, agora sou um oficial Vigia Noturno . Mas ainda há muito para entender e aprender.",
  [1139165182332672] = "A questão do caderno chegou ao fim. O capitão disse para não me preocupar com qualquer influência ou perigo subsequente e que posso ter uma boa noite de sono.",
  [1139165182332416] = "<P_Heart> (Tantas coisas aconteceram em apenas alguns dias...) </>",
  [1139165182332160] = "Vá em frente então. O tempo gasto com a família é precioso. Não importa o quão ocupado você esteja, lembre-se de voltar para casa mais cedo.",
  [1139165182331904] = "Estou indo para casa. Benson e Melissa ainda estão esperando por mim.",
  [1139165182331648] = "Então estou aliviado. Uma boa comida sempre pode curar a tristeza.",
  [1139165182331392] = "É fantástico! Me sinto muito melhor, obrigado.",
  [1139165182331136] = "Venha, me ajude a experimentar o chá gelado doce que acabei de fazer. Não tenho certeza se combina com o gosto local.",
  [1139165182330880] = "Não importa quantos problemas existam, o amanhã acabará por chegar.",
  [1139165182330624] = "Só um pouco.",
  [1139165182330368] = "Pequeno Klein, você não parece... você não parece muito feliz?",
  [1139165182330112] = "Não... <P_Heart> (Ah, não, esqueci da mudança!) </>",
  [1139165182329856] = "Encontrei Benson esta tarde e ele disse que você estava se mudando para a rua Daffodil. Você esqueceu alguma coisa e voltou para buscá-la?",
  [1139165182329600] = "Boa noite, acabei de sair do trabalho.",
  [1139165182329344] = "Está sujo. Os sequestradores deveriam sofrer um pouco, não deveriam?",
  [1139165182329088] = "Ainda tem uma bala no ombro desse cara, não vamos fazer nada a respeito?",
  [1139165182328832] = "Se você estiver interessado, pode experimentá-los diretamente.",
  [1139165182328576] = "Estes são os nossos estilos mais vendidos, perfeitos para um cavalheiro jovem e bonito como ele. Se você comprar o conjunto inteiro, há desconto.",
  [1139165182328320] = "Olá, gostaríamos de comprar um terno formal para ele. Você tem alguma recomendação?",
  [1139165182328064] = "Bom dia, senhores. Você gostaria de comprar alguma coisa?",
  [1139165182327808] = "Talvez eu tenha uma constituição que atraia Beyonder entidades...",
  [1139165182327552] = "Não sei se é apenas minha imaginação, mas desde que você chegou, a frequência de Beyonder incidentes na área parece estar disparando.",
  [1139165182327296] = "<P_Heart> (Então terei duas roupas formais decentes!) </>",
  [1139165182327040] = "Reembolsável... <P_Heart> (Ótimo, se eu lavar e consertar isso, posso comprar outro assim que o reembolso chegar...) </>",
  [1139165182326784] = "Não se preocupe, as perdas nas missões podem ser reembolsadas.",
  [1139165182326528] = "Suspiro, este é o terno que acabei de comprar...",
  [1139165182326272] = "Olhe para você, parece que você acabou de sair de uma vala e foi atropelado por uma carruagem três ou quatro vezes.",
  [1139165182326016] = "Deusa! Como isso acabou assim?",
  [1139165182325760] = "Mas, por enquanto, você precisa ter um sono bom e profundo.",
  [1139165182325504] = "Muito bom. Assim que a Santa Catedral aprovar, você será um de nós. *Tosse, tosse.*",
  [140807013140992] = "Palhaço",
  [1139165182325248] = "Espero me tornar um oficial Vigia Noturno .",
  [1139165182324992] = "Mas sem a aprovação do esquadrão, você não pode deixar Tingen sob qualquer desculpa e precisa fazer o possível para manter isso em segredo de sua família.",
  [1139165182324736] = "Você também receberá o status de inspetor probatório, o que às vezes será muito útil.",
  [1139165182324480] = "Seu salário dobrará imediatamente para 6 libras por semana e aumentará até certo ponto a cada ano a partir de então.",
  [1139165182324224] = "Sr. Klein Moretti, você está disposto a se juntar oficialmente ao time Tingen Vigias Noturnos e se tornar um de nós?",
  [1139165182323968] = "Eliminamos o descendente descontrolado da Família Antígono e também frustramos a conspiração da Escola de Pensamento Rosa. Nesse processo você se saiu muito bem.",
  [1139165182323712] = "Quase esqueci algo muito importante.",
  [1139165182323456] = "Imediatamente retiraremos os restos mortais, os Artefatos Selados e o caderno da Família Antigonus, e faremos com que Frye, Luo Yao e a polícia venham até nós.",
  [1139165182322944] = "Leonard, você está em boas condições, então fique aqui. Não deixe nenhuma pessoa comum se aproximar...",
  [1139165182322688] = "Não tenha medo. Os incidentes e a influência do caderno terminam aqui.",
  [1139165182322176] = "é a fonte de tudo – o caderno da Família Antigonus.",
  [1139165182321664] = "Todos os inimigos foram confirmados como mortos, e isso...",
  [1139165182321408] = "Capitão, todos estão bem.",
  [1139165182320640] = "E como eu também.",
  [1139165182320384] = "Não se preocupe com isso. Há muitas pessoas especiais neste mundo que sempre conseguem fazer coisas que outros não conseguem, como você...",
  [1139165182320128] = "Talvez seja porque sou muito talentoso.",
  [1139165182319872] = "Durante a luta anterior, eu queria te ajudar mais, mas percebi que você não precisava disso.",
  [1139165182319616] = "<P_Heart> (Ele não está tão ferido quanto parece...) </>",
  [1139165182319360] = "Não há necessidade, eu mesmo posso beber. Apenas dê para mim.",
  [1139165182319104] = "Eu simplesmente tive sorte. Você precisa que eu lhe dê a poção?",
  [1139165182318848] = "Mesmo você sendo o recém-chegado, o fato de eu estar deitado enquanto você está de pé me faz parecer fraco.",
  [1139165182318592] = "Leonardo, você está bem?",
  [1139165182318336] = "Você poderia... me ajudar a beber a poção? Eu não consigo me levantar...",
  [1139165182318080] = "Isso é uma grande ajuda... Minhas mãos tremiam mais cedo... Toda a minha poção... derramada...",
  [1139165182317824] = "Sr. Hassen, você está bem? Esta é a poção que o capitão me pediu para lhe dar.",
  [1139165182317568] = "Deixe isso comigo, você vai verificar os outros.",
  [1139165182317312] = "Obrigado. Lolita desmaiou, mas seus ferimentos não são muito graves.",
  [1139165182317056] = "Há algo em que eu possa ajudar? Esta é a poção que o capitão me deu.",
  [1139165182316800] = "Bom filho.",
  [1139165182316288] = "... <P_Heart> (Não acredito em uma palavra do que ele diz, mas posso aproveitar esta oportunidade para atraí-lo.) </>",
  [1139165182316032] = "Tudo bem, tome sua decisão. Você não tem muito tempo a perder.",
  [1139165182315776] = "<P_Heart> (O Sequência 8 correspondente ao Vidente é o Palhaço?) </>",
  [1139165182315520] = "Eu costumava ser um Vidente.",
  [1139165182315264] = "Se você conseguir completar isso, eu lhe darei recompensas extras. Eu sei que você é um Vidente; a Escola de Pensamento Rose pode fornecer a fórmula Sequência 8.",
  [1139165181856000] = "Capitão... Ah, sim! Ele mencionou você. Um momento.",
  [1139165182314496] = "Acene com a cabeça se você concordar. Eu sei que você ainda pode realizar esta ação. Seus companheiros não podem ajudá-lo agora.",
  [1139165182314240] = "Vá me ajudar a pegar aquele caderno da Família Antigonus.",
  [1139165182313984] = "<P_Heart> (Onde ele está... Vou fingir que ainda estou controlado e ver o que ele realmente quer fazer.) </>",
  [1139165182313472] = "Você quer ser acordado? Contanto que você concorde com uma coisa, você pode ser libertado.",
  [822436845543680] = "Pêndulo Adivinhação",
  [1139165182312192] = "O que devo fazer? Não posso ficar aqui para sempre. O Capitão e os outros ainda estão na realidade e não sei o que aquele Palhaço fará a seguir.",
  [1139165182311936] = "Proteção da Deusa, que ela se recupere logo.",
  [1139165182311680] = "Lorota tem três hobbies principais: café, sobremesas e empregadas domésticas. Ela diz que precisa dessas três coisas para acelerar sua recuperação.",
  [1139165182311424] = "Um café? Os ferimentos da dona Lorota ainda não deveriam ter cicatrizado, certo?",
  [1139165182311168] = "Ela deveria ter ido procurar um café.",
  [822436845141760] = "Vigias Noturnos",
  [1139165182310912] = "Obrigado pelo elogio. E a Sra. Lorotta? Ela está bem?",
  [1139165182310656] = "Nesta época, há cada vez menos cavalheiros com espírito de autodepreciação. Felizmente, conhecemos outro hoje.",
  [1139165182310400] = "Seja Vidente ou Palhaço, ambos podem ser encontrados em um circo.",
  [1139165182309888] = "Não, ainda existem pontos em comum.",
  [1139165182309632] = "Sua escolha é excelente, embora seja estranho que o sucessor do Vidente seja o Palhaço... parece que os dois não têm nada a ver um com o outro.",
  [1139165182309376] = "Fingi concordar, aproveitei a oportunidade para forçá-lo a entrar no alcance da influência de 2-049 e, em seguida, atirei e matei-o.",
  [1139165182308864] = "Na época, ele pensou que eu era controlado por 2-049, então tentou me atrair me resgatando e oferecendo o Sequência 8 Palhaço da Vidente Caminho, me fazendo ir buscar o caderno Antigonus.",
  [1139165182308608] = "Foi uma sorte muito grande; aquele palhaço cometeu um erro de julgamento fatal.",
  [1139165182308352] = "<P_Heart> (Essa pergunta veio afinal...) </>",
  [1139165182308096] = "Suspeito que ele alcançou Sequência 7. Como você conseguiu isso? Eu simplesmente não consigo acreditar.",
  [1139165182307840] = "Klein, vou te chamar de Klein. Seu desempenho hoje foi excelente; você realmente conseguiu matar um membro da Rose School of Thought.",
  [1139165182307584] = "Existem alguns artefatos selados atrás do Portão Chanis, que você verá gradualmente no futuro.",
  [1139165182307328] = "\"Grau 3\" é um tanto perigoso e deve ser usado com cuidado. Deve ter pelo menos três pessoas para se inscrever. O nível de segurança é oficial Vigias Noturnos .",
  [1130369089386752] = "Aniversário?",
  [1139165182307072] = "\"Grau 2\" é perigoso, use com cautela e moderação. O nível de segurança é para bispos e Vigia Noturno capitães de equipe e superiores.",
  [1139165182306816] = "\"Grau 1\" é altamente perigoso, pode ser usado com limitações. O nível de segurança é para bispos diocesanos e Vigia Noturno diáconos e acima.",
  [1139165182306560] = "\"Grau 0\" significa extremamente perigoso, com maior prioridade e nível de segurança. Não pergunte, não divulgue, não descreva, não espie. Só pode ser selado no subsolo da catedral sede.",
  [1139165182306304] = "As principais igrejas dividiram os Artefatos Selados em quatro níveis.",
  [1139165182305280] = "Vigias Noturnos são aqueles que, em tais eventos, tentam o seu melhor para proteger Tingen uma e outra vez. Lutando contra os inimigos e também lutando contra nós mesmos.",
  [1139165182305024] = "Na verdade, sou igual, só tive mais sorte...",
  [1139165182304768] = "Ray Bieber se envolveu em um acontecimento extraordinário e morreu devido à estranheza e ao caos. Welch e Naya morreram da mesma maneira...",
  [1139165182304512] = "Ray Bieber era apenas uma pessoa comum, mas sob a tentação de um poder extraordinário, sua sanidade foi completamente engolida. Essa é uma tentação que nenhum ser humano comum pode resistir.",
  [1139165182304256] = "Eventos extraordinários são assim; o perigo e a loucura estão escondidos por trás da vida cotidiana.",
  [1139165182304000] = "Obtivemos o caderno e a Ordem Eremita não irá mais segui-lo ou prejudicá-lo.",
  [1139165182303744] = "Faça com que Frye manuseie o cadáver do Palhaço para ver se ele consegue identificar sua aparência original e encontrar pistas relevantes.",
  [1139165182303488] = "Sob a influência de um poder extraordinário, o pensamento humano é louco e caótico, mas ele pode inconscientemente pensar que a fábrica é um lugar seguro.",
  [1139165182303232] = "Ele deveria estar usando um ritual antigo para absorver o poder do caderno, assim como consumimos diretamente poções altas Sequência. Isto é cheio de perigos e requer tempo; ele precisa ficar em um lugar seguro.",
  [1139165182302976] = "Você tem mais alguma coisa que deseja perguntar?",
  [1139165182302720] = "No entanto, devo primeiro relatar este assunto à Santa Catedral. Assim que confirmarem o nível de confidencialidade do notebook, consideraremos se você pode vê-lo.",
  [1139165182302464] = "<P_Heart> (Não, de jeito nenhum...) </>",
  [1139165182302208] = "Isso o torna seguro... Klein, você deve estar cheio de curiosidade sobre o caderno da Família Antigonus e querer descobrir o que aconteceu no passado.",
  [1139165182301952] = "Sim, estou preocupado que o <P_Yellow> membro da Rose School of Thought </> não desista, tem vigiado a casa de Ray Bieber e nos seguiu até aqui, preparando-se para causar problemas no momento crítico.",
  [1139165182301696] = "Adivinhando novamente para ver se há algum perigo por perto.",
  [1139165182301184] = "Existe perigo, grande perigo!",
  [1139165182300928] = "Vamos lá, termine isso o mais rápido possível e sele novamente 2-049.",
  [1139165182300672] = "Esta é a razão pela qual precisamos manter a distância. Se não tivéssemos descoberto a anormalidade a tempo, você teria sido assimilado pelo Artefato Selado 2-049 agora há pouco.",
  [1139165182300416] = "O que aconteceu!",
  [1139165182299648] = "Al Hassen, um cara velho como eu, e o outro é Borgia.",
  [1139165182299392] = "Esta é a Sra. Lorota, uma coveira Sequência 8 e também atiradora de elite.",
  [1139165182299136] = "Eles são colegas da Diocese de Backlund, escoltando o Artefato Selado 2-049 até aqui enquanto nos apoiam na conclusão da missão.",
  [1139165182298880] = "Este é Klein Moretti, nosso recém-chegado. Ele tem uma ressonância estranha com o caderno da Família Antigonus.",
  [1139165182298624] = "Esta ação permite-nos descobrir problemas imediatamente e, desde que o resgatemos a tempo, não haverá perigo para a sua vida.",
  [1139165182298368] = "Objeto perigoso de \"grau 2\"... Perigoso, use com cautela e moderação. Então, esta ação é realizada devido à natureza especial do Artefato Selado?",
  [1139165182298112] = "Solicitamos o uso de <P_Yellow> Sealed Artifact 2-049 </> , que é um item perigoso que pertenceu à Família Antigonus. Pode nos ajudar a localizar Ray Bieber, desde que ele seja descendente desta família.",
  [1139165182297856] = "É assim... Por quê?",
  [1139165182297600] = "Lembre-se, absolutamente não pare. Isto diz respeito à sua segurança!",
  [1139165182297344] = "Acompanhe-nos e faça esse movimento imediatamente, e continue assim, absolutamente não pare!",
  [1139165182297088] = "Capitão, estou aqui... O que você está fazendo?",
  [1139165181855744] = "Olá, meu nome é Klein Moretti. O Sr. Dunn Smith me convidou para vir aqui.",
  [1139165182295808] = "Eu entendo, eu só... não sei o que fazer.",
  [1139165182295552] = "Não, não existe tal destino injusto.",
  [1139165182295296] = "É este o nosso destino destinado? Porque queremos lutar, estamos sendo punidos?",
  [1139165182295040] = "Será que pessoas como nós, que têm destinos tão amargos, estão destinadas a viver vidas tão difíceis e a apodrecer na fábrica?",
  [1139165182294784] = "...Eu só estava pensando, é porque queríamos abrir nossa própria loja e escapar de nossas vidas anteriores que sofremos esses infortúnios?",
  [1139165182294528] = "Tudo bem, obrigado pelo seu trabalho duro.",
  [1139165182294272] = "Basta chegar à nova casa depois de sair do trabalho. A localização é <P_Yellow> Rua Narciso 2 </>.",
  [1139165182294016] = "Vá em frente, a nova casa e a rescisão do aluguel estão resolvidas. Melissa e eu vamos mudar tudo para o novo local hoje.",
  [1139165182293760] = "Tenho que ir para a empresa, tem algo urgente no trabalho.",
  [1139165182293504] = "A inteligência do Sr. Franky ainda é um pouco maior que a de um babuíno de cabelos cacheados, se ele estiver em boas condições.",
  [1139165182293248] = "Benson, você está errado.",
  [1139165182292992] = "Na verdade, ele muitas vezes é como um babuíno de cabelos cacheados, só se preocupando com as poucas bananas colocadas bem na sua frente.",
  [1139165182292736] = "Sua inteligência não é tão boa quanto a de um babuíno de cabelos cacheados; ele não consegue distinguir entre coisas muito complexas.",
  [1139165182292480] = "Afinal, o Sr. Franky é fácil de persuadir...",
  [1139165182292224] = "Como você fez isso? Faltam seis meses para o contrato de locação. Sair mais cedo é uma quebra de contrato. Se fôssemos levados a tribunal, teríamos que pagar uma quantia enorme.",
  [1139165182291968] = "Tudo bem, vou pegar papel e caneta e assinaremos a “Rescisão do Contrato”.",
  [1139165182291712] = "Obrigado, Sr. Franky. <P_Heart> (Como Benson convenceu esse senhorio mesquinho?) </>",
  [1139165182291456] = "Klein, o Sr. Franky concordou generosamente com nosso pedido de sair mais cedo.",
  [1139165182291200] = "E você, nosso Sr. Franky, é realmente um cavalheiro elegante e nobre.",
  [1139165182290944] = "Benson, você é realmente um jovem zeloso e honesto!",
  [1139165182290688] = "Obrigado, estou saindo agora.",
  [1139165182290432] = "Entendido, deixe esta noite comigo. Você vai para casa e descansa cedo.",
  [1139165182290176] = "Kenley, o capitão disse que eu deveria trocar o turno da noite com você. Desculpe pelo problema.",
  [1139165182289920] = "Proteção da Deusa, espero que haja mais desses tolos azarados que se entreguem à nossa porta.",
  [1139165182289664] = "Talvez aquele grupo de sequestradores tenha tido muito azar. Eles eram pessoas comuns, mas tiveram que enfrentar dois Beyonders ao mesmo tempo.",
  [1139165182289408] = "Nem recebemos comissão uma vez por semana, e a maioria das comissões vale menos de 20 libras.",
  [1139165182289152] = "<P_Heart> (10 libras? Isso não é ruim...) </>",
  [1139165182288896] = "Infelizmente, você não é um membro formal, então provavelmente receberá apenas dez por cento.",
  [1139165182288640] = "De acordo com nossa regra não escrita e de longa data, metade da recompensa vai para os fundos extras da equipe e o restante é dividido igualmente entre os membros participantes.",
  [1139165182288384] = "Quanto eu ganho?",
  [1139165182288128] = "Você realmente é um rapaz de sorte. Há quanto tempo você está conosco e já recebeu uma comissão no valor de 200 libras.",
  [1139165182287872] = "Cara de sorte? Meu?",
  [1139165182287616] = "Claro que não! As regras da empresa determinam que só podemos jogar cartas na sala de recreação. Estávamos conversando sobre você, seu cara de sorte!",
  [1139165182287360] = "O que vocês estão fazendo aqui reunidos? Lutando contra o mal?",
  [1139165182287104] = "Vocês dois continuem conversando, eu voltarei primeiro. <P_Heart> (Boa sorte, Sr. Poeta que não sabe escrever poesia.) </>",
  [1139165182286848] = "Ah, capitão...",
  [1139165182286592] = "Como está a sua memorização da \"Coleção de Poesias Roselle\"? Afinal, um Poeta da Meia-Noite precisa usar diferentes estilos de poesia para exercer diferentes influências sobre os seres vivos ao seu redor.",
  [1139165182286336] = "Você? Você já passou há muito tempo do estágio de Insônia; esse tipo de consumo não significa nada para você. Porém, quase esqueci...",
  [1139165182286080] = "Quanto a mim?",
  [1139165182285824] = "Você não precisa estar de plantão esta noite. Vá trocar com Kenley e vá para casa descansar agora.",
  [1139165182285568] = "Isso é normal. Você acabou de se tornar um Beyonder e usou adivinhação várias vezes durante a missão. Você deve ter consumido bastante espiritualidade . Basta voltar e ter uma boa noite de sono.",
  [1139165182285312] = "Desculpe, de repente me sinto um pouco cansado...",
  [1139165182285056] = "O que há de errado, Klein?",
  [1139165182284800] = "<P_Heart> (Esse sentimento é... eu digeri parte da poção? Por que... porque eu agi com sucesso como Vidente uma vez?) </>",
  [1139165182284544] = "Obrigado, capitão, eu...",
  [1139165182284288] = "Assim que o cliente pagar a recompensa, um fundo extra significativo será distribuído a você.",
  [1139165182284032] = "Você lidou muito bem com essa missão, especialmente Klein. Sua habilidade de Vidente é muito útil nesses tipos de eventos.",
  [1139165182283776] = "Não se atrase para o trabalho, vá em frente.",
  [1139165182283520] = "Não tenha pressa, Benson, temos muito tempo. Estou indo para a empresa agora.",
  [1139165182283264] = "Não quero continuar ganhando menos de 2 libras por semana daqui a cinco anos, com as despesas da família dependendo inteiramente de meu irmão e irmã mais novos.",
  [1139165182283008] = "Mas também preciso trabalhar mais. Pretendo comprar mais alguns livros de contabilidade para um estudo mais aprofundado.",
  [1139165182282752] = "Você forneceu o dinheiro e nós forneceremos o esforço. Isso é justo.",
  [1139165182282496] = "Então vou deixar isso para você.",
  [1139165182282240] = "Irei para a Tingen Housing Company mais tarde. Vou deixar os assuntos da nova casa para mim e Melissa.",
  [1139165182281984] = "Nada mal, você parece um cara confiável e bonito.",
  [1139165182281728] = "Klein, use isso na empresa. Podemos lavar e passar depois.",
  [1139165182281472] = "Obrigado pelo seu patrocínio. Nossa loja apresenta designs sofisticados, materiais de qualidade e preços acessíveis. Estamos ansiosos para vê-lo novamente.",
  [1139165182281216] = "Jovem, parabéns por se livrar das sombras do passado e embarcar em uma nova jornada cheia de sol!",
  [1139165182280960] = "Em outras palavras, não preciso me preocupar em cometer suicídio de forma estranha ou ser seguido por pessoas estranhas?",
  [1139165182280704] = "Se você está vivo ou não, isso não afetará mais os desenvolvimentos subsequentes. O poder misterioso que causou tudo isso não prestará mais atenção especial a você.",
  [1139165182280448] = "O motivo do seu suicídio é claro e aquele caderno chegou às mãos de Ray Bieber. O objetivo do estranho poder foi alcançado.",
  [1139165182280192] = "Mas para você, isso é uma coisa boa.",
  [1139165182279936] = "Talvez seu nascimento espiritualidade tenha atendido aos requisitos, ou talvez ele seja o último descendente da Família Antígono. Existem muitas possibilidades...",
  [1139165182279680] = "Eu também não sei... por que teve que ser dado a Ray Bieber?",
  [1139165182279424] = "Como resultado, Welch e Naya cometeram suicídio na hora, mas não sei por que vocês sobreviveram.",
  [1139165182279168] = "Você provavelmente acionou o estranho poder do notebook, e o objetivo desse poder era entregar o notebook para Ray Bieber sem que ninguém percebesse.",
  [1139165182278912] = "Eu ainda não entendo...",
  [1139165182278656] = "Isso não é óbvio?",
  [1139165182278400] = "Então fui eu quem trouxe o caderno da Família Antigonus para cá?",
  [1139165182278144] = "Pegue o retrato e peça aos moradores aqui a confirmação final, depois emita um mandado de prisão sob a acusação de assassinar sua mãe.",
  [1139165182277888] = "Precisamos da intervenção de outras habilidades para ajudar. Solicitarei assistência de Backlund, o que levará algum tempo.",
  [1139165182277632] = "Isso indica que um poder estranho interferiu no adivinhação . Este assunto não é simples.",
  [1139165182277376] = "Parece que não vai funcionar...",
  [1139165182277120] = "Eu entendo. Continue questionando os residentes próximos e seja minucioso.",
  [1139165182276864] = "O filho do falecido se chama Ray Bieber, com cerca de 30 anos. Ele herdou o ofício de seu falecido pai e também é joalheiro.",
  [1139165182276608] = "Ela e o filho moram aqui há mais de dez anos. Segundo vizinhos, eles não são vistos há mais de uma semana.",
  [1139165182276352] = "Tenho uma ideia geral da situação. A falecida é Katy Stephana Bieber, entre 55 e 60 anos, viúva.",
  [1139165182276096] = "Mas no início, uma força invisível selou a sala. Este é um procedimento comum ao usar Ritual Magic.",
  [1139165182275840] = "Além de um cadáver, tudo aqui é normal...",
  [1139165182275584] = "Você encontrou alguma coisa?",
  [1139165182275328] = "Morto há mais de cinco dias, sem ferimentos externos e sem sinais de influência deixados por poderes extraordinários. A causa específica requer um exame mais aprofundado.",
  [1139165182275072] = "Sinto que já estive aqui antes...",
  [1139165182274560] = "Você vai se acostumar.",
  [1139165182274304] = "Eu me sinto muito melhor. Obrigado, Frye.",
  [1139165182274048] = "<P_Heart> (...o cheiro de tabaco, menta e desinfetante...) </>",
  [1139165182273536] = "<P_Heart> (Tão nojento, tão assustador...) </>",
  [1139165182273280] = "Uau————————",
  [1139165182273024] = "Klein, você e o Velho Neil venham atrás de nós.",
  [1139165182272768] = "Não existe Espírito Maligno.",
  [1139165182272512] = "Não há ninguém lá dentro e nenhuma aura mágica.",
  [1139165182272256] = "Deixe-me ver...",
  [1139165182272000] = "Você e aquele caderno da Família Antigonus parecem ter algum tipo de conexão predestinada por terem se encontrado assim.",
  [1139165182271744] = "...Meu sonho e inspiração me dizem que este é o lugar.",
  [176266263161088] = "Mãe",
  [1139165182271488] = "Vamos embora. Tome cuidado.",
  [1139165182271232] = "Entendido, capitão!",
  [1139165182270976] = "Faça com que Cohen substitua o Velho Neil para proteger o Arsenal e notifique o Velho Neil e Frye para se prepararem para uma missão. Klein, Leonard, eu irei com vocês também.",
  [1139165182270720] = "Os sonhos sempre trazem presságios importantes, especialmente para Beyonders .",
  [1139165182270464] = "Parece que perdi um grande crédito ontem.",
  [1139165182270208] = "Então tive um sonho ontem à noite e recebi uma pista!",
  [1139165182269952] = "O lugar onde Leonard e eu resgatamos o pequeno Elliott ontem ficava bem em frente à sala dos sequestradores, mas não percebi na hora.",
  [1139165182269696] = "Onde?",
  [1139165182269440] = "Capitão, acho que sei onde está esse caderno!",
  [1139165182269184] = "Klein, qual é o problema?",
  [1139165182268928] = "Como Insone, ele só precisa de duas horas de descanso todos os dias. Os proprietários de fábricas e banqueiros devem adorar esta poção.",
  [1139165182268672] = "Em seu escritório. Ele estava de vigília noturna ontem à noite.",
  [1139165182268416] = "Onde está o capitão?",
  [1139165182268160] = "Bom dia. Você parece bastante ansioso?",
  [1139165182267904] = "Isso tudo é muita coincidência... Tenho que contar ao Capitão e aos outros!",
  [1139165182267648] = "É o Caderno Antígono! Está na sala em frente aos sequestradores!",
  [1139165182267392] = "Apareceu! Aquela sensação que o Capitão mencionou – de ter visto ou feito algo antes. Essa deve ser a pista que procurávamos em relação ao caderno!",
  [1139165182266880] = "O que eu esqueci? Sobre o que esse sonho está tentando me alertar?",
  [1139165182266624] = "Algo parece errado...",
  [1139165182266368] = "Onde... estou...?",
  [1139165182265856] = "Não fique nervoso. Você verá seu pai e o velho mordomo Keli em breve. Que tal jogarmos uma partida de Gwent?",
  [1139165182265600] = "Realmente? Estou salvo?",
  [1139165182265344] = "Somos seguranças contratados pelo seu pai, estamos aqui para te salvar, está tudo bem agora.",
  [1139165182265088] = "Sim, você adivinhou certo, muito preciso.",
  [1139165182264832] = "Você, quem é você?",
  [1139165182264576] = "Hehe, ouvi dizer que todos adormeceram, você recua um pouco.",
  [1139165182264320] = "Pode ser reembolsado pela empresa?",
  [1139165182264064] = "Recentemente, estive pensando em me inscrever para um alaúde Feynapotter. Como pode uma recitação ser sem acompanhamento?",
  [1139165182263808] = "<P_Heart> (Sente-se muito tranquilo...) </>",
  [294670189994496] = "Atuando",
  [1139165182263552] = "Ameaças terríveis, esperanças vermelhas! Pelo menos uma coisa é verdade: esta vida voa. Uma coisa é verdade, o resto é mentira, a flor que uma vez floresceu para sempre morre...",
  [1139165182263296] = "A seguir é a minha apresentação, deixe-me recitar um poema para eles.",
  [1139165182263040] = "Por que ser um sequestrador? Você não pode simplesmente ser uma pessoa civilizada e feliz?",
  [1139165182262784] = "Há quatro pessoas lá dentro, uma delas com uma pequena aura, que deveria ser Elliot, e as outras três são sequestradores.",
  [1139165182262528] = "Deixe-me tentar.",
  [1139165182262016] = "Mas há duas portas aqui, qual é?",
  [1139165182261504] = "Não me chame assim... é estranho.",
  [1139165182261248] = "Deixo isso para você daqui em diante, nosso grande Vidente.",
  [1139165182260992] = "Eu tenho um retrato do Jovem Mestre Elliot e o Amuleto da Tempestade que ele usa com frequência, tudo bem?",
  [1139165182260736] = "Também precisamos de uma foto; sempre precisamos saber como é o alvo.",
  [1139165182260480] = "Preciso de algo pessoal pertencente ao Pequeno Elliot.",
  [1139165182260224] = "<P_Heart> (A Navegação com Vara de Radiestesia deve ser utilizável para encontrar pessoas usando as habilidades do Vidente, mas requer um item pessoal pertencente ao alvo.) </>",
  [1139165182259968] = "Tudo bem, há mais alguma coisa em que eu possa ajudar?",
  [1139165182259712] = "Esta também é a intenção do Capitão.",
  [1139165182259456] = "Concluir esta comissão em cooperação comigo pode servir como sua avaliação de recém-chegado, o que é muito apropriado.",
  [1139165182259200] = "Quer dizer, vamos completar isso missão juntos. Meu Sequência não é bom em encontrar pessoas, mas essa é a especialidade de um Vidente.",
  [1139165182258944] = "Preciso de sua ajuda com isso missão .",
  [1139165182258688] = "Não precisa ser humilde, você é realmente uma pessoa especial.",
  [1139165182258432] = "É apenas devido a alguns acidentes e coincidências; Eu precisava ganhar a habilidade de me proteger o mais rápido possível.",
  [1139165182258176] = "Ouvi dizer que você já se tornou um Beyonder . Essa é uma velocidade verdadeiramente louvável.",
  [1139165182257920] = "<P_Heart> (Abaixando a voz) </> Fale baixo, há convidados...",
  [1139165182257664] = "Nem sempre se considere um poeta. Na verdade, você ainda recita apenas as obras de outras pessoas.",
  [1139165182257408] = "Linda senhora, por favor elabore um contrato.",
  [1139165182257152] = "Tudo bem, não há problema.",
  [1139165182256896] = "Mas se o jovem mestre puder ser resgatado com sucesso, ele estará disposto a dobrar a recompensa, dando 200 libras de uma só vez.",
  [1139165182256640] = "Não, o Sr. Vickor é apenas um empresário comum. Além disso, em relação ao resgate, ele acredita que a polícia é mais profissional.",
  [1139165182256384] = "O Sr. Vickor só espera que descubramos onde estão os sequestradores. Um comerciante de tabaco com laços estreitos com as plantações do sul não deveria pensar que seu único filho vale tão pouco.",
  [1139165182256128] = "Se você descobrir onde os sequestradores estão escondidos, estamos dispostos a pagar uma recompensa de 100 libras.",
  [1139165182255872] = "Ele não está à vontade e espera investigar e ajudar de outras direções para garantir que o pequeno Elliott possa ser resgatado com segurança.",
  [1139165182255616] = "Então o que você está fazendo aqui?",
  [1139165182255360] = "O único filho do Sr. Vickrol, <P_Yellow> Little Elliot </>, foi sequestrado esta manhã. Já chamamos a polícia e recebemos bastante atenção deles.",
  [1139165182255104] = "Meu nome é Keli e sou o mordomo do comerciante de tabaco, Sr. Vickor.",
  [1139165182254848] = "Desculpe, por favor continue.",
  [1139165182254592] = "Você é muito pontual.",
  [1139165182254336] = "Espere, 8 libras, apenas 8 libras, combinado!",
  [1139165182254080] = "... <P_Heart> (Fomos para a Right Street agora há pouco?) </>",
  [1139165182253824] = "Klein, qual você prefere, este conjunto ou aquele da loja do Sr. Wat na Right Street, mais cedo? Embora o Sr. Wat tenha dito que poderia colocar uma gravata borboleta nova, hmm...",
  [1139165182253568] = "Isso é um pouco...",
  [1139165182253312] = "8 libras? Se você puder adicionar esta cartola, seria um preço razoável.",
  [1139165182253056] = "Veja a alfaiataria e o tecido, veja como esse senhor fica gracioso usando isso. Que tal isso, vou te dar um desconto, 8 libras!",
  [1139165182252800] = "Já está aí há muito tempo... o vento e o sol vão causar depreciação, não é à toa que esse canto da bainha está um pouco branco e desgastado.",
  [1139165182252544] = "Isso porque era uma peça de exposição, usada por um manequim na vitrine por um tempo. Definitivamente não são roupas velhas.",
  [1139165182252288] = "Ahem, Klein, essa peça de roupa parece um pouco velha e tem um pouco de poeira, olha aqui...",
  [1139165182252032] = "<P_Heart> (Benson, vou deixar isso com você.) </>",
  [1139165182251776] = "9 libras...",
  [1139165182251520] = "Esta base de terno formal inclui casaco, calças, colete, camisa e botas de couro, totalizando 9 libras.",
  [1139165182251264] = "Este conjunto é bom, muito adequado para funcionários de empresas de segurança. Quanto?",
  [1139165182251008] = "Muito animado. Vamos, gire e deixe-me ver.",
  [1139165182250752] = "Eu entendo, então você pode tentar este conjunto.",
  [1139165182250496] = "Simples é bom, como um casaco preto e uma camisa branca, combinados com uma cartola de seda.",
  [1139165182250240] = "Você tem algum outro estilo aqui?",
  [1139165182249984] = "Na verdade, roupas tão chamativas não são adequadas para trabalhar na empresa. Afinal, os empregadores muitas vezes preferem empregados mais estáveis.",
  [1139165182249728] = "Mas sinto que a gola está um pouco apertada, meu peito está abafado e as algemas aqui...",
  [1139165182249472] = "E são apenas 12 libras! Por apenas 12 libras, você será o cavalheiro mais atraente em qualquer ocasião social!",
  [1139165182249216] = "É o estilo mais moderno importado da Intis. As bordas do colete são decoradas com fios de ouro e a gola é decorada com pedras preciosas reais.",
  [1139165182248960] = "Não é ruim, mas... é um pouco chamativo demais?",
  [1139165182248704] = "Klein, o que você acha?",
  [1139165182248448] = "Essa roupa é chamada de 'New Leaf'. Diz-se que o designer utilizou o conceito de folhas verdes frescas na primavera, conferindo a todo o conjunto um temperamento fresco e vivo.",
  [1139165182248192] = "Parece muito maduro, tão maduro que quero te chamar de irmão.",
  [1139165182247936] = "Realmente tem uma sensação madura e confiável.",
  [1139165182247680] = "Você tem um ótimo olho. Esta roupa é bem adaptada, com um design discreto e estável, adequada para qualquer ocasião.",
  [1139165182247424] = "Afinal, ainda é verão. Se você sair usando roupas como essas, poderá desmaiar devido à insolação antes mesmo de dar alguns passos.",
  [1139165182247168] = "É que esse tecido é muito grosso, está tão quente que mal consigo respirar...",
  [1139165182246912] = "Senhor, você parece firme, mas elegante, com um pouco de charme em sua seriedade. Essa roupa realmente combina com o seu temperamento!",
  [1139165182246656] = "Klein, estas são as regras da sociedade. Bem-vindo ao mundo adulto.",
  [1139165181857536] = "Mais tarde, vá encontrar o <P_Yellow> Velho Neil </> e peça para ele providenciar algum trabalho de leitura de literatura para você. Afinal, você é um profissional da história.",
  [1139165181929728] = "Droga, você provocou a <P_Yellow> Gangue de Caçadores de Dragões </> !",
  [1139165181928704] = "...Algo aconteceu tão cedo? Você realmente deveria se tornar um Beyonder para poder lidar com esses eventos estranhos e misteriosos com mais calma.",
  [1139165181928448] = "Espaço reservado",
  [1139165181928192] = "Tudo bem, vou guardar minha mochila!",
  [1139165181927936] = "Venha, venha provar a comida do seu irmão.",
  [1139165181927680] = "Você fez tudo isso?",
  [1139165181927424] = "Cheira tão bem...",
  [1139165181927168] = "Parece ótimo!",
  [1139165181926912] = "Isso também faz parte do trabalho!",
  [1139165181926656] = "Ou posso passear pelo caminho, tal como o Capitão Dunn disse? Talvez eu encontre pistas relacionadas ao caderno.",
  [1139165181926400] = "Ainda é cedo, posso ir para casa e preparar uma grande refeição para comemorar com Melissa esta noite que consegui um bom emprego!",
  [1139165181926144] = "A questão do trabalho está finalmente resolvida.",
  [1139165181925888] = "Durma, durma, tenho que ir trabalhar amanhã...",
  [1139165181925632] = "Benson voltará para casa em breve... Lembre-se que prometi buscá-lo e fazer uma boa refeição juntos!",
  [1139165181925376] = "Ensopado de borrego com ervilhas jovens, tão delicioso.",
  [1139165181925120] = "Mas a única pista que chegou à minha porta agora é aquele cara que enlouqueceu e perdeu o controle na rua. O que exatamente está acontecendo...",
  [1139165181924864] = "Ainda não sei onde está aquele caderno Antigonus. O capitão me disse para dar uma volta, talvez eu encontre pistas.",
  [1139165181924608] = "O capitão disse que este é um Caminho incompleto e que eu mesmo preciso encontrar um caminho para as sequências subsequentes... mas ainda é muito cedo para pensar nisso.",
  [1139165181924352] = "Embora eu tenha aprendido conhecimentos básicos de habilidade, o caminho do Beyonder é misterioso e perigoso, então ainda tenho que ser cauteloso.",
  [1139165181924096] = "Eu escolhi \"Seer\" e me tornei um Beyonder .",
  [822505833274112] = "Algo mais?",
  [1139165181923840] = "Os benefícios são muito bons e os colegas parecem muito amigáveis. Espero que tudo corra bem mais tarde...",
  [1139165181923584] = "Uma equipe Beyonder disfarçada de empresa de segurança, afiliada à Igreja da Meia Noite, e agora também é minha empresa.",
  [1139165181923328] = "Preciso encontrar o notebook e também preciso de capacidade de autoproteção suficiente, então aceitei o convite para ingressar na Blackthorn Security Company e me tornei um Beyonder .",
  [1139165181923072] = "Por causa daquele caderno da família Antígono, estive envolvido num acontecimento estranho.",
  [1139165181922816] = "Parece que muita coisa aconteceu hoje...",
  [1139165181922560] = "Tudo bem, tudo bem, vamos começar a aproveitar o jantar, estou com muita fome.",
  [1139165181922304] = "Uma empresa de segurança com a missão de encontrar, coletar e proteger antiguidades. Eles precisam de consultores profissionais.",
  [1139165181922048] = "Deusa... que tipo de trabalho você encontrou!",
  [1139165181921792] = "Mas consegui outro emprego e eles até me adiantaram quatro semanas de salário.",
  [1139165181921536] = "Está tudo bem Klein, não precisa se apressar. Podemos procurar outras oportunidades!",
  [1139165181921280] = "Sim, pensei que nossa família poderia ter um professor universitário!",
  [1139301010114816] = "O cervo morto ressuscitou de repente e atacou você, mordendo seu braço. \n Você lutou desesperadamente e finalmente conseguiu se livrar disso.",
  [1139301010118912] = "De repente, raios de luz carmesim descem, subindo de diferentes assentos e se transformando em pessoas com rostos borrados.",
  [1139165181920512] = "Estou cansado, volte e descanse também.",
  [1139165181920256] = "Estou me preparando para experimentar um novo Ritual de Magia em você, seu garotinho nojento!",
  [1139165181857024] = "Dê uma olhada nesta aliança. As pessoas gostam de chamar isso de contrato hoje em dia.",
  [1139165181918976] = "Só um pouco de lama da sola do meu sapato. Sua cor é quase a mesma do pó de café, quase a mesma.",
  [1139165181918720] = "Então, o que você colocou no café?",
  [1139165181918464] = "Também pode ser interpretado como desfavorável e favorável. Este pêndulo é um presente para você; experimente os detalhes você mesmo.",
  [1139165181918208] = "Sentido anti-horário 'Não', sentido horário 'Sim'...",
  [1139165181917952] = "Sim, o cristal girando no sentido anti-horário é ruim, no sentido horário é bom e não se mover significa que não é bom nem ruim.",
  [1139165181917696] = "Através do seu cristal?",
  [1139165181917440] = "Eu não adivinhei, este é o método do pêndulo </> em adivinhação , contando com a conexão entre o próprio corpo astral e o mundo espiritual e o céu estrelado, e usando a comunicação entre materiais naturais e espiritualidade para adivinhar o bom ou o ruim das coisas.<P_Yellow>",
  [1139165181917184] = "Adivinhei certo!",
  [1139165181916928] = "O copo à <P_Yellow> esquerda </> tem algo ruim.",
  [1139165181916672] = "Eu sei.",
  [1139165181916416] = "Feito!",
  [1139165181916160] = "Feito?",
  [862026243078912] = "Ler",
  [1139165181915904] = "Tudo bem, vá contar ao Velho Neil.",
  [1139165181915648] = "Em qual xícara de café devo colocar?",
  [1139165181915392] = "Mas... só não beba!",
  [1139165181915136] = "Isso não seria um pouco indelicado?",
  [1139165181914880] = "O cabelo conta como ‘algo ruim’? Vamos tentar... Ai, isso dói!",
  [1139165181914624] = "Deixa eu acrescentar uma coisa ao café... A sola do meu sapato está tão suja que preciso lavá-lo...",
  [1139165181914368] = "Algo ruim? Especificamente, o que devo colocar...",
  [1139165181914112] = "Vamos, coloque algo ruim em um dos copos, mas não me conte.",
  [1139165181913856] = "Garotinho ganancioso, então vou te ensinar outro truque interessante.",
  [1139165181913600] = "Sinto-me em boas condições agora, quero aprender mais!",
  [1139165181913344] = "Você é muito talentoso, mas após cada prática ou uso excessivo de Visão Espiritual , você precisa recuperar seu espiritualidade através do sono. Você pode ir para casa e descansar.",
  [1139165181913088] = "Que sentimento mágico... eu sou um Beyonder !",
  [1139165181912832] = "Uh, não se preocupe, é apenas uma representação da Magia Ritual.",
  [1139165181912576] = "Há olhos atrás de você!",
  [1139165181912320] = "Feche os olhos, levante as mãos, coloque-as na frente dos olhos, os dedos indicadores voltados um para o outro, mas não se toquem.",
  [1139165181912064] = "Sendo esse o caso, vou lhe ensinar a habilidade mais simples e mais comumente usada no campo misterioso, que também tem o maior potencial para o futuro— <P_Yellow> Visão Espiritual </> !",
  [1139165181911808] = "Eu me sinto muito bem e parece que algum conhecimento de “Vidente” apareceu na minha cabeça. O que devo fazer a seguir?",
  [1139165181911552] = "Parabéns, novo Beyonder , nosso Vidente.",
  [1139165181911296] = "Vou te ensinar meditação agora. Faça o que eu digo.",
  [1139165181911040] = "Isso ocorre porque o poder da poção transbordou e você não tem como controlá-la.",
  [1139165181910784] = "Sim... O que devo fazer agora?",
  [1139165181910528] = "Sua visão está anormal? E você está ouvindo sons estranhos?",
  [1139165181910272] = "Jovem, não hesite. Quanto mais você hesitar, mais nervoso ficará, e quanto mais nervoso estiver, mais afetará a absorção da poção.",
  [1139165181910016] = "Se você está se sentindo nervoso.",
  [1139165181909760] = "Em seguida, cantarole uma melodia melodiosa e dance uma leve dança de corte - você pode fazer sapateado, se quiser. Finalmente, jogue uma partida de Gwent...",
  [1139165181909504] = "Preparação? Depois, primeiro tome uma taça de vinho Olmier da Intis e fume um charuto Dicy.",
  [1139165181909248] = "Devo apenas beber assim? Não são necessários outros preparativos? Como um ritual ou oração?",
  [1139165181908992] = "Eu vou te ensinar. Você está pronto?",
  [1139165181908736] = "Basta seguir a ordem da receita, adicionar os ingredientes um a um de acordo com as medidas e depois mexer um pouco.",
  [1139165181908480] = "Deixe-me ver... está tudo aqui. O preparo de poções low-Sequência é muito simples, não requer chamas ou encantamentos especiais. Pelo menos é o caso abaixo Sequência 7.",
  [1139165181908224] = "Podemos começar agora. Traga os ingredientes; eles estão no armário ali.",
  [1139165181907968] = "Nada mal, não seguindo a multidão, você tem caráter como eu naquela época. E você tem sorte, ainda restam duas porções de materiais da poção do Vidente, caso contrário você teria que esperar muito tempo.",
  [1139165181907712] = "Eu escolhi \"Vidente\".",
  [1139165181907456] = "Algo deu errado tão cedo? Você realmente deveria se tornar um Beyonder , para poder lidar com esses eventos estranhos e misteriosos com mais calma.",
  [1139165181906944] = "O capitão Dunn me pediu para entregar isso a você.",
  [1139165181906688] = "O Velho Neil deveria estar na <P_Yellow> Sala de Alquimia </>, você pode simplesmente ir procurá-lo... Que a Deusa proteja você.",
  [1139165181906432] = "Eu posso entender.",
  [1139165181906176] = "Mas, honestamente, respeito todos que se voluntariam para se tornar um Vigia Noturno .",
  [1139165181905920] = "Por causa do que aconteceu com ele, sempre fico um pouco emocionado com questões semelhantes...",
  [1139165181905664] = "Tudo bem, desculpe... Meu pai já foi um membro formal do Vigias Noturnos ; ele se sacrificou em um incidente Beyonder há cinco anos.",
  [1139165181905408] = "Rozanne, pare, pare por um segundo!",
  [1139165181905152] = "Os inimigos de Beyonders não são apenas cultistas e feiticeiros das trevas, mas também eles próprios! Quase todos os anos as pessoas perdem o controle e se sacrificam! Você não está com medo? Você não leva em consideração os sentimentos de sua família?",
  [1139165181904896] = "Mas, mas! Minha Deusa, você sabe o quão perigoso isso é? O capitão não te contou?",
  [1139165181904640] = "Que assustador... Mas aqueles que estiveram envolvidos com Beyonders têm uma probabilidade maior de serem afetados por Beyonder incidentes novamente...",
  [1139165181904384] = "Talvez porque fui rapidamente arrastado para outro incidente perigoso Beyonder.",
  [1139165181904128] = "Eh? Você acabou de entrar na empresa, tão cedo...",
  [1139165181903872] = "O capitão disse que abriria uma exceção para eu me tornar um Beyonder , vou encontrar o Sr. Neil agora.",
  [1139165181903616] = "<P_Heart> (Espero que realmente não haja mais nada desta vez...) </>",
  [1139165181903360] = "Nada mais, vá em frente.",
  [1139165181903104] = "Eu terei cuidado.",
  [1139165181902848] = "Esta operação dos Alquimistas da Psicologia falhou, mas eles podem continuar a enviar pessoas para rastrear você. Você deve ficar vigilante e ter cuidado.",
  [1139165181902592] = "<P_Heart> (Como esperado...) </>",
  [1139165181902336] = "Ah, mais uma coisa.",
  [1139165181901824] = "Capitão, há mais alguma coisa?",
  [1139165181901568] = "Você se tornar um Beyonder é baseado na necessidade de lidar com o perigo e encontrar o caderno. Depois, você precisa seguir o Velho Neil para aprender conhecimentos ocultos adicionais. Você mesmo pode organizar o horário para isso. Alguma dúvida?",
  [1139165181901312] = "<P_Heart> (O Capitão não parece ter uma memória muito boa...) </>",
  [1139165181901056] = "Tudo bem, capitão...",
  [1139165181900800] = "Leve isso para o Velho Neil e ele entenderá.",
  [1139165181900544] = "Me sinto bem, vou agora.",
  [1139165181900288] = "Tudo bem, vá encontrar o Velho Neil. Você também pode descansar um ou dois dias antes de ir.",
  [1139165181900032] = "Eu sei, mas respeito a voz interior.",
  [1139165181899776] = "Por que escolher \"Vidente\"? Lembro a você que, depois de consumir a poção, não há chance de se arrepender.",
  [1139165181899520] = "Eu escolho, \"Vidente\"!",
  [1139165181899264] = "Eu já decidi. eu escolho...",
  [1139165181899008] = "Será que ele está se referindo a este Vidente?",
  [1139165181898752] = "O Imperador Roselle mencionou em seu diário... \"Seja Aprendiz, ou <P_Yellow> Vidente </>, ou Saqueador, todos eles são melhores\".",
  [1139165181898496] = "Além disso, quero fortalecer ainda mais minha compreensão e domínio do oculto; o Corpse Collector Caminho não é adequado para mim.",
  [1139165181898240] = "A senhorita Daly também escolheu este Caminho , parece misterioso e legal... mas tenho um pouco de medo de cadáveres...",
  [1139165181897984] = "Mas tome cuidado com o poder de certas existências. O Velho Neil também disse que muitas vezes não dorme bem à noite e ouve alguns sussurros estranhos...",
  [1139165181897728] = "Este é o Caminho do Velho Neil, que pode aprender melhor o conhecimento oculto.",
  [1139165181897472] = "Esses três caminhos...",
  [1139165181897216] = "Não se apresse em escolher. Acalme-se e pergunte ao seu coração.",
  [1139165181896960] = "Todos soam bem...",
  [1139165181896704] = "Claro, isso não significa que, depois de consumir a poção, você compreenderá e dominará imediatamente o poder. A poção apenas lhe dá a qualificação para aprender essas habilidades.",
  [1139165181896448] = "Mas este Sequência carece de meios diretos de combater os inimigos, e só temos sua fórmula Sequência 9. Se a Catedral escondeu outros, não sei.",
  [1139165181896192] = "Não sabemos muito sobre isso Caminho . É bom em adivinhação , Visão Espiritual e habilidades semelhantes, e é proficiente em conhecimento oculto.",
  [1139165181895936] = "Além disso, eles também ganharão algumas melhorias no condicionamento físico, sendo capazes de suportar a erosão do frio, da podridão e da aura da morte.",
  [1139165181895680] = "\"Colecionador de cadáveres\" entende muitas características e fraquezas de criaturas mortas-vivas, pode ser confundido com sua própria espécie por mortos-vivos estúpidos para evitar serem atacados e pode ver diretamente alguns espíritos malignos.",
  [1139165181895424] = "Você deve estar relativamente familiarizado com isso Caminho . Daly é atualmente um Sequência 7 \"Médium Espiritual\" deste Caminho .",
  [1139165181895168] = "Mas eles percebem facilmente certas existências escondidas atrás das coisas e devem ter muito cuidado, permanecendo maravilhados com Beyonder poderes.",
  [1139165181894912] = "Este é o Caminho ao qual o Velho Neil pertence. \"Espreitadores de Mistérios\" entendem e dominam magia, bruxaria, astrologia e outros campos misteriosos, e são proficientes em Magia Ritual.",
  [1139165181894656] = "Para opção de salto",
  [1139165181894400] = "Eu quero saber...",
  [1139165181894144] = "Beba esta poção. Isso fará com que você se sinta um pouco mais relaxado.",
  [1139165181893888] = "Então é assim... Louvada seja a Deusa. Talvez a Deusa estivesse cuidando de seu devoto crente e guiando você na neblina.",
  [1139165181893632] = "Ouvi o hino da Deusa no meio da neblina e vi o coral praticando essa canção perto da igreja.",
  [1139165181893376] = "Porém, como você se livrou da influência do Artefato Selado? Você é apenas uma pessoa comum, mas encontrou a direção correta no nevoeiro.",
  [1139165181893120] = "Sim, mas não se preocupe muito. Desde que sejam usados ​​e selados adequadamente, podem desempenhar um papel importante em situações específicas.",
  [1139165181892864] = "Os artefatos selados também podem fazer com que Beyonders perca o controle?",
  [1139165181892608] = "A pessoa que está rastreando você pode ter perdido o controle porque não conseguiu controlar totalmente a habilidade do Artefato Selado. Esses itens costumam ser poderosos e perigosos.",
  [1139165181892352] = "Diferentes Artefatos Selados têm efeitos diferentes. Por exemplo, ocultar uma área ou fazer o alvo cair na alucinação de um labirinto nebuloso.",
  [1139165181892096] = "Todas essas são manifestações das habilidades de itens místicos, que oficialmente chamamos de <P_Yellow> Artefatos Selados </> . Hmm... acho que esqueci de explicar isso antes.",
  [1139165181891840] = "Além disso, um monstro tão grande caiu na estrada, mas as pessoas ao redor pareciam incapazes de vê-lo...",
  [1139165181891584] = "Agora mesmo, uma névoa espessa surgiu de repente na rua e todos os que estavam por perto desapareceram.",
  [1139165181891328] = "Klein, o caminho do Beyonder está cheio de tentações e perigos. Se você não tomar cuidado, você cairá e perderá o controle. Você deve se lembrar disso.",
  [1139165181891072] = "Muito inteligente. De repente, ele perdeu o controle enquanto rastreava você, sua mente enlouqueceu e seu corpo se transformou em um monstro.",
  [1139165181890816] = "Esse tipo de monstro é humano? Ele perdeu o controle?",
  [1139094851814656] = "Retire o pergaminho",
  [1139094851684608] = "Concordo com Enid",
  [1139094851688704] = "Ferida desaparecendo",
  [1139165181890560] = "Tudo isso graças ao seu estado de alerta. Este é o seu crédito.",
  [1139165181890304] = "Esses caras são tão bons em se esconder quanto ratos no esgoto. Foi realmente uma colheita inesperada que conseguimos colher.",
  [1139165181890048] = "Mas por negligência de um membro, o caderno entrou no mercado de antiguidades e foi adquirido por Welch. Agora eles têm que enviar pessoas para todos os lugares para rastreá-lo.",
  [1139165181889792] = "Ele vem da <P_Yellow> Ordem Secreta </>, uma antiga organização estabelecida na Quarta Época. O Antigonus Notebook original era controlado por eles.",
  [1139165181889536] = "Capitão, eu...",
  [1139165181889280] = "Você provavelmente tem muitas perguntas. Acontece que agora é hora do intervalo.",
  [1139165181889024] = "Klein, seu julgamento foi muito correto. Foram os colegas próximos à catedral que descobriram a sua anormalidade que nos permitiu chegar a tempo.",
  [1139165181888768] = "De repente, tudo ao redor estava cheio de uma névoa espessa. Ele apareceu da neblina e se transformou em um monstro. Eu só pude correr em direção à catedral...",
  [1139165181888512] = "Qual é a situação? Qual é a névoa cinzenta ao redor? Eu não posso sair daqui!",
  [1139165181888256] = "<P_Heart> (Assim, conduza lentamente o outro grupo em direção à catedral...) </>",
  [1139165181888000] = "<P_Heart> (Essa sensação de estar sendo observado não desapareceu. Um Beyonder pode correr mais rápido que uma carruagem?) </>",
  [1139165181887744] = "<P_Heart> (Se eu também fosse Beyonder , não entraria em pânico, né...) </>",
  [1139165181887488] = "Tudo bem, por favor entre.",
  [1139165181887232] = "<P_Heart> (Será mais seguro perto da catedral e será mais fácil notificar o Vigias Noturnos ...) </>",
  [1139165181886976] = "Vá para a rua Champagne. <P_Heart> (Champagne Street fica muito perto da Igreja da Deusa da Noite Eterna, mas também é um local público, então é razoável que eu vá até lá.) </>",
  [1139165181886720] = "<P_Heart> (Mas ainda não sei as verdadeiras intenções da outra parte. Isso pode me expor e deixá-lo escapar.) </>",
  [1139165181886464] = "<P_Heart> (Ainda não estou conseguindo lidar com um Beyonder , talvez deva retornar à empresa para buscar ajuda dos meus Vigia Noturno colegas...) </>",
  [1139165181886208] = "<P_Heart> (Não posso levar o perseguidor de volta. Isso colocaria Melissa e os outros em perigo!) </>",
  [1139165181885952] = "<P_Heart> (Não, não posso ir para casa!) </>",
  [1139165181885696] = "Senhor, para onde?",
  [1139165181885440] = "<P_Heart> (Não, alguém está me observando? Me observando? Me monitorando?) </>",
  [1139165181885184] = "Algo está errado! Fique calmo, fique calmo...",
  [1139165181884928] = "(O dinheiro realmente não dura muito. Benson realmente passou por dificuldades antes...)",
  [1139165181884672] = "Serão 18 centavos no total.",
  [1139165181884416] = "Deixe-me ver... Dê-me algumas ervilhas, repolho, cebola... e algumas batatas!",
  [1139165181884160] = "Legumes recém-enviados de fazendas fora da cidade, baratos e frescos!",
  [1139165181883904] = "Então, que tal esta peça? 7 centavos.",
  [1139165181883648] = "Apenas me dê um pedaço de cordeiro fresco comum, do tipo barato.",
  [1139165181883392] = "Tudo bem! Que tal esta peça? Fresco e gorduroso!",
  [1139165181883136] = "Dê-me meio quilo de cordeiro.",
  [1139165181882880] = "Cordeiro fresco! Assado, cozido, frito – é delicioso, não importa como você o cozinhe!",
  [1139165181882624] = "Como esperado, ele não tem nada de especial...",
  [1139165181882112] = "Você viu alguma coisa...",
  [1139165181881856] = "<P_Heart> ( Sequência 8, Poeta da meia-noite, Leonard...) </>",
  [1139165181881600] = "Adoraria conversar mais com você, mas tenho que substituir o capitão de plantão. Adeus.",
  [1139165181881344] = "Eu também acho que tenho sorte o suficiente.",
  [1139165181881088] = "Ter encontrado tal evento e ainda estar vivo é bastante especial por si só.",
  [1139165181880832] = "Você tem um temperamento especial.",
  [1139165181880576] = "Heh, tenho uma impressão profunda de você.",
  [1139165181880320] = "Olá, Klein.",
  [1139165181880064] = "Estarei trabalhando aqui a partir de agora. Por favor, cuide de mim.",
  [1139165181879808] = "Obrigado, até amanhã.",
  [1139165181879552] = "Faz muito tempo que não tenho medo... Aqui é muito bom, Klein. Bem-vindo à equipe.",
  [1139165181879296] = "Não admira que ele precisasse de órgãos internos diferentes... Desculpe, fiz você se lembrar de coisas ruins.",
  [1139165181879040] = "Sim, ele matou muitas pessoas antes disso. Naquela época, ele estava preparando um ritual maligno, por isso foi pego pelo Vigias Noturnos.",
  [1139165181878784] = "O assassino era um Beyonder ?",
  [1139165181878528] = "Se o Vigias Noturnos não tivesse chegado a tempo, eu teria sido a sexta vítima.",
  [1139165181878272] = "Eu lembro! O 'Açougueiro Sangrento' que matou cinco meninas e roubou seus diferentes órgãos? Quando eu era criança, minha mãe costumava usar isso para assustar minha irmã.",
  [1139165181878016] = "Você conhece o serial killer que chocou toda a cidade de Tingen dezesseis anos atrás?",
  [633321918830080] = "Examinar",
  [1139165181877760] = "Você também passou por um caso estranho e assustador Beyonder?",
  [1139165181877504] = "Eu sou o mesmo.",
  [1139165181877248] = "Hum, sim.",
  [1139165181876992] = "Klein, você foi convidado pelo capitão porque foi afetado por um incidente maligno e também tem talentos especiais?",
  [1139165181876736] = "<P_Heart> (12 libras equivalem a 240 soli, ou 2.880 centavos de cobre, o que se converte em mais de dez mil em dinheiro de antes de eu transmigrar!) </>",
  [1139165181876480] = "<P_Heart> (1 libra equivale a 20 soli e 1 soli equivale a 12 centavos. E aqui, o poder de compra de 1 centavo equivale a 3 ou 4 yuans antes de eu transmigrar, então...) </>",
  [1139165181876224] = "Sou eu. Bem-vindo, Klein. Você tem muita sorte; há dinheiro suficiente hoje.",
  [1139165181875968] = "Esta é a Sra. Orianna? Eu sou o cara novo, Klein Moretti. O capitão Dunn me pediu para vir e sacar um adiantamento de 4 semanas de salário.",
  [1139165181875712] = "Orianna? Ela geralmente só fica <P_Yellow> lá em cima </> . Vá dar uma olhada.",
  [1139165181875456] = "Muito obrigado. A propósito, posso perguntar onde está o contador?",
  [1139165181875200] = "Tudo bem, recém-chegado, volte e tenha uma boa noite de sono. Seu trabalho começa oficialmente amanhã.",
  [1139165181874944] = "Tudo bem, vou manter isso em mente!",
  [1139165181874688] = "No entanto, primeiro você precisa de uma boa pontaria, caso contrário, suas balas atingirão primeiro seus companheiros de equipe ou você mesmo.",
  [1139165181874432] = "Como Vigia Noturno , você tem autoridade para usar livremente um revólver e atacar os inimigos.",
  [1139165181874176] = "A propósito, aqui estão essas balas, esses são seus suprimentos de bordo, leve-os bem.",
  [1139165181873920] = "<P_Heart> (Talvez eu possa postar um missão para encontrar o diário do Imperador Roselle no Clube do Tarô ...) </>",
  [1139165181873664] = "Apenas estas poucas páginas. Talvez a Catedral ainda tenha alguns. Além disso, podem ser encontrados em mercados negros e organizações secretas. Você achou que isso era fácil de conseguir?",
  [1139165181873408] = "Este diário, existem outros?",
  [1139165181873152] = "<P_Heart> (A chave para uma poção não é dominar e cavar, mas digerir e agir... o que isso significa?) </>",
  [1139165181872896] = "<P_Heart> (Então talvez eu consiga obter algumas informações preciosas e secretas de seu diário, ou até mesmo pistas para voltar para casa...) </>",
  [1139165181872640] = "<P_Heart> (O Imperador é realmente meu companheiro transmigrador!) </>",
  [1139165181872384] = "Que jovem. Certa vez, também pensei que era a pessoa mais especial. Mas muitas pessoas estudam a vida toda e só conseguem entender algumas palavras sobre elas.",
  [1139165181872128] = "Este... pensei que seria o mais especial e quis tentar decifrá-lo e interpretá-lo imediatamente.",
  [1139165181871872] = "Por que você de repente começou a se distanciar?",
  [1139165181871616] = "Você também deve dar uma olhada nesses materiais.",
  [1139165181871360] = "Depois de realmente se envolver neste trabalho, você saberá como é difícil!",
  [1139165181871104] = "...Sua coisinha rude!",
  [1139165181870848] = "Você também pode dar uma olhada. Você terá que começar a me ajudar com esse trabalho amanhã.",
  [1139165181870592] = "Uma ideia genial, certo?",
  [1139165181870336] = "Espero comparar as datas dos acontecimentos históricos daquela época com as anotações do diário das datas correspondentes, de modo a decifrar mais símbolos.",
  [1139165181870080] = "Mas já decifrei alguns símbolos dele, confirmei que são expressões de números e descobri que na verdade é um diário!",
  [1139165181869824] = "Este lendário imperador de Intis usou símbolos estranhos que inventou para registrar informações, e muitas pessoas acreditam que este é o seu caderno.",
  [1139165181869568] = "<P_Heart> (Aquele Imperador Roselle que é um suposto predecessor transmigrador?) </>",
  [1139165181869312] = "Este é o diário de <P_Yellow> Roselle Gustav </> .",
  [1139165181869056] = "Por exemplo, estes em minha mão requerem registros históricos e interpretação mais detalhados para inferir seu conteúdo específico.",
  [1139165181868800] = "Algumas coisas relacionadas à história, como diários populares, livros populares, epitáfios, etc. São complexas e fragmentadas.",
  [1139165181868544] = "O Capitão Dunn pediu-lhe para organizar o meu trabalho. Quais documentos e livros devo interpretar primeiro?",
  [1139165181868288] = "Não há necessidade de se preocupar, muito obrigado.",
  [1139165181868032] = "Nada mal, muito bom gosto.",
  [1139165181867776] = "Café tão perfumado...",
  [1139165181867520] = "Tudo bem, experimente.",
  [1139165181867264] = "É bom ser jovem. Se eu não dormir bem à noite, ouvirei alguns <P_Yellow> sussurros de existências inexplicáveis ​​</> .",
  [1139165181867008] = "Por favor, me dê uma xícara. Eu realmente não dormi bem ontem...",
  [1139165181866752] = "Assim como eles, me chame de Velho Neil. Gostaria de uma xícara de café moído à mão?",
  [1139165181866496] = "Miss Rozanne é realmente uma pessoa amigável. Desculpe incomodá-lo, Sr. Neil.",
  [1139165181866240] = "Você deve ser Klein Moretti? A pequena Rozanne acabou de dizer que você é muito educado.",
  [1139165181865984] = "Tudo bem, capitão Dunn.",
  [1139165181865728] = "Você deveria me chamar de Capitão Dunn agora.",
  [1139165181865472] = "Tudo bem, Sr. Dunn.",
  [1139165181865216] = "Você também precisa de um terno formal próprio.",
  [1139165181864960] = "Não, isso é necessário. Pense bem, você ainda está disposto a morar no seu apartamento atual? Até o banheiro tem que ser compartilhado com várias famílias, e além disso...",
  [1139165181864704] = "Isso é demais. Posso aguentar menos por enquanto.",
  [1139165181864448] = "Vá procurar a contadora, <P_Yellow> Sra. Orianna </>, para sacar um adiantamento de quatro semanas de salário. Depois disso, você receberá apenas metade do seu salário por semana até que seja quitado.",
  [1139165181864192] = "Não há necessidade de entregá-lo. Depois que o revólver estiver emparelhado com as balas Demon Hunter, você poderá se proteger se realmente encontrar algum perigo, ou isso pode lhe dar coragem.",
  [1139165181863936] = "Ah, sim.",
  [1139165181863680] = "Welch's House perdeu um <P_Yellow> revólver </> , ele ainda deveria estar com você, certo?",
  [1139165181863424] = "Quando você for à casa do Velho Neil, lembre-se de coletar algumas balas de caçadores de demônios.",
  [1139165181863168] = "O pôster de procurado está sobre a mesa. Lembre-se de como ele é.",
  [1139165181862912] = "A propósito, há três anos, um arcebispo recém-nomeado desapareceu com um artefato selado de grau 0.",
  [1139165181862656] = "<P_Yellow> \"Somos guardiões, mas também um grupo de pobres coitados que lutam constantemente contra o perigo e a loucura.\" </>",
  [1139165181862400] = "Uma vez cometido um erro, a pessoa avançará passo a passo em direção à perda de controle. O fundador do sistema Vigia Noturno moderno, o Arcebispo Chanis, disse uma vez:",
  [1139165181862144] = "Ouvir sons que outros não podem ouvir, ver coisas que outros não podem ver e estar constantemente sujeito a tentações misteriosas e feitiços ilusórios.",
  [1139165181861888] = "O poder deve ter um preço. Enquanto buscamos o poder, também acumulamos loucura e perda de controle...",
  [1139165181861632] = "Morte mental, colapso físico... e grande parte dessas pessoas que perderam o controle eram nossos companheiros de equipe.",
  [1139165181861376] = "Enlouquecendo porque não conseguem suportar o poder, caindo porque ouvem os sussurros de existências desconhecidas e tendo suas personalidades distorcidas devido ao colapso mental.",
  [1139165181861120] = "Entre os Beyonder incidentes tratados pela Vigias Noturnos e outras organizações judiciais semelhantes todos os anos, um quarto é <P_Yellow> perda de controle por Beyonders </> .",
  [1139165181860864] = "Beyonders não são o que você imagina. Estamos sempre caminhando com perigo, então você deve escolher com cautela.",
  [1139165181860608] = "Você já se tornou nosso funcionário administrativo, mas se você pode se tornar um Beyonder formal depende de seus encontros futuros.",
  [1139165181860352] = "Quais foram os poderes Beyonders e Beyonder que você mencionou anteriormente?",
  [1139165181860096] = "Eu entendo.",
  [1139165181859840] = "Esta é a colheita que queremos. Afinal... aquele caderno é muito importante.",
  [1139165181859584] = "Só porque Daly não conseguiu descobrir nada usando os métodos de um “Médium Espiritual” não significa que eles absolutamente não existam. Talvez em lugares familiares e críticos você tenha a sensação de que já viu ou fez algo antes.",
  [809242973986304] = "Ok, eu entendo.",
  [1139165181859328] = "Eu realmente não me lembro de nada, e as habilidades da Sra. Daly também não descobriram nada.",
  [1139165182968064] = "Três dias depois? Tudo bem...",
  [1139165182836992] = "Haines mencionou esta manhã que é possível orar por ajuda de diferentes entidades com a ajuda da Magia Ritual.",
  [1139165182820608] = "<P_Heart> (Rasgando) </> Eu quero que todos... estejam vivos.",
  [1139165181858304] = "O caso de Welch e Naya foi concluído, mas aquele <P_Yellow> Antigonus Notebook </> também desapareceu.",
  [1139165181858048] = "Além disso, você também precisa sair para passear todos os dias, principalmente nas diversas estradas que vão da Welch's House até sua casa.",
  [1139165181857792] = "O velho Neil costumava ser um membro formal, mas está muito velho e não é mais adequado para lidar com casos. Porém, ele não quer descansar e deseja apenas fazer companhia a documentos e livros.",
  [1139165182246144] = "Melissa e eu não temos pressa, mas você realmente precisa disso.",
  [1139165181857280] = "Hoje é seu primeiro dia de trabalho, então você pode primeiro se familiarizar com as coisas.",
  [1139165181919488] = "Alguns fios de cabelo, não tenho certeza se isso conta como ‘algo ruim’.",
  [1139165181841664] = "A cama é dura como uma rocha; Não estou muito acostumado com isso.",
  [1139165182708992] = "Fui eu quem ativou o ritual maligno? Achei que se encontrasse os três itens, poderia escapar.",
  [1139165182586112] = "Onde é isso?",
  [1139165182444800] = "Voltei!",
  [1139165182314752] = "<P_Heart> (O Capitão e os outros...) </>",
  [1139165182296320] = "Por favor, ajude-me a dizer-lhe que não importa o que aconteça, enquanto estivermos juntos, poderemos viver bem... Devemos viver bem.",
  [1139165181855488] = "Huh? Quem é você?",
  [1139165181855232] = "Assim que nossa loja abrir, você estará convidado a nos visitar. Nós lhe daremos um lindo desconto.",
  [1139165181854976] = "Você realmente é uma pessoa gentil e prestativa, mas já teve problemas suficientes, acho que podemos resolver isso.",
  [1139165181854720] = "Você precisa de ajuda?",
  [1139165181854464] = "Pagamos apenas o depósito, precisamos recuperar o dinheiro o mais rápido possível. É raro que o antigo dono da loja nos dê um preço tão bom.",
  [1139165181854208] = "Fale primeiro com Ray corretamente, depois leve-o para pedir desculpas a Ethan e aos outros! Tudo bem se você deixá-los bater em Ray para desabafar sua raiva!",
  [1139165181853952] = "Ele falou algo muito excessivo para nós, e brigamos... Não foi só o Ethan e os outros, eu fiquei com muita raiva também!",
  [1139165181853696] = "Mas recentemente, não sei o que aconteceu com Riel, de repente ele perdeu o interesse em abrir a loja.",
  [1139165181853440] = "Então discutimos isso com Ethan e os outros, fizemos um empréstimo juntos e queríamos alugar esta loja.",
  [1139165181853184] = "Ray herdou o artesanato em joias de seu pai e também estou interessado em administrar uma loja. Queríamos nos livrar do mesquinho dono da fábrica e encontrar outra maneira de ganhar a vida.",
  [1139165181852928] = "A atitude deles para com você agora dificilmente poderia ser chamada de maravilhosa.",
  [1139165181852672] = "...Pensando assim, o passado também não foi tão bonito; o que era lindo eram só eles.",
  [1139165181852416] = "Pensando agora, aquela foi realmente uma época maravilhosa... embora o dono da fábrica fosse mesquinho e o trabalho fosse pesado...",
  [1139165181852160] = "Riel disse que “Dragon Hunter” significa coragem e unidade, então sempre nos chamamos assim.",
  [1139165181851904] = "Esse nome é estranho? Mas não somos uma gangue clandestina, apenas um pequeno grupo de amigos reunidos.",
  [1139165181851648] = "Ele é meu noivo, nós dois éramos membros da gangue Dragon Hunter.",
  [1139165181851392] = "Assim que eu resolver esses problemas com <P_Yellow> Riel </>, com certeza irei agradecer juntos, Sr.",
  [1139165181851136] = "Meu nome é Klein Moretti, moro perto.",
  [1139165181850880] = "Ethan e os outros perdem a razão quando ficam impulsivos. Obrigado por agora, posso perguntar quem você é?",
  [1139165181850624] = "<P_Heart> (De repente ela se recompôs...) </>",
  [1139165181850368] = "Agora não é hora de chorar, controle-se, Alice!",
  [1139165181850112] = "Huh? Esse...",
  [1139165181849856] = "Tivemos alguns mal-entendidos, então...",
  [1139165181849600] = "Desculpe, na verdade somos parceiros... Ethan e eu trabalhávamos juntos na fábrica.",
  [1139165181849344] = "Como eles são chamados... Gangue de Caçadores de Dragões?",
  [1139165181849088] = "Há algo em que eu possa ajudar? Quero dizer, eles não parecem meros bandidos aqui para coletar dinheiro de proteção.",
  [1139165181848832] = "Vou bem obrigado...",
  [1139165181848576] = "Você está bem?",
  [1139165181848320] = "Tratar uma senhora assim é realmente indelicado.",
  [1139165181848064] = "Eu disse que só queremos dinheiro agora!",
  [1139165181847808] = "Ethan, me escute, nós realmente queremos abrir nossa própria loja...",
  [1139165181847552] = "<P_Heart> (Tão feroz... devo chamar a polícia primeiro...) </>",
  [1139165181847296] = "Não é da sua conta, se perca!",
  [1139165181847040] = "Senhora, esses clientes são da joalheria? Você precisa de alguma ajuda?",
  [1139165181846784] = "Ele já fugiu com nosso dinheiro!",
  [1139165181846528] = "Que tipo de pessoa? Alguém que nos despreza? Alguém que nos despreza? Alguém que vira as costas depois de pegar o dinheiro?",
  [1139165181846272] = "Riel não é esse tipo de pessoa!",
  [1139165181846016] = "Alice, você ainda não entendeu? Todos nós fomos enganados por aquele bastardo!",
  [1139165181845760] = "Pessoal, acalmem-se, ouçam minha explicação...",
  [1139165181845504] = "Isso está decidido. Agora, devo ir primeiro para a Blackthorn Company.",
  [1139165181844736] = "A entrevista para um professor da Universidade de Tingen é hoje. Embora eu tenha decidido ingressar no Vigias Noturnos , ainda preciso ir à universidade para cancelar a entrevista.",
  [1139165181844224] = "Se ingressar no Vigias Noturnos não der certo, ainda posso ir direto para a universidade para a entrevista!",
  [1139165181843968] = "Afinal, foi apenas uma questão de educação, foi uma oportunidade de trabalho recomendada pelo Mentor Cohen.",
  [1139165181843712] = "A entrevista para um professor da <P_Yellow> Universidade de Tingen </> também é hoje. Embora eu tenha decidido ingressar no Vigias Noturnos, ainda preciso ir à universidade para cancelar a entrevista.",
  [1139165181843456] = "Dunn disse... vá para 36 Zoutland Street, 2º andar, <P_Yellow> Blackthorn Security Company </> para encontrá-lo.",
  [1139165181843200] = "Em todos os aspectos, aderir ao Vigias Noturnos é a melhor escolha nesta fase.",
  [1139165181842944] = "Já que decidi, não hesitarei mais.",
  [1139165181842688] = "Deixe-me pensar, hoje eu deveria...",
  [1139094851831808] = "Aproveite devagar",
  [1139094851831552] = "Vá rápido",
  [1139094851831296] = "Retire o projeto",
  [1139094851830784] = "Pergunte sobre o Capitão Frye",
  [1139094851830528] = "Bambu Capítulo 5 ocupado",
  [1139094851830272] = "Preocupe-se com a condição dos cidadãos",
  [1139094851830016] = "Bilhete de cabine",
  [1139094851829760] = "Bilhete de convés",
  [1139094851829504] = "Fale sobre Backlund",
  [1139094851829248] = "Fale sobre Roselle",
  [1139094851828992] = "Fale sobre o café",
  [1139094851828736] = "Pergunte sobre o método para despertar o Imperador",
  [1139094851828224] = "Beba um café para se acalmar",
  [1139094851827968] = "Sobre a época",
  [1139094851827712] = "Sobre Blackthorn",
  [1139094851827456] = "Sobre aquele par de irmãos",
  [1139094851826688] = "Fale sobre o significado de guardar",
  [1139094851826432] = "Fale sobre a corrupção no meu corpo",
  [1139094851826176] = "Fale sobre a crise em Tingen",
  [1139094851825920] = "Aproxime-se de Leonardo",
  [1139094851825664] = "Mostre o espelho de cobre",
  [1139094851825152] = "Sair diretamente",
  [1139094851824896] = "Dica 10 Almas",
  [1139094851824640] = "Dica 5 Almas",
  [1139094851824384] = "Dica 1 Soule",
  [1139094851824128] = "Longo-Longo-Longo-Curto",
  [1139094851823872] = "Longo-Longo-Curto-Longo",
  [1139094851823616] = "Longo-Curto-Longo-Longo",
  [1139094851823360] = "Curto-Longo-Longo-Longo",
  [1139094851823104] = "Leitura terminada",
  [1139094851822848] = "Leia a terceira página do diário de Roselle",
  [1139094851822592] = "Leia a segunda página do diário de Roselle",
  [1139094851822336] = "Verifique a hora",
  [1139094851822080] = "Terminar a reunião",
  [1139094851821824] = "Experimente o encantamento",
  [1139094851821568] = "Leia a primeira página do diário de Roselle",
  [1139094851821312] = "Pergunte sobre o diário de Roselle",
  [1139094851821056] = "O tolo que não pertence a esta época",
  [1139094851820800] = "O tolo de outro mundo",
  [1139094851820544] = "Não, não",
  [1139094851820288] = "Nada",
  [1139094851820032] = "Você e Dunn",
  [1139094851819776] = "Agora mesmo...",
  [1139094851819520] = "Sobre você",
  [1139094851819264] = "Entra Blackthorn",
  [1139094851819008] = "Leia o jornal",
  [1139094851818496] = "Esta pintura...?",
  [1139094851817984] = "Empresa de segurança?",
  [1139094851817728] = "Lembre-se da \"orientação\"",
  [1139094851817472] = "Pense em uma maneira",
  [1139094851816960] = "Retirar",
  [1139094851816192] = "[Lugar] Fruta",
  [1139094851815424] = "[Lugar] Sino",
  [1139094851814912] = "[Local] Cartão de aniversário",
